import glob
import polars as pl
from pathlib import Path

processed_dir = Path("/content/drive/MyDrive/Processed Trading Data")
base_dir = Path("/content/drive/MyDrive/Trading Data")
global_out_file = processed_dir / "global_features_daily.parquet"

print("Processing 5m Global CFD Data for Directional Momentum...")

# Find the global data file
global_files = glob.glob(str(base_dir / "global_data_5m_*.csv"))
if not global_files:
    raise FileNotFoundError("Could not find global_data_5m_*.csv in Trading Data folder.")

raw_global_file = global_files[0]

# Load and strictly handle timezones (UTC -> IST)
global_df = (
    pl.scan_csv(raw_global_file)
    .with_columns([
        pl.col("timestamp").str.strptime(pl.Datetime, "%Y-%m-%d %H:%M:%S")
        .dt.replace_time_zone("UTC")
        .dt.convert_time_zone("Asia/Kolkata")
    ])
    .with_columns([
        pl.col("timestamp").dt.date().alias("Date"),
        pl.col("timestamp").dt.time().alias("Time")
    ])
    .collect()
)

# Extract prices at the exact boundaries with robust minute-filtering
daily_global = (
    global_df
    .filter((pl.col("Time") >= pl.time(9, 0)) & (pl.col("Time") <= pl.time(15, 30)))
    .group_by(["symbol", "Date"])
    .agg([
        # Safely grab the first tick on or after 9:00 AM for the delayed Overnight anchor
        pl.col("open").filter(pl.col("Time") >= pl.time(9, 0)).first().alias("Open_0900"),

        # Safely grab the first tick on or after 9:15 AM for the Intraday anchor
        pl.col("open").filter(pl.col("Time") >= pl.time(9, 15)).first().alias("Open_0915"),

        # Safely grab the last tick before or at 15:30 for the Close
        pl.col("close").filter(pl.col("Time") <= pl.time(15, 30)).last().alias("Close_1530")
    ])
    .sort(["symbol", "Date"])
    .with_columns([
        # Intraday Drift: Day T's market open (9:15) to Day T's close (15:30)
        (pl.col("Close_1530") / pl.col("Open_0915")).log().alias("Intraday_Drift"),

        # [MODIFIED ALIGNMENT & TIME]: Overnight Momentum leading into Day T+1
        # Calculated from Day T Close (15:30) to Day T+1 Pre-Open (09:00 AM).
        # Shifted (-1) to sit safely on Day T's row for 9:16 AM live execution.
        (pl.col("Open_0900").shift(-1) / pl.col("Close_1530")).log().over("symbol").alias("Overnight_Momentum")
    ])
)

# Pivot the data so each symbol becomes a feature column
global_features_df = daily_global.pivot(
    index="Date",
    on="symbol",
    values=["Intraday_Drift", "Overnight_Momentum"]
)

global_features_df.write_parquet(global_out_file)
print(f"Saved Morning-Aligned Global Macro Features (9:00 AM Delay Adjusted): {global_out_file}")

import polars as pl
from pathlib import Path
import gc

processed_dir = Path("/content/drive/MyDrive/Processed Trading Data")


def compute_options_features(opt_path: Path, out_path: Path, index_name: str) -> None:
    print(f"\n{'='*50}")
    print(f"Computing Options Features: {index_name}")
    print(f"{'='*50}")

    lf_opt = pl.scan_parquet(opt_path).with_columns([
        pl.col("delta").cast(pl.Float64, strict=False),
        pl.col("IV").cast(pl.Float64, strict=False),
        pl.col("gamma").cast(pl.Float64, strict=False),
        pl.col("OI").cast(pl.Float64, strict=False),
        pl.col("LotSize").cast(pl.Float64, strict=False),
        pl.col("SpotPrice").cast(pl.Float64, strict=False),
    ])

    # ── 1. 25-Delta Put IV ────────────────────────────────────────────────────
    print("  [1] Extracting 25-delta IVs...")
    put_25d = (
        lf_opt.filter(pl.col("Type").is_in(["P", "PE"]))
        .drop_nulls(subset=["delta", "IV"])
        .with_columns((pl.col("delta").abs() - 0.25).abs().alias("delta_dist"))
        .sort(["Datetime", "delta_dist"])
        .group_by("Datetime")
        .first()
        .select([pl.col("Datetime").alias("Date"), pl.col("IV").alias("Put_IV_25d")])
    )

    # ── 2. 25-Delta Call IV ───────────────────────────────────────────────────
    call_25d = (
        lf_opt.filter(pl.col("Type").is_in(["C", "CE"]))
        .drop_nulls(subset=["delta", "IV"])
        .with_columns((pl.col("delta").abs() - 0.25).abs().alias("delta_dist"))
        .sort(["Datetime", "delta_dist"])
        .group_by("Datetime")
        .first()
        .select([pl.col("Datetime").alias("Date"), pl.col("IV").alias("Call_IV_25d")])
    )

    # ── 3. GEX per day ────────────────────────────────────────────────────────
    # Formula: Σ signed_gamma × OI × LotSize × SpotPrice² / 100
    #
    # Data source: EOD options snapshot (closing OI, closing SpotPrice, EOD greeks).
    # Timing: GEX on day T reflects dealer gamma positioning carrying INTO day T+1.
    # At 9:10 AM on T+1, all of day T's EOD data is known — no leakage.
    #
    # Sign convention (dealers assumed short options, standard):
    #   Calls contribute +gamma: dealer bought calls → they are long gamma on calls.
    #   Puts  contribute -gamma: dealer bought puts  → they are long gamma on puts,
    #     but in the aggregate GEX formula, puts reduce net GEX.
    #   Net positive GEX → dealers long gamma → sell rallies/buy dips → vol suppressed.
    #   Net negative GEX → dealers short gamma → amplify moves → vol elevated.
    print("  [2] Computing GEX...")
    gex_lf = (
        lf_opt
        .drop_nulls(subset=["gamma", "OI", "LotSize", "SpotPrice"])
        .with_columns([
            pl.when(pl.col("Type").is_in(["C", "CE"]))
              .then(pl.col("gamma"))
              .otherwise(-pl.col("gamma"))
              .alias("signed_gamma"),
        ])
        .with_columns([
            (
                pl.col("signed_gamma")
                * pl.col("OI")
                * pl.col("LotSize")
                * pl.col("SpotPrice").pow(2)
                / 100.0
            ).alias("gex_contrib")
        ])
        .group_by("Datetime")
        .agg(pl.col("gex_contrib").sum().alias("GEX_Raw"))
        .rename({"Datetime": "Date"})
        .sort("Date")
    )

    # ── 4. Rolling GEX features ───────────────────────────────────────────────
    # Collect required for stateful rolling ops in Polars.
    print("  [3] Computing GEX rolling features...")
    gex_df = gex_lf.collect()

    gex_df = gex_df.with_columns([
        # min_samples (renamed from min_periods in Polars ≥1.21)
        pl.col("GEX_Raw").rolling_mean(window_size=20, min_samples=5).alias("_gex_mean"),
        pl.col("GEX_Raw").rolling_std(window_size=20, min_samples=5).alias("_gex_std"),
    ]).with_columns([
        # GEX_Zscore: signed continuous magnitude. Clips at ±3.
        # Used directly for the GEX_x_DTE_R0 interaction in Cell 1
        # (sign matters there: positive = pin force, negative = amplification).
        ((pl.col("GEX_Raw") - pl.col("_gex_mean")) /
         (pl.col("_gex_std") + 1e-6)
        ).clip(-3.0, 3.0).alias("GEX_Zscore"),
    ]).with_columns([
        # GEX_Pos: how strongly positive GEX is. Zero when GEX is negative.
        # Encodes vol-suppressing regime magnitude independently.
        # Range: [0, 3]. Large = strong dealer long-gamma pin force.
        pl.col("GEX_Zscore").clip(lower_bound=0.0).alias("GEX_Pos"),

        # GEX_Neg: how strongly negative GEX is (as a positive number). Zero when GEX ≥ 0.
        # Encodes vol-amplifying regime magnitude independently.
        # Range: [0, 3]. Large = strong dealer short-gamma amplification force.
        # Stored as positive so the vol gate can apply an independent positive weight.
        (-pl.col("GEX_Zscore")).clip(lower_bound=0.0).alias("GEX_Neg"),
    ]).drop(["_gex_mean", "_gex_std"])

    # ── 5. Merge all features and write ──────────────────────────────────────
    print("  [4] Merging and writing...")
    skew_df = (
        put_25d.join(call_25d, on="Date", how="inner")
        .with_columns(
            (pl.col("Put_IV_25d") - pl.col("Call_IV_25d")).alias("Options_Skew_25d")
        )
        .collect()
        .join(gex_df, on="Date", how="left")
        .sort("Date")
    )

    # Forward-fill GEX gaps (rare missing days where options data absent)
    skew_df = skew_df.with_columns([
        pl.col("GEX_Raw").fill_null(strategy="forward"),
        pl.col("GEX_Zscore").fill_null(strategy="forward"),
        pl.col("GEX_Pos").fill_null(strategy="forward"),
        pl.col("GEX_Neg").fill_null(strategy="forward"),
    ])

    skew_df.write_parquet(out_path)

    print(f"  Saved : {out_path}")
    print(f"  Shape : {skew_df.shape}")
    print(f"  Columns: {skew_df.columns}")
    print(f"  GEX_Raw   : {skew_df['GEX_Raw'].min():.3e} → {skew_df['GEX_Raw'].max():.3e}")
    print(f"  GEX_Zscore: {skew_df['GEX_Zscore'].min():.3f} → {skew_df['GEX_Zscore'].max():.3f}")
    print(f"  GEX_Pos   : {skew_df['GEX_Pos'].min():.3f} → {skew_df['GEX_Pos'].max():.3f}")
    print(f"  GEX_Neg   : {skew_df['GEX_Neg'].min():.3f} → {skew_df['GEX_Neg'].max():.3f}")
    _pos_days = int((skew_df['GEX_Pos'] > 0).sum())
    _neg_days = int((skew_df['GEX_Neg'] > 0).sum())
    print(f"  GEX regime: {_pos_days} positive days | {_neg_days} negative days "
          f"| {len(skew_df) - _pos_days - _neg_days} zero days")


# ── Execution ─────────────────────────────────────────────────────────────────
compute_options_features(
    opt_path  = processed_dir / "nifty50_opt.parquet",
    out_path  = processed_dir / "nifty_options_skew.parquet",
    index_name= "NIFTY",
)
gc.collect()

compute_options_features(
    opt_path  = processed_dir / "banknifty_opt.parquet",
    out_path  = processed_dir / "banknifty_options_skew.parquet",
    index_name= "BANKNIFTY",
)
gc.collect()

import polars as pl
from pathlib import Path
import pandas as pd

processed_dir = Path("/content/drive/MyDrive/Processed Trading Data")

# ==========================================
# FILE PATH VARIABLES
# ==========================================

# --- Common Files ---
vix_5m_file = processed_dir / "indiavix_5m.parquet"
global_feat_file = processed_dir / "global_features_daily.parquet"

# --- NIFTY Files ---
nifty_5m_file = processed_dir / "nifty50_5m.parquet"
nifty_opt_file = processed_dir / "nifty50_opt.parquet"
nifty_skew_feat_file = processed_dir / "nifty_options_skew.parquet"
nifty_master_out_file = processed_dir / "nifty_master_file.parquet"

# --- BANKNIFTY Files ---
banknifty_5m_file = processed_dir / "banknifty_5m.parquet"
banknifty_opt_file = processed_dir / "banknifty_opt.parquet"
banknifty_skew_feat_file = processed_dir / "banknifty_options_skew.parquet"
banknifty_master_out_file = processed_dir / "banknifty_master_file.parquet"


# ==========================================
# PROCESSING LOGIC (Function)
# ==========================================
def process_index_data(
    index_name,
    spot_5m_path,
    opt_path,
    skew_path,
    vix_path,
    global_path,
    out_path
):
    print(f"\n{'='*50}")
    print(f"Processing Pipeline For: {index_name}")
    print(f"{'='*50}")

    print(f"1. Compressing 5-minute {index_name} data into Daily Features...")
    lf_spot_5m = (
        pl.scan_parquet(spot_5m_path)
        .sort("Datetime")
        .with_columns([
            pl.col("Datetime").dt.date().alias("Date"),
            (pl.col("Close") / pl.col("Close").shift(1)).log().alias("log_return_5m"),
            (pl.col("Close") - pl.col("Close").shift(1)).abs().alias("abs_price_change_5m")
        ])
    )

    daily_spot = (
        lf_spot_5m
        .group_by("Date")
        .agg([
            pl.col("Open").first().alias("Spot_Open"),
            pl.col("High").max().alias("Spot_High"),
            pl.col("Low").min().alias("Spot_Low"),
            pl.col("Close").last().alias("Spot_Close"),
            pl.col("Volume").sum().alias("Spot_Volume"),
            (pl.col("log_return_5m").std() * ((75 * 252) ** 0.5)).alias("Realized_Vol_Ann"),
            pl.col("abs_price_change_5m").sum().alias("Path_Length")
        ])
        .with_columns([
            ( (pl.col("Spot_Close") - pl.col("Spot_Open")).abs() /
              pl.when(pl.col("Path_Length") == 0).then(1.0).otherwise(pl.col("Path_Length"))
            ).alias("Trend_Strength")
        ])
    )

    print("2. Extracting Macro Sentiment (PCR) from Options Data...")
    lf_opt = pl.scan_parquet(opt_path)
    daily_options = (
        lf_opt
        .group_by("Datetime")
        .agg([
            pl.col("Volume").filter(pl.col("Type").is_in(["C", "CE"])).sum().alias("Call_Volume"),
            pl.col("Volume").filter(pl.col("Type").is_in(["P", "PE"])).sum().alias("Put_Volume"),
            pl.col("OI").filter(pl.col("Type").is_in(["C", "CE"])).sum().alias("Call_OI"),
            pl.col("OI").filter(pl.col("Type").is_in(["P", "PE"])).sum().alias("Put_OI"),
        ])
        .with_columns([
            (pl.col("Put_OI") / pl.col("Call_OI").fill_null(1.0)).alias("PCR_OI"),
            (pl.col("Put_Volume") / pl.col("Call_Volume").fill_null(1.0)).alias("PCR_Volume")
        ])
        .rename({"Datetime": "Date"})
    )

    print("3. Extracting Daily VIX Close...")
    lf_vix_5m = pl.scan_parquet(vix_path)
    daily_vix = (
        lf_vix_5m
        .with_columns(pl.col("Datetime").dt.date().alias("Date"))
        .group_by("Date")
        .agg([
            pl.col("Close").last().alias("VIX_Close")
        ])
    )

    print("4. Loading Global & Skew Features...")
    lf_global = pl.scan_parquet(global_path)
    lf_skew = pl.scan_parquet(skew_path)

    print("5. Merging Master Dataset and Generating Forward Targets...")
    master_lf = (
        daily_spot
        .join(daily_vix, on="Date", how="left")
        .join(daily_options, on="Date", how="left")
        .join(lf_global, on="Date", how="left")
        .join(lf_skew, on="Date", how="left")
        .sort("Date")
        .with_columns([
            (pl.col("Spot_Close").shift(-1) / pl.col("Spot_Close")).log().alias("Target_Ret_1D"),
            (pl.col("Spot_Close").shift(-5) / pl.col("Spot_Close")).log().alias("Target_Ret_5D"),
            ((pl.col("VIX_Close") / 100.0) - pl.col("Realized_Vol_Ann")).alias("VRP_Daily")
        ])
        .drop_nulls(subset=["Target_Ret_1D", "Target_Ret_5D"])
        .with_columns(pl.all().fill_null(strategy="forward"))
        # --- NEW TRAILING RETURN LOGIC INSERTED HERE ---
        .drop("Spot_Volume", strict=False) # Drop if exists
        .with_columns([
            (pl.col("Spot_Close") / pl.col("Spot_Close").shift(5)).log().alias("Trailing_Ret_5D")
        ])
        .drop_nulls() # Drop the first 5 days that now have NaNs
    )

    master_lf.sink_parquet(out_path)

    # Load to memory for final inspection
    final_df = pl.read_parquet(out_path)

    print(f"\nSaved to: {out_path}")
    print(f"Dataset Shape: {final_df.shape}")
    print(f"\n{index_name} Dataset Head:")
    pd.set_option('display.max_columns', None)
    print(final_df.head().to_pandas())

    return final_df


# ==========================================
# EXECUTION
# ==========================================

# 1. Process NIFTY
nifty_df = process_index_data(
    index_name="NIFTY",
    spot_5m_path=nifty_5m_file,
    opt_path=nifty_opt_file,
    skew_path=nifty_skew_feat_file,
    vix_path=vix_5m_file,
    global_path=global_feat_file,
    out_path=nifty_master_out_file
)

# 2. Process BANKNIFTY
banknifty_df = process_index_data(
    index_name="BANKNIFTY",
    spot_5m_path=banknifty_5m_file,
    opt_path=banknifty_opt_file,
    skew_path=banknifty_skew_feat_file,
    vix_path=vix_5m_file,
    global_path=global_feat_file,
    out_path=banknifty_master_out_file
)

"""## 2. Model Architecture

Out-of-Sample Accuracy Report

- Target Confidence Interval : 80%
- Total Test Days Evaluated  : 230
- 1-Day Ahead Hit Rate       : 70.87% (163/230)
- 5-Day Ahead Hit Rate       : 81.74% (188/230)
"""

import pandas as pd
import polars as pl
import numpy as np
import matplotlib.pyplot as plt
import torch
from torch.utils.data import Dataset, DataLoader
from sklearn.preprocessing import StandardScaler
from pathlib import Path

# 1. Load Data and Fix Missing Import
processed_dir = Path("/content/drive/MyDrive/Processed Trading Data")
master_out_file = processed_dir / "master_daily_features.parquet"
df = pl.read_parquet(master_out_file)

# We one-hot encode Regime_State safely using pandas
df_pd = df.to_pandas()
df_pd = pd.get_dummies(df_pd, columns=["Regime_State"], drop_first=False, dtype=float)

# 2. Define Features and Targets
# Explicitly drop absolute price columns. The model must learn from dynamics, not prices.
base_features = [
    'Realized_Vol_Ann', 'Path_Length', 'Trend_Strength', 'VIX_Close',
    'PCR_OI', 'PCR_Volume', 'VRP_Daily', 'Trailing_Ret_5D'
]
regime_cols = [c for c in df_pd.columns if 'Regime_State_' in c]
feature_cols = base_features + regime_cols
target_cols = ['Target_Ret_1D', 'Target_Ret_5D']

# Extract raw arrays
X_raw = df_pd[feature_cols].values.astype(np.float32)
y_raw = df_pd[target_cols].values.astype(np.float32)
dates_raw = pd.to_datetime(df_pd['Date']).values

# 3. The Sequence Dataset Class
class NiftySequenceDataset(Dataset):
    def __init__(self, X, y, sequence_length=21):
        self.X = X
        self.y = y
        self.sequence_length = sequence_length

    def __len__(self):
        return len(self.X) - self.sequence_length + 1

    def __getitem__(self, idx):
        # Grab a 21-day window of features
        x_window = self.X[idx : idx + self.sequence_length]
        # Target aligns with the last day of the window
        y_target = self.y[idx + self.sequence_length - 1]
        return torch.tensor(x_window), torch.tensor(y_target)

# 4. Purged Walk-Forward Splitter
def create_purged_walk_forward_splits(total_length, train_size=1000, test_size=250, purge_gap=5):
    """
    Creates indices for Walk-Forward CV with a strictly enforced purge gap.
    purge_gap = 5 ensures the T+5 target from the train set doesn't overlap with the test set.
    """
    splits = []
    start_idx = 0
    while start_idx + train_size + purge_gap + test_size <= total_length:
        train_start = start_idx
        train_end = start_idx + train_size

        test_start = train_end + purge_gap
        test_end = test_start + test_size

        splits.append({
            'train': (train_start, train_end),
            'test': (test_start, test_end)
        })
        # Roll the window forward by the test_size
        start_idx += test_size
    return splits

splits = create_purged_walk_forward_splits(len(X_raw))

# 5. Visualize the Splits to Verify Zero Leakage
fig, ax = plt.subplots(figsize=(12, max(4, len(splits)*0.8)))
for i, split in enumerate(splits):
    ax.plot([split['train'][0], split['train'][1]], [i, i], color='blue', linewidth=6, label='Train' if i==0 else "")
    # The empty space between blue and orange is your Purge Gap
    ax.plot([split['test'][0], split['test'][1]], [i, i], color='orange', linewidth=6, label='Test' if i==0 else "")

ax.set_title("Purged Walk-Forward Validation Splits (Zero Leakage Ensured)", fontsize=14)
ax.set_xlabel("Dataset Index (Chronological Days)")
ax.set_ylabel("Split Iteration")
ax.set_yticks(range(len(splits)))
ax.legend(loc="upper right")
plt.grid(axis='x', alpha=0.3)
plt.tight_layout()
plt.show()

print(f"Created {len(splits)} isolated Walk-Forward splits.")

import torch.nn as nn
import torch.nn.functional as F
import math

class PositionalEncoding(nn.Module):
    def __init__(self, d_model, max_len=100):
        super(PositionalEncoding, self).__init__()
        pe = torch.zeros(max_len, d_model)
        position = torch.arange(0, max_len, dtype=torch.float).unsqueeze(1)
        div_term = torch.exp(torch.arange(0, d_model, 2).float() * (-math.log(10000.0) / d_model))
        pe[:, 0::2] = torch.sin(position * div_term)
        pe[:, 1::2] = torch.cos(position * div_term)
        self.register_buffer('pe', pe.unsqueeze(0)) # Shape: (1, max_len, d_model)

    def forward(self, x):
        # x shape: (Batch, Seq_len, Features)
        return x + self.pe[:, :x.size(1), :]

class TransformerMDN(nn.Module):
    def __init__(self, input_dim, seq_len=21, d_model=32, nhead=4, num_layers=2, dropout=0.3, num_targets=2, num_mixtures=3):
        super(TransformerMDN, self).__init__()
        self.num_targets = num_targets
        self.num_mixtures = num_mixtures

        # 1. Input Projection & Positional Encoding
        self.input_projection = nn.Linear(input_dim, d_model)
        self.pos_encoder = PositionalEncoding(d_model, max_len=seq_len)

        # 2. Small Transformer Encoder
        encoder_layer = nn.TransformerEncoderLayer(
            d_model=d_model,
            nhead=nhead,
            dim_feedforward=128,
            dropout=dropout,
            batch_first=True
        )
        self.transformer_encoder = nn.TransformerEncoder(encoder_layer, num_layers=num_layers)

        # 3. MDN Head (Outputs pi, mu, sigma for each target and mixture)
        # We flatten the transformer output or take the last sequence step. We'll take the last step.
        self.mdn_hidden = nn.Linear(d_model, 32)

        # Output dimensions: (targets * mixtures)
        self.pi_layer = nn.Linear(32, num_targets * num_mixtures)
        self.mu_layer = nn.Linear(32, num_targets * num_mixtures)
        self.sigma_layer = nn.Linear(32, num_targets * num_mixtures)

    def forward(self, x):
        # x shape: (Batch, Seq_len, Features)
        x = self.input_projection(x)
        x = self.pos_encoder(x)

        # Pass through Transformer
        out = self.transformer_encoder(x)

        # Take the output of the final time step (the "present" day)
        last_step_out = out[:, -1, :]

        # Pass to MDN Head
        hidden = F.relu(self.mdn_hidden(last_step_out))

        # Compute mixture parameters
        pi_logits = self.pi_layer(hidden).view(-1, self.num_targets, self.num_mixtures)
        mu = self.mu_layer(hidden).view(-1, self.num_targets, self.num_mixtures)
        sigma_raw = self.sigma_layer(hidden).view(-1, self.num_targets, self.num_mixtures)

        # Softmax for probabilities (must sum to 1)
        pi = F.softmax(pi_logits, dim=-1)
        # Exponential + small epsilon for standard deviation (must be strictly positive)
        sigma = torch.exp(sigma_raw) + 1e-6

        return pi, mu, sigma

# Instantiate to check shapes
model = TransformerMDN(input_dim=len(feature_cols))
print(f"Model instantiated. Total parameters: {sum(p.numel() for p in model.parameters() if p.requires_grad)}")

import torch.optim as optim

def mdn_nll_loss(pi, mu, sigma, target):
    """
    Negative Log-Likelihood Loss for Mixture Density Networks.
    target shape: (Batch, num_targets)
    pi, mu, sigma shape: (Batch, num_targets, num_mixtures)
    """
    # Expand target to match mixture dimension: (Batch, num_targets, 1)
    target = target.unsqueeze(-1)

    # Create Normal distributions
    normal_dist = torch.distributions.Normal(mu, sigma)

    # Calculate log probabilities of the target given each mixture
    log_prob_normal = normal_dist.log_prob(target)

    # Log-Sum-Exp trick for numerical stability to prevent NaN losses
    log_pi = torch.log(pi + 1e-8)
    log_sum_exp = torch.logsumexp(log_pi + log_prob_normal, dim=-1)

    # Average NLL across batches and targets
    nll = -log_sum_exp.mean()
    return nll

# Hyperparameters
SEQ_LEN = 21
BATCH_SIZE = 64
EPOCHS = 30 # Kept low to prevent overfitting our microscopic dataset
LR = 0.001

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Training on: {device}")

out_of_sample_losses = []

for split_idx, split in enumerate(splits):
    print(f"\n--- Training Walk-Forward Split {split_idx + 1}/{len(splits)} ---")

    # 1. Isolate the data for this specific split
    tr_start, tr_end = split['train']
    te_start, te_end = split['test']

    X_train_raw, y_train_raw = X_raw[tr_start:tr_end], y_raw[tr_start:tr_end]
    X_test_raw, y_test_raw = X_raw[te_start:te_end], y_raw[te_start:te_end]

    # 2. Strict Scaling (Fit on Train ONLY) -> Cast back to float32 for PyTorch
    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train_raw).astype(np.float32)
    X_test_scaled = scaler.transform(X_test_raw).astype(np.float32)

    # 3. Create PyTorch Datasets (Corrected argument name: sequence_length)
    train_dataset = NiftySequenceDataset(X_train_scaled, y_train_raw, sequence_length=SEQ_LEN)
    test_dataset = NiftySequenceDataset(X_test_scaled, y_test_raw, sequence_length=SEQ_LEN)

    train_loader = DataLoader(train_dataset, batch_size=BATCH_SIZE, shuffle=True, drop_last=True)
    test_loader = DataLoader(test_dataset, batch_size=BATCH_SIZE, shuffle=False)

    # 4. Initialize a fresh model for each split
    model = TransformerMDN(input_dim=len(feature_cols), seq_len=SEQ_LEN).to(device)
    optimizer = optim.AdamW(model.parameters(), lr=LR, weight_decay=1e-4)

    # 5. Training Loop
    for epoch in range(EPOCHS):
        model.train()
        epoch_loss = 0.0
        for X_batch, y_batch in train_loader:
            X_batch, y_batch = X_batch.to(device), y_batch.to(device)

            optimizer.zero_grad()
            pi, mu, sigma = model(X_batch)
            loss = mdn_nll_loss(pi, mu, sigma, y_batch)
            loss.backward()

            # Gradient clipping to prevent exploding gradients
            torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
            optimizer.step()

            epoch_loss += loss.item()

        if (epoch+1) % 10 == 0 or epoch == 0:
            print(f"Epoch {epoch+1}/{EPOCHS} | Train NLL Loss: {epoch_loss/len(train_loader):.4f}")

    # 6. Evaluation (Strictly Out-of-Sample)
    model.eval()
    test_loss = 0.0
    with torch.no_grad():
        for X_batch, y_batch in test_loader:
            X_batch, y_batch = X_batch.to(device), y_batch.to(device)
            pi, mu, sigma = model(X_batch)
            loss = mdn_nll_loss(pi, mu, sigma, y_batch)
            test_loss += loss.item()

    avg_test_loss = test_loss / len(test_loader)
    out_of_sample_losses.append(avg_test_loss)
    print(f"-> Split {split_idx + 1} Out-of-Sample NLL Loss: {avg_test_loss:.4f}")

print(f"\nAverage Out-of-Sample NLL across all splits: {np.mean(out_of_sample_losses):.4f}")

