import torch
import numpy as np
import polars as pl

def predict_nifty_range(model, scaler, X_raw, df_pd, seq_len=21, confidence_interval=0.80):
    """
    Takes the most recent 21 days, predicts the return distribution,
    and translates it into actionable NIFTY spot price ranges.
    """
    model.eval()

    # 1. Isolate the latest 21 days from our raw feature array
    latest_window_raw = X_raw[-seq_len:]

    # Get the latest actual NIFTY closing price to anchor our predictions
    latest_close = df_pd['Spot_Close'].iloc[-1]
    latest_date = df_pd['Date'].iloc[-1]

    # 2. Scale the data using the fit scaler from Split 4
    latest_window_scaled = scaler.transform(latest_window_raw).astype(np.float32)

    # Convert to tensor and add a batch dimension: Shape (1, 21, Features)
    X_tensor = torch.tensor(latest_window_scaled).unsqueeze(0).to(device)

    # 3. Predict the Mixture Parameters
    with torch.no_grad():
        pi, mu, sigma = model(X_tensor)

    pi = pi.cpu().numpy()[0]       # Shape: (Targets, Mixtures)
    mu = mu.cpu().numpy()[0]       # Shape: (Targets, Mixtures)
    sigma = sigma.cpu().numpy()[0] # Shape: (Targets, Mixtures)

    # 4. Simulation for Exact Percentile Extraction
    n_sims = 100000
    results = {}

    targets = {0: "1-Day", 1: "5-Day"}

    print(f"--- NIFTY 50 Inference Report ---")
    print(f"Anchored on Last Close: {latest_close:.2f} (Date: {latest_date})\n")

    for target_idx, target_name in targets.items():
        pi_t = pi[target_idx]
        mu_t = mu[target_idx]
        sigma_t = sigma[target_idx]

        # Randomly choose which Gaussian to draw from based on probabilities (pi)
        chosen_mixtures = np.random.choice(len(pi_t), size=n_sims, p=pi_t)

        # Draw the simulated returns from the chosen Gaussians
        simulated_returns = np.random.normal(loc=mu_t[chosen_mixtures], scale=sigma_t[chosen_mixtures])

        # Translate Log-Returns back to Absolute Spot Prices
        # P_future = P_current * exp(log_return)
        simulated_prices = latest_close * np.exp(simulated_returns)

        # Extract Confidence Intervals (e.g., 80% CI means 10th to 90th percentile)
        lower_tail = (1.0 - confidence_interval) / 2.0
        upper_tail = 1.0 - lower_tail

        p_lower = np.percentile(simulated_prices, lower_tail * 100)
        p_median = np.percentile(simulated_prices, 50)
        p_upper = np.percentile(simulated_prices, upper_tail * 100)

        results[target_name] = {
            "lower": p_lower,
            "median": p_median,
            "upper": p_upper
        }

        print(f"[{target_name} Forecast]")
        print(f"Expected Target (Median) : {p_median:.2f}")
        print(f"{int(confidence_interval*100)}% Confidence Range : {p_lower:.2f} to {p_upper:.2f}")
        print(f"Implied Move             : {((p_median / latest_close) - 1)*100:.2f}%\n")

    return results

# Run the inference engine using the model and scaler from the final Walk-Forward split
inference_results = predict_nifty_range(model, scaler, X_raw, df_pd, seq_len=SEQ_LEN, confidence_interval=0.80)

import matplotlib.pyplot as plt

def plot_price_cone(latest_close, results):
    """
    Plots the projected price ranges for 1D and 5D horizons.
    """
    horizons = [0, 1, 5]

    # Median path
    medians = [latest_close, results["1-Day"]["median"], results["5-Day"]["median"]]

    # Upper and Lower bounds
    uppers = [latest_close, results["1-Day"]["upper"], results["5-Day"]["upper"]]
    lowers = [latest_close, results["1-Day"]["lower"], results["5-Day"]["lower"]]

    plt.figure(figsize=(10, 6))

    # Plot the center line
    plt.plot(horizons, medians, color='blue', marker='o', linewidth=2, label='Expected Path (Median)')

    # Plot the confidence bounds
    plt.plot(horizons, uppers, color='green', linestyle='--', alpha=0.7, label='Upper Bound (90th Pct)')
    plt.plot(horizons, lowers, color='red', linestyle='--', alpha=0.7, label='Lower Bound (10th Pct)')

    # Fill the cone
    plt.fill_between(horizons, lowers, uppers, color='blue', alpha=0.1, label='80% Confidence Zone')

    # Formatting
    plt.axhline(latest_close, color='black', linestyle=':', alpha=0.5, label='Current Price')
    plt.title("NIFTY 50 - Forward Probability Cone", fontsize=14)
    plt.xlabel("Trading Days Ahead", fontsize=12)
    plt.ylabel("Spot Price", fontsize=12)
    plt.xticks([0, 1, 5], ['Today (T+0)', 'Tomorrow (T+1)', 'Next Week (T+5)'])
    plt.legend(loc='upper left')
    plt.grid(alpha=0.3)

    # Annotate prices
    plt.text(5, uppers[-1], f" {uppers[-1]:.0f}", va='bottom', color='green', fontweight='bold')
    plt.text(5, lowers[-1], f" {lowers[-1]:.0f}", va='top', color='red', fontweight='bold')
    plt.text(5, medians[-1], f" {medians[-1]:.0f}", va='center', color='blue', fontweight='bold')

    plt.tight_layout()
    plt.show()

plot_price_cone(df_pd['Spot_Close'].iloc[-1], inference_results)

import numpy as np
import torch
import matplotlib.pyplot as plt

def backtest_probabilistic_accuracy(model, test_loader, confidence_interval=0.80, n_sims=10000):
    """
    Evaluates the model on strictly out-of-sample data to calculate the Coverage Probability.
    Checks how often the actual forward return falls within the predicted confidence bounds.
    """
    model.eval()

    actuals_1d, lowers_1d, uppers_1d = [], [], []
    actuals_5d, lowers_5d, uppers_5d = [], [], []

    lower_tail = (1.0 - confidence_interval) / 2.0
    upper_tail = 1.0 - lower_tail

    print(f"Running Out-of-Sample Backtest on Final Split...")

    with torch.no_grad():
        for X_batch, y_batch in test_loader:
            X_batch_gpu = X_batch.to(device)
            pi, mu, sigma = model(X_batch_gpu)

            # Move to CPU for processing
            pi = pi.cpu().numpy()
            mu = mu.cpu().numpy()
            sigma = sigma.cpu().numpy()
            y_actual = y_batch.numpy()

            batch_size = pi.shape[0]

            for b in range(batch_size):
                # --- 1D Target (Index 0) ---
                pi_1d, mu_1d, sigma_1d = pi[b, 0, :], mu[b, 0, :], sigma[b, 0, :]
                chosen_mix_1d = np.random.choice(len(pi_1d), size=n_sims, p=pi_1d)
                sim_rets_1d = np.random.normal(loc=mu_1d[chosen_mix_1d], scale=sigma_1d[chosen_mix_1d])

                lowers_1d.append(np.percentile(sim_rets_1d, lower_tail * 100))
                uppers_1d.append(np.percentile(sim_rets_1d, upper_tail * 100))
                actuals_1d.append(y_actual[b, 0])

                # --- 5D Target (Index 1) ---
                pi_5d, mu_5d, sigma_5d = pi[b, 1, :], mu[b, 1, :], sigma[b, 1, :]
                chosen_mix_5d = np.random.choice(len(pi_5d), size=n_sims, p=pi_5d)
                sim_rets_5d = np.random.normal(loc=mu_5d[chosen_mix_5d], scale=sigma_5d[chosen_mix_5d])

                lowers_5d.append(np.percentile(sim_rets_5d, lower_tail * 100))
                uppers_5d.append(np.percentile(sim_rets_5d, upper_tail * 100))
                actuals_5d.append(y_actual[b, 1])

    # Calculate Hit Rates (Coverage Probability)
    hits_1d = sum(1 for a, l, u in zip(actuals_1d, lowers_1d, uppers_1d) if l <= a <= u)
    hits_5d = sum(1 for a, l, u in zip(actuals_5d, lowers_5d, uppers_5d) if l <= a <= u)

    total = len(actuals_1d)
    acc_1d = (hits_1d / total) * 100
    acc_5d = (hits_5d / total) * 100

    print("\n--- Out-of-Sample Accuracy Report ---")
    print(f"Target Confidence Interval : {int(confidence_interval * 100)}%")
    print(f"Total Test Days Evaluated  : {total}")
    print(f"1-Day Ahead Hit Rate       : {acc_1d:.2f}% ({hits_1d}/{total})")
    print(f"5-Day Ahead Hit Rate       : {acc_5d:.2f}% ({hits_5d}/{total})\n")

    return actuals_1d, lowers_1d, uppers_1d, actuals_5d, lowers_5d, uppers_5d

# Execute the backtest
a_1d, l_1d, u_1d, a_5d, l_5d, u_5d = backtest_probabilistic_accuracy(
    model, test_loader, confidence_interval=0.80
)

# --- Visualization of the Out-of-Sample Performance ---
def plot_backtest_coverage(actuals, lowers, uppers, title, num_days=100):
    """
    Plots the last 'num_days' of the backtest to visually inspect the bounds.
    """
    plt.figure(figsize=(14, 6))

    # We slice the last 'num_days' to make the chart readable
    x_axis = np.arange(num_days)
    a_slice = actuals[-num_days:]
    l_slice = lowers[-num_days:]
    u_slice = uppers[-num_days:]

    plt.plot(x_axis, a_slice, color='black', marker='o', markersize=4, label='Actual Log Return')
    plt.plot(x_axis, u_slice, color='green', linestyle='--', alpha=0.7, label='Predicted Upper Bound (90th Pct)')
    plt.plot(x_axis, l_slice, color='red', linestyle='--', alpha=0.7, label='Predicted Lower Bound (10th Pct)')

    plt.fill_between(x_axis, l_slice, u_slice, color='blue', alpha=0.1, label='Predicted 80% Confidence Zone')

    plt.axhline(0, color='gray', linestyle=':', alpha=0.5)
    plt.title(f"{title} - Last {num_days} Days Out-of-Sample", fontsize=14)
    plt.xlabel("Days", fontsize=12)
    plt.ylabel("Log Return", fontsize=12)
    plt.legend(loc='upper left')
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

# Plot the 5D results for visual confirmation
plot_backtest_coverage(a_5d, l_5d, u_5d, "5-Day Forecast Backtest")

"""## 3. Complex TFT (GRN) Model with Pinball Loss Function


WEIGHTED ASYMMETRIC TFT Accuracy Report
- Target Confidence Interval : 80% (10th to 90th Percentile)
- Total Test Days Evaluated  : 230
- 1-Day Ahead Hit Rate       : 85.22%
- 1-Day Directional Accuracy : 53.48%
- 1-Day Avg Predicted Range  : 2.57%
----------------------------------------
- 5-Day Ahead Hit Rate       : 79.13%
- 5-Day Directional Accuracy : 47.39%
- 5-Day Avg Predicted Range  : 4.80%

--- Skew Diagnostics (5D) ---
- Average Upside Room        : +2.34%
- Average Downside Risk      : -2.46%

#### Issues -
- Unmasked Bi-Directional Attention
  - Why it's a structural flaw: Because it is unmasked, Day $T-15$ is allowed to "look forward" and pay attention to Day $T$. While this doesn't leak the target, it violates the causal flow of time inside the sequence window. Time-series models perform much better when forced to learn causal dependencies (Day $T$ can look back at $T-15$, but $T-15$ cannot look forward at $T$).The Fix: This is why the upgraded model uses the generate_decay_mask function to apply a strict lower-triangular causal mask to the attention layer.
"""

import pandas as pd
import polars as pl
import numpy as np
import matplotlib.pyplot as plt
import torch
from torch.utils.data import Dataset, DataLoader
from sklearn.preprocessing import StandardScaler
from pathlib import Path

# 1. Load Data
processed_dir = Path("/content/drive/MyDrive/Processed Trading Data")
master_out_file = processed_dir / "master_daily_features.parquet"
df = pl.read_parquet(master_out_file)

# One-hot encode Regime_State safely
df_pd = df.to_pandas()
df_pd = pd.get_dummies(df_pd, columns=["Regime_State"], drop_first=False, dtype=float)

# 2. Define Features and Targets
base_features = [
    'Realized_Vol_Ann', 'Path_Length', 'Trend_Strength', 'VIX_Close',
    'PCR_OI', 'PCR_Volume', 'VRP_Daily', 'Trailing_Ret_5D'
]
regime_cols = [c for c in df_pd.columns if 'Regime_State_' in c]
feature_cols = base_features + regime_cols
target_cols = ['Target_Ret_1D', 'Target_Ret_5D']

X_raw = df_pd[feature_cols].values.astype(np.float32)
y_raw = df_pd[target_cols].values.astype(np.float32)

# 3. Sequence Dataset
class NiftySequenceDataset(Dataset):
    def __init__(self, X, y, sequence_length=21):
        self.X = X
        self.y = y
        self.sequence_length = sequence_length

    def __len__(self):
        return len(self.X) - self.sequence_length + 1

    def __getitem__(self, idx):
        x_window = self.X[idx : idx + self.sequence_length]
        y_target = self.y[idx + self.sequence_length - 1]
        return torch.tensor(x_window), torch.tensor(y_target)

# 4. Purged Walk-Forward Splitter
def create_purged_walk_forward_splits(total_length, train_size=1000, test_size=250, purge_gap=5):
    splits = []
    start_idx = 0
    while start_idx + train_size + purge_gap + test_size <= total_length:
        train_start = start_idx
        train_end = start_idx + train_size
        test_start = train_end + purge_gap
        test_end = test_start + test_size
        splits.append({'train': (train_start, train_end), 'test': (test_start, test_end)})
        start_idx += test_size
    return splits

splits = create_purged_walk_forward_splits(len(X_raw))
print(f"Created {len(splits)} isolated Walk-Forward splits for regularized TFT training.")

import torch.nn as nn
import torch.nn.functional as F
import math
import torch

# --- 1. Quantile (Pinball) Loss ---
def quantile_loss(preds, target, quantiles):
    """
    Computes the Pinball Loss for asymmetric percentile forecasting.
    preds: (Batch, Num_Targets, Num_Quantiles)
    target: (Batch, Num_Targets)
    quantiles: Tensor of quantiles, e.g., [0.10, 0.50, 0.90]
    """
    # Expand targets to match the quantiles dimension: (Batch, Num_Targets, 1)
    target = target.unsqueeze(-1)

    # Calculate the errors
    errors = target - preds

    # Pinball Loss formula: max(q * e, (q - 1) * e)
    losses = torch.max(quantiles * errors, (quantiles - 1.0) * errors)

    # Average across the batch and targets
    return losses.mean()

# --- 2. TFT Core Components ---
class GLU(nn.Module):
    def __init__(self, input_size):
        super().__init__()
        self.fc1 = nn.Linear(input_size, input_size)
        self.fc2 = nn.Linear(input_size, input_size)

    def forward(self, x):
        return torch.sigmoid(self.fc1(x)) * self.fc2(x)

class GatedResidualNetwork(nn.Module):
    def __init__(self, input_size, hidden_size, output_size, dropout=0.1):
        super().__init__()
        self.fc1 = nn.Linear(input_size, hidden_size)
        self.elu = nn.ELU()
        self.fc2 = nn.Linear(hidden_size, output_size)
        self.dropout = nn.Dropout(dropout)
        self.gate = GLU(output_size)
        self.layer_norm = nn.LayerNorm(output_size)
        self.skip_proj = nn.Linear(input_size, output_size) if input_size != output_size else nn.Identity()

    def forward(self, x):
        residual = self.skip_proj(x)
        x = self.fc1(x)
        x = self.elu(x)
        x = self.fc2(x)
        x = self.dropout(x)
        x = self.gate(x)
        return self.layer_norm(residual + x)

class AsymmetricTFT(nn.Module):
    def __init__(self, input_dim, seq_len=21, d_model=32, nhead=4, dropout=0.2, num_targets=2):
        super().__init__()
        self.num_targets = num_targets
        self.grn_in = GatedResidualNetwork(input_dim, d_model * 2, d_model, dropout)

        pe = torch.zeros(seq_len, d_model)
        position = torch.arange(0, seq_len, dtype=torch.float).unsqueeze(1)
        div_term = torch.exp(torch.arange(0, d_model, 2).float() * (-math.log(10000.0) / d_model))
        pe[:, 0::2] = torch.sin(position * div_term)
        pe[:, 1::2] = torch.cos(position * div_term)
        self.register_buffer('pe', pe.unsqueeze(0))

        self.attention = nn.MultiheadAttention(embed_dim=d_model, num_heads=nhead, dropout=dropout, batch_first=True)
        self.layer_norm = nn.LayerNorm(d_model)

        self.grn_out = GatedResidualNetwork(d_model, d_model, d_model, dropout)

        # NEW HEAD: Predict Median directly, and strictly positive spreads for the wings
        self.median_layer = nn.Linear(d_model, num_targets)
        # 2 spreads per target (downside distance, upside distance)
        self.spread_layer = nn.Linear(d_model, num_targets * 2)

    def forward(self, x):
        x = self.grn_in(x)
        x = x + self.pe
        attn_out, _ = self.attention(x, x, x)
        x = self.layer_norm(x + attn_out)

        last_step = x[:, -1, :]
        out = self.grn_out(last_step)

        # 1. Predict Median (50th percentile)
        median = self.median_layer(out) # Shape: (B, targets)

        # 2. Predict Spreads (must be positive)
        spreads = F.softplus(self.spread_layer(out)).view(-1, self.num_targets, 2)

        # 3. Calculate 10th and 90th percentiles using the spreads to guarantee non-crossing
        q10 = median - spreads[:, :, 0]
        q90 = median + spreads[:, :, 1]

        # Stack into final shape: (Batch, Targets, Quantiles)
        preds = torch.stack([q10, median, q90], dim=-1)

        return preds

model = AsymmetricTFT(input_dim=len(feature_cols))

import torch.optim as optim

SEQ_LEN = 21
BATCH_SIZE = 64
EPOCHS = 35
LR = 0.001

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Training Asymmetric TFT on: {device}")

# Define the exact percentiles we want (10th, 50th, 90th) to create an 80% CI
QUANTILES = torch.tensor([0.10, 0.50, 0.90], device=device).view(1, 1, 3)

out_of_sample_loss = []

for split_idx, split in enumerate(splits):
    print(f"\n--- Training Asymmetric Walk-Forward Split {split_idx + 1}/{len(splits)} ---")

    tr_start, tr_end = split['train']
    te_start, te_end = split['test']

    X_train_raw, y_train_raw = X_raw[tr_start:tr_end], y_raw[tr_start:tr_end]
    X_test_raw, y_test_raw = X_raw[te_start:te_end], y_raw[te_start:te_end]

    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train_raw).astype(np.float32)
    X_test_scaled = scaler.transform(X_test_raw).astype(np.float32)

    train_dataset = NiftySequenceDataset(X_train_scaled, y_train_raw, sequence_length=SEQ_LEN)
    test_dataset = NiftySequenceDataset(X_test_scaled, y_test_raw, sequence_length=SEQ_LEN)

    train_loader = DataLoader(train_dataset, batch_size=BATCH_SIZE, shuffle=True, drop_last=True)
    test_loader = DataLoader(test_dataset, batch_size=BATCH_SIZE, shuffle=False)

    model = AsymmetricTFT(input_dim=len(feature_cols), seq_len=SEQ_LEN).to(device)
    # Lower weight decay here since Pinball loss is naturally tighter
    optimizer = optim.AdamW(model.parameters(), lr=LR, weight_decay=1e-4)

    for epoch in range(EPOCHS):
        model.train()
        epoch_loss = 0.0
        for X_batch, y_batch in train_loader:
            X_batch, y_batch = X_batch.to(device), y_batch.to(device)

            optimizer.zero_grad()
            preds = model(X_batch)

            # Apply Quantile Loss
            loss = quantile_loss(preds, y_batch, QUANTILES)

            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
            optimizer.step()
            epoch_loss += loss.item()

        if (epoch+1) % 10 == 0 or epoch == 0:
            print(f"Epoch {epoch+1}/{EPOCHS} | Train Pinball Loss: {epoch_loss/len(train_loader):.5f}")

    # Evaluation
    model.eval()
    test_loss = 0.0
    with torch.no_grad():
        for X_batch, y_batch in test_loader:
            X_batch, y_batch = X_batch.to(device), y_batch.to(device)
            preds = model(X_batch)
            loss = quantile_loss(preds, y_batch, QUANTILES)
            test_loss += loss.item()

    avg_test_loss = test_loss / len(test_loader)
    out_of_sample_loss.append(avg_test_loss)
    print(f"-> Split {split_idx + 1} Out-of-Sample Pinball Loss: {avg_test_loss:.5f}")

print(f"\nAverage Out-of-Sample Pinball Loss across splits: {np.mean(out_of_sample_loss):.5f}")

import matplotlib.pyplot as plt
import numpy as np

def evaluate_asymmetric_accuracy(model, test_loader):
    model.eval()

    actuals_1d, lowers_1d, uppers_1d, means_1d = [], [], [], []
    actuals_5d, lowers_5d, uppers_5d, means_5d = [], [], [], []

    with torch.no_grad():
        for X_batch, y_batch in test_loader:
            X_batch_gpu = X_batch.to(device)

            preds = model(X_batch_gpu).cpu().numpy()
            y_actual = y_batch.numpy()

            batch_size = preds.shape[0]

            for b in range(batch_size):
                lowers_1d.append(preds[b, 0, 0])
                means_1d.append(preds[b, 0, 1])
                uppers_1d.append(preds[b, 0, 2])
                actuals_1d.append(y_actual[b, 0])

                lowers_5d.append(preds[b, 1, 0])
                means_5d.append(preds[b, 1, 1])
                uppers_5d.append(preds[b, 1, 2])
                actuals_5d.append(y_actual[b, 1])

    # Calculate Hit Rates
    hits_1d = sum(1 for a, l, u in zip(actuals_1d, lowers_1d, uppers_1d) if l <= a <= u)
    hits_5d = sum(1 for a, l, u in zip(actuals_5d, lowers_5d, uppers_5d) if l <= a <= u)

    total = len(actuals_1d)

    # Calculate Average Net Ranges
    avg_range_1d = np.mean(np.array(uppers_1d) - np.array(lowers_1d)) * 100
    avg_range_5d = np.mean(np.array(uppers_5d) - np.array(lowers_5d)) * 100

    # Calculate Skewness
    up_spread_5d = np.mean(np.array(uppers_5d) - np.array(means_5d)) * 100
    down_spread_5d = np.mean(np.array(means_5d) - np.array(lowers_5d)) * 100

    # Calculate Directional Accuracy (Does the predicted median have the same sign as the actual move?)
    dir_acc_1d = np.mean(np.sign(means_1d) == np.sign(actuals_1d)) * 100
    dir_acc_5d = np.mean(np.sign(means_5d) == np.sign(actuals_5d)) * 100

    print("\n--- WEIGHTED ASYMMETRIC TFT Accuracy Report ---")
    print(f"Target Confidence Interval : 80% (10th to 90th Percentile)")
    print(f"Total Test Days Evaluated  : {total}")
    print(f"1-Day Ahead Hit Rate       : {(hits_1d / total) * 100:.2f}%")
    print(f"1-Day Directional Accuracy : {dir_acc_1d:.2f}%")
    print(f"1-Day Avg Predicted Range  : {avg_range_1d:.2f}%")
    print("-" * 40)
    print(f"5-Day Ahead Hit Rate       : {(hits_5d / total) * 100:.2f}%")
    print(f"5-Day Directional Accuracy : {dir_acc_5d:.2f}%")
    print(f"5-Day Avg Predicted Range  : {avg_range_5d:.2f}%")
    print(f"--- Skew Diagnostics (5D) ---")
    print(f"Average Upside Room        : +{up_spread_5d:.2f}%")
    print(f"Average Downside Risk      : -{down_spread_5d:.2f}%\n")

    return actuals_1d, lowers_1d, uppers_1d, means_1d, actuals_5d, lowers_5d, uppers_5d, means_5d

# 1. Execute the evaluation
a_1d, l_1d, u_1d, m_1d, a_5d, l_5d, u_5d, m_5d = evaluate_asymmetric_accuracy(model, test_loader)

# 2. Plotting Function
def plot_backtest_coverage(actuals, lowers, uppers, means, title, num_days=None):
    if num_days is None:
        num_days = len(actuals)

    plt.figure(figsize=(16, 7))

    x_axis = np.arange(num_days)
    a_slice = actuals[-num_days:]
    l_slice = lowers[-num_days:]
    u_slice = uppers[-num_days:]
    m_slice = means[-num_days:]

    plt.plot(x_axis, a_slice, color='black', marker='o', markersize=3, label='Actual Log Return', alpha=0.8)
    plt.plot(x_axis, m_slice, color='purple', linestyle='-', linewidth=2, alpha=0.9, label='Predicted Median (50th Pct)')
    plt.plot(x_axis, u_slice, color='green', linestyle='--', alpha=0.7, label='Predicted Upside (90th Pct)')
    plt.plot(x_axis, l_slice, color='red', linestyle='--', alpha=0.7, label='Predicted Downside (10th Pct)')

    plt.fill_between(x_axis, l_slice, u_slice, color='blue', alpha=0.1, label='Asymmetric 80% Zone')

    plt.axhline(0, color='gray', linestyle=':', alpha=0.5)

    time_label = f"Last {num_days} Days" if num_days != len(actuals) else "Full Out-of-Sample Period"
    plt.title(f"{title} - {time_label}", fontsize=14)

    plt.xlabel("Test Set Days (Chronological)", fontsize=12)
    plt.ylabel("Log Return", fontsize=12)
    plt.legend(loc='upper left')
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

# 3. Generate the Plots
plot_backtest_coverage(a_1d, l_1d, u_1d, m_1d, "Weighted Asymmetric TFT 1-Day Forecast", num_days=None)
plot_backtest_coverage(a_5d, l_5d, u_5d, m_5d, "Weighted Asymmetric TFT 5-Day Forecast", num_days=None)

"""## 4. Optimisation Experiments"""

import pandas as pd
import polars as pl
import numpy as np
import torch
import math
import random
from torch.utils.data import Dataset, DataLoader
from sklearn.preprocessing import StandardScaler
from pathlib import Path

# 1. Load Data
processed_dir = Path("/content/drive/MyDrive/Processed Trading Data")
master_out_file = processed_dir / "master_daily_features.parquet"
df = pl.read_parquet(master_out_file)

# One-hot encode Regime_State safely
df_pd = df.to_pandas()
df_pd = pd.get_dummies(df_pd, columns=["Regime_State"], drop_first=False, dtype=float)

# 2. Define Features and Targets
base_features = [
    'Realized_Vol_Ann', 'Path_Length', 'Trend_Strength', 'VIX_Close',
    'PCR_OI', 'PCR_Volume', 'VRP_Daily', 'Trailing_Ret_5D'
]
regime_cols = [c for c in df_pd.columns if 'Regime_State_' in c]
feature_cols = base_features + regime_cols
target_cols = ['Target_Ret_1D', 'Target_Ret_5D']

X_raw = df_pd[feature_cols].values.astype(np.float32)
y_raw = df_pd[target_cols].values.astype(np.float32)

# 3. Sequence Dataset
class NiftySequenceDataset(Dataset):
    def __init__(self, X, y, sequence_length=21):
        self.X = X
        self.y = y
        self.sequence_length = sequence_length

    def __len__(self):
        return len(self.X) - self.sequence_length + 1

    def __getitem__(self, idx):
        x_window = self.X[idx : idx + self.sequence_length]
        y_target = self.y[idx + self.sequence_length - 1]
        return torch.tensor(x_window), torch.tensor(y_target)

# 4. Random Out-of-Sample Splitter
def get_random_oos_split(total_length, min_train_size=1000, test_size=230, purge_gap=5):
    """
    Randomly selects a chronological split point to test the model.
    """
    max_train_idx = total_length - test_size - purge_gap
    if max_train_idx <= min_train_size:
        raise ValueError("Dataset too small for these split parameters.")

    train_end = random.randint(min_train_size, max_train_idx)

    return {
        'train': (0, train_end),
        'test': (train_end + purge_gap, train_end + purge_gap + test_size)
    }

print("Data successfully loaded. Random OOS Splitter initialized.")

import torch.nn as nn
import torch.nn.functional as F

# --- 1. Quantile (Pinball) Loss ---
def quantile_loss(preds, target, quantiles):
    target = target.unsqueeze(-1)
    errors = target - preds
    losses = torch.max(quantiles * errors, (quantiles - 1.0) * errors)
    return losses.mean()

# --- 2. TFT Core Components ---
class GLU(nn.Module):
    def __init__(self, input_size):
        super().__init__()
        self.fc1 = nn.Linear(input_size, input_size)
        self.fc2 = nn.Linear(input_size, input_size)

    def forward(self, x):
        return torch.sigmoid(self.fc1(x)) * self.fc2(x)

class GatedResidualNetwork(nn.Module):
    def __init__(self, input_size, hidden_size, output_size, dropout=0.1):
        super().__init__()
        self.fc1 = nn.Linear(input_size, hidden_size)
        self.elu = nn.ELU()
        self.fc2 = nn.Linear(hidden_size, output_size)
        self.dropout = nn.Dropout(dropout)
        self.gate = GLU(output_size)
        self.layer_norm = nn.LayerNorm(output_size)
        self.skip_proj = nn.Linear(input_size, output_size) if input_size != output_size else nn.Identity()

    def forward(self, x):
        residual = self.skip_proj(x)
        x = self.fc1(x)
        x = self.elu(x)
        x = self.fc2(x)
        x = self.dropout(x)
        x = self.gate(x)
        return self.layer_norm(residual + x)

class AsymmetricTFT(nn.Module):
    def __init__(self, input_dim, seq_len=21, d_model=32, nhead=4, dropout=0.2, num_targets=2, num_grn_layers=1):
        super().__init__()
        self.num_targets = num_targets

        # Expandable GRN Block
        layers = []
        in_size = input_dim
        for i in range(num_grn_layers):
            out_size = d_model if i == num_grn_layers - 1 else d_model * 2
            layers.append(GatedResidualNetwork(in_size, d_model * 2, out_size, dropout))
            in_size = out_size
        self.grn_in = nn.Sequential(*layers)

        pe = torch.zeros(seq_len, d_model)
        position = torch.arange(0, seq_len, dtype=torch.float).unsqueeze(1)
        div_term = torch.exp(torch.arange(0, d_model, 2).float() * (-math.log(10000.0) / d_model))
        pe[:, 0::2] = torch.sin(position * div_term)
        pe[:, 1::2] = torch.cos(position * div_term)
        self.register_buffer('pe', pe.unsqueeze(0))

        self.attention = nn.MultiheadAttention(embed_dim=d_model, num_heads=nhead, dropout=dropout, batch_first=True)
        self.layer_norm = nn.LayerNorm(d_model)

        self.grn_out = GatedResidualNetwork(d_model, d_model, d_model, dropout)

        self.median_layer = nn.Linear(d_model, num_targets)
        self.spread_layer = nn.Linear(d_model, num_targets * 2)

    def forward(self, x):
        x = self.grn_in(x)
        x = x + self.pe
        attn_out, _ = self.attention(x, x, x)
        x = self.layer_norm(x + attn_out)

        last_step = x[:, -1, :]
        out = self.grn_out(last_step)

        median = self.median_layer(out)
        spreads = F.softplus(self.spread_layer(out)).view(-1, self.num_targets, 2)

        q10 = median - spreads[:, :, 0]
        q90 = median + spreads[:, :, 1]

        preds = torch.stack([q10, median, q90], dim=-1)
        return preds

print("Dynamic Asymmetric TFT Architecture loaded.")

import torch.optim as optim

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
QUANTILES = torch.tensor([0.10, 0.50, 0.90], device=device).view(1, 1, 3)

def evaluate_experiment_accuracy(models, test_loader):
    for m in models: m.eval()

    actuals_1d, lowers_1d, uppers_1d, means_1d = [], [], [], []
    actuals_5d, lowers_5d, uppers_5d, means_5d = [], [], [], []

    with torch.no_grad():
        for X_batch, y_batch in test_loader:
            X_batch_gpu = X_batch.to(device)
            y_actual = y_batch.numpy()

            # Ensemble Averaging
            all_preds = torch.stack([m(X_batch_gpu) for m in models])
            preds = torch.mean(all_preds, dim=0).cpu().numpy()

            for b in range(preds.shape[0]):
                # 1D Target
                lowers_1d.append(preds[b, 0, 0])
                means_1d.append(preds[b, 0, 1])
                uppers_1d.append(preds[b, 0, 2])
                actuals_1d.append(y_actual[b, 0])
                # 5D Target
                lowers_5d.append(preds[b, 1, 0])
                means_5d.append(preds[b, 1, 1])
                uppers_5d.append(preds[b, 1, 2])
                actuals_5d.append(y_actual[b, 1])

    # 1D Metrics Calculation
    hits_1d = sum(1 for a, l, u in zip(actuals_1d, lowers_1d, uppers_1d) if l <= a <= u)
    hr_1d = (hits_1d / len(actuals_1d)) * 100
    rng_1d = np.mean(np.array(uppers_1d) - np.array(lowers_1d)) * 100
    dir_acc_1d = np.mean(np.sign(means_1d) == np.sign(actuals_1d)) * 100

    # 5D Metrics Calculation
    hits_5d = sum(1 for a, l, u in zip(actuals_5d, lowers_5d, uppers_5d) if l <= a <= u)
    hr_5d = (hits_5d / len(actuals_5d)) * 100
    rng_5d = np.mean(np.array(uppers_5d) - np.array(lowers_5d)) * 100
    dir_acc_5d = np.mean(np.sign(means_5d) == np.sign(actuals_5d)) * 100

    return hr_1d, rng_1d, dir_acc_1d, hr_5d, rng_5d, dir_acc_5d

def run_experiment(name, master_split, epochs=35, d_model=32, seq_len=21, dropout=0.2,
                   num_grn_layers=1, use_lr_scheduler=False, n_ensembles=1):
    print(f"\n{'='*60}")
    print(f"EXPERIMENT: {name}")
    print(f"{'='*60}")

    tr_start, tr_end = master_split['train']
    te_start, te_end = master_split['test']

    X_train_raw, y_train_raw = X_raw[tr_start:tr_end], y_raw[tr_start:tr_end]
    X_test_raw, y_test_raw = X_raw[te_start:te_end], y_raw[te_start:te_end]

    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train_raw).astype(np.float32)
    X_test_scaled = scaler.transform(X_test_raw).astype(np.float32)

    train_dataset = NiftySequenceDataset(X_train_scaled, y_train_raw, sequence_length=seq_len)
    test_dataset = NiftySequenceDataset(X_test_scaled, y_test_raw, sequence_length=seq_len)

    train_loader = DataLoader(train_dataset, batch_size=64, shuffle=True, drop_last=True)
    test_loader = DataLoader(test_dataset, batch_size=64, shuffle=False)

    trained_models = []

    for i in range(n_ensembles):
        if n_ensembles > 1: print(f" Training Ensemble Member {i+1}/{n_ensembles}...")

        model = AsymmetricTFT(input_dim=len(feature_cols), seq_len=seq_len, d_model=d_model,
                              dropout=dropout, num_grn_layers=num_grn_layers).to(device)

        optimizer = optim.AdamW(model.parameters(), lr=0.001, weight_decay=1e-4)

        scheduler = None
        if use_lr_scheduler:
            scheduler = optim.lr_scheduler.CosineAnnealingWarmRestarts(optimizer, T_0=10, T_mult=2)

        for epoch in range(epochs):
            model.train()
            for X_batch, y_batch in train_loader:
                X_batch, y_batch = X_batch.to(device), y_batch.to(device)
                optimizer.zero_grad()
                preds = model(X_batch)
                loss = quantile_loss(preds, y_batch, QUANTILES)
                loss.backward()
                torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
                optimizer.step()

            if scheduler:
                scheduler.step()

        trained_models.append(model)

    hr_1d, rng_1d, dir_1d, hr_5d, rng_5d, dir_5d = evaluate_experiment_accuracy(trained_models, test_loader)

    print("\n--- PERFORMANCE METRICS ---")
    print(f"[1D] Hit Rate: {hr_1d:.2f}% | Avg Range: {rng_1d:.2f}% | Dir. Accuracy: {dir_1d:.2f}%")
    print(f"[5D] Hit Rate: {hr_5d:.2f}% | Avg Range: {rng_5d:.2f}% | Dir. Accuracy: {dir_5d:.2f}%")

    return trained_models, scaler

# --- Generate the SINGLE Random Split for A/B Testing ---
master_split = get_random_oos_split(len(X_raw), test_size=230)
print(f"MASTER SPLIT LOCKED IN:")
print(f"Training Data: Index 0 to {master_split['train'][1]}")
print(f"Testing Data : Index {master_split['test'][0]} to {master_split['test'][1]}\n")

# 1. Baseline Control
m_base, scaler_base = run_experiment("1. Baseline Control", master_split, epochs=35)

# 2. Extended Training (Overfitting Test)
m_epochs, _ = run_experiment("2. Increased Epochs (75)", master_split, epochs=75)

# 3. Network Scaling
m_hyper, _ = run_experiment("3. Larger Network (d_model=64, seq=42)", master_split, d_model=64, seq_len=42, epochs=35)

# 4. Deep Gated Residual Networks
