import pandas as pd
import polars as pl
import numpy as np
import torch
import math
import random
from torch.utils.data import Dataset, DataLoader
from sklearn.preprocessing import StandardScaler
from pathlib import Path

# ==========================================
# GLOBAL HYPERPARAMETERS & CONFIGURATION
# ==========================================
CONFIG = {
    "num_runs": 5,              # NUMBER OF RANDOMIZED PIPELINE RUNS
    "seq_len": 21,
    "d_model": 32,
    "nhead": 4,
    "dropout": 0.2,
    "num_grn_layers": 3,        # Retaining deep feature extraction
    "epochs": 35,
    "batch_size": 64,
    "lr": 0.001,
    "use_lr_scheduler": True,   # Retaining optimization escape mechanism
    "n_ensembles": 3,           # Retaining stability mechanism
    "median_weight": 1.2,       # SMALL LOGICAL TWEAK: Increased from 2.0 to 3.0 to organically tighten range
    "test_size": 230,
    "purge_gap": 5
}
# ==========================================

# 1. Load Data
processed_dir = Path("/content/drive/MyDrive/Processed Trading Data")
master_out_file = processed_dir / "master_daily_features.parquet"
df = pl.read_parquet(master_out_file)

df_pd = df.to_pandas()
df_pd = pd.get_dummies(df_pd, columns=["Regime_State"], drop_first=False, dtype=float)

# 2. Features and Targets
base_features = [
    'Realized_Vol_Ann', 'Path_Length', 'Trend_Strength', 'VIX_Close',
    'PCR_OI', 'PCR_Volume', 'VRP_Daily', 'Trailing_Ret_5D'
]
regime_cols = [c for c in df_pd.columns if 'Regime_State_' in c]
feature_cols = base_features + regime_cols
target_cols = ['Target_Ret_1D', 'Target_Ret_5D']

X_raw = df_pd[feature_cols].values.astype(np.float32)
y_raw = df_pd[target_cols].values.astype(np.float32)

# 3. Sequence Dataset
class NiftySequenceDataset(Dataset):
    def __init__(self, X, y, sequence_length=21):
        self.X = X
        self.y = y
        self.sequence_length = sequence_length

    def __len__(self):
        return len(self.X) - self.sequence_length + 1

    def __getitem__(self, idx):
        x_window = self.X[idx : idx + self.sequence_length]
        y_target = self.y[idx + self.sequence_length - 1]
        return torch.tensor(x_window), torch.tensor(y_target)

# 4. Random Out-of-Sample Splitter
def get_random_oos_split(total_length, min_train_size=1000, test_size=230, purge_gap=5):
    max_train_idx = total_length - test_size - purge_gap
    if max_train_idx <= min_train_size:
        raise ValueError("Dataset too small for these split parameters.")
    train_end = random.randint(min_train_size, max_train_idx)
    return {
        'train': (0, train_end),
        'test': (train_end + purge_gap, train_end + purge_gap + test_size)
    }

print("Data successfully loaded. Pipeline Configuration Ready.")

import torch.nn as nn
import torch.nn.functional as F

# --- 1. Weighted Quantile Loss ---
def weighted_quantile_loss(preds, target, quantiles, median_weight=3.0):
    target_exp = target.unsqueeze(-1)
    errors = target_exp - preds
    losses = torch.max(quantiles * errors, (quantiles - 1.0) * errors)
    weights = torch.tensor([1.0, median_weight, 1.0], device=preds.device).view(1, 1, 3)
    weighted_losses = losses * weights
    return weighted_losses.mean()

# --- 2. TFT Core Components ---
class GLU(nn.Module):
    def __init__(self, input_size):
        super().__init__()
        self.fc1 = nn.Linear(input_size, input_size)
        self.fc2 = nn.Linear(input_size, input_size)

    def forward(self, x):
        return torch.sigmoid(self.fc1(x)) * self.fc2(x)

class GatedResidualNetwork(nn.Module):
    def __init__(self, input_size, hidden_size, output_size, dropout=0.1):
        super().__init__()
        self.fc1 = nn.Linear(input_size, hidden_size)
        self.elu = nn.ELU()
        self.fc2 = nn.Linear(hidden_size, output_size)
        self.dropout = nn.Dropout(dropout)
        self.gate = GLU(output_size)
        self.layer_norm = nn.LayerNorm(output_size)
        self.skip_proj = nn.Linear(input_size, output_size) if input_size != output_size else nn.Identity()

    def forward(self, x):
        residual = self.skip_proj(x)
        x = self.fc1(x)
        x = self.elu(x)
        x = self.fc2(x)
        x = self.dropout(x)
        x = self.gate(x)
        return self.layer_norm(residual + x)

class AsymmetricTFT(nn.Module):
    def __init__(self, input_dim, seq_len=21, d_model=32, nhead=4, dropout=0.2, num_targets=2, num_grn_layers=3):
        super().__init__()
        self.num_targets = num_targets

        layers = []
        in_size = input_dim
        for i in range(num_grn_layers):
            out_size = d_model if i == num_grn_layers - 1 else d_model * 2
            layers.append(GatedResidualNetwork(in_size, d_model * 2, out_size, dropout))
            in_size = out_size
        self.grn_in = nn.Sequential(*layers)

        pe = torch.zeros(seq_len, d_model)
        position = torch.arange(0, seq_len, dtype=torch.float).unsqueeze(1)
        div_term = torch.exp(torch.arange(0, d_model, 2).float() * (-math.log(10000.0) / d_model))
        pe[:, 0::2] = torch.sin(position * div_term)
        pe[:, 1::2] = torch.cos(position * div_term)
        self.register_buffer('pe', pe.unsqueeze(0))

        self.attention = nn.MultiheadAttention(embed_dim=d_model, num_heads=nhead, dropout=dropout, batch_first=True)
        self.layer_norm = nn.LayerNorm(d_model)

        self.grn_out = GatedResidualNetwork(d_model, d_model, d_model, dropout)
        self.median_layer = nn.Linear(d_model, num_targets)
        self.spread_layer = nn.Linear(d_model, num_targets * 2)

    def forward(self, x):
        x = self.grn_in(x)
        x = x + self.pe
        attn_out, _ = self.attention(x, x, x)
        x = self.layer_norm(x + attn_out)
        last_step = x[:, -1, :]
        out = self.grn_out(last_step)

        median = self.median_layer(out)
        spreads = F.softplus(self.spread_layer(out)).view(-1, self.num_targets, 2)
        q10 = median - spreads[:, :, 0]
        q90 = median + spreads[:, :, 1]

        preds = torch.stack([q10, median, q90], dim=-1)
        return preds

print(f"Deep Asymmetric TFT Architecture mapped with {CONFIG['num_grn_layers']} GRN layers.")

import torch.optim as optim
import matplotlib.pyplot as plt

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
QUANTILES = torch.tensor([0.15, 0.50, 0.85], device=device).view(1, 1, 3)

pipeline_results = []
# Store variables for the final plot
last_actuals, last_lowers, last_uppers, last_means = None, None, None, None

for run in range(1, CONFIG["num_runs"] + 1):
    print(f"\n" + "="*50)
    print(f"PIPELINE RUN {run}/{CONFIG['num_runs']}")
    print("="*50)

    # 1. Generate new random split
    split = get_random_oos_split(len(X_raw), test_size=CONFIG["test_size"], purge_gap=CONFIG["purge_gap"])
    tr_start, tr_end = split['train']
    te_start, te_end = split['test']
    print(f"Split Locked -> Train: 0-{tr_end} | Test: {te_start}-{te_end}")

    X_train_raw, y_train_raw = X_raw[tr_start:tr_end], y_raw[tr_start:tr_end]
    X_test_raw, y_test_raw = X_raw[te_start:te_end], y_raw[te_start:te_end]

    # 2. Strict Scaling
    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train_raw).astype(np.float32)
    X_test_scaled = scaler.transform(X_test_raw).astype(np.float32)

    train_dataset = NiftySequenceDataset(X_train_scaled, y_train_raw, sequence_length=CONFIG["seq_len"])
    test_dataset = NiftySequenceDataset(X_test_scaled, y_test_raw, sequence_length=CONFIG["seq_len"])
    train_loader = DataLoader(train_dataset, batch_size=CONFIG["batch_size"], shuffle=True, drop_last=True)
    test_loader = DataLoader(test_dataset, batch_size=CONFIG["batch_size"], shuffle=False)

    # 3. Train Ensemble
    ensemble_models = []
    for i in range(CONFIG["n_ensembles"]):
        model = AsymmetricTFT(
            input_dim=len(feature_cols), seq_len=CONFIG["seq_len"], d_model=CONFIG["d_model"],
            nhead=CONFIG["nhead"], dropout=CONFIG["dropout"], num_grn_layers=CONFIG["num_grn_layers"]
        ).to(device)

        optimizer = optim.AdamW(model.parameters(), lr=CONFIG["lr"], weight_decay=1e-4)
        scheduler = optim.lr_scheduler.CosineAnnealingWarmRestarts(optimizer, T_0=10, T_mult=2) if CONFIG["use_lr_scheduler"] else None

        for epoch in range(CONFIG["epochs"]):
            model.train()
            for X_batch, y_batch in train_loader:
                X_batch, y_batch = X_batch.to(device), y_batch.to(device)
                optimizer.zero_grad()
                preds = model(X_batch)
                loss = weighted_quantile_loss(preds, y_batch, QUANTILES, median_weight=CONFIG["median_weight"])
                loss.backward()
                torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
                optimizer.step()
            if scheduler: scheduler.step()
        ensemble_models.append(model)
        print(f"  Ensemble {i+1} trained.")

    # 4. Evaluate out-of-sample
    actuals_1d, lowers_1d, uppers_1d, means_1d = [], [], [], []
    actuals_5d, lowers_5d, uppers_5d, means_5d = [], [], [], []

    for m in ensemble_models: m.eval()
    with torch.no_grad():
        for X_batch, y_batch in test_loader:
            X_batch_gpu = X_batch.to(device)
            y_actual = y_batch.numpy()
            all_preds = torch.stack([m(X_batch_gpu) for m in ensemble_models])
            preds = torch.mean(all_preds, dim=0).cpu().numpy()

            for b in range(preds.shape[0]):
                lowers_1d.append(preds[b, 0, 0]); means_1d.append(preds[b, 0, 1]); uppers_1d.append(preds[b, 0, 2]); actuals_1d.append(y_actual[b, 0])
                lowers_5d.append(preds[b, 1, 0]); means_5d.append(preds[b, 1, 1]); uppers_5d.append(preds[b, 1, 2]); actuals_5d.append(y_actual[b, 1])

    hits_1d = sum(1 for a, l, u in zip(actuals_1d, lowers_1d, uppers_1d) if l <= a <= u)
    hits_5d = sum(1 for a, l, u in zip(actuals_5d, lowers_5d, uppers_5d) if l <= a <= u)
    total = len(actuals_1d)

    hr_1d = (hits_1d / total) * 100
    rng_1d = np.mean(np.array(uppers_1d) - np.array(lowers_1d)) * 100
    dir_1d = np.mean(np.sign(means_1d) == np.sign(actuals_1d)) * 100

    hr_5d = (hits_5d / total) * 100
    rng_5d = np.mean(np.array(uppers_5d) - np.array(lowers_5d)) * 100
    dir_5d = np.mean(np.sign(means_5d) == np.sign(actuals_5d)) * 100
    up_spread_5d = np.mean(np.array(uppers_5d) - np.array(means_5d)) * 100
    down_spread_5d = np.mean(np.array(means_5d) - np.array(lowers_5d)) * 100

    # 5. Store Results
    res_dict = {
        "run": run, "train_range": f"0-{tr_end}", "test_range": f"{te_start}-{te_end}",
        "hr_1d": hr_1d, "rng_1d": rng_1d, "dir_1d": dir_1d,
        "hr_5d": hr_5d, "rng_5d": rng_5d, "dir_5d": dir_5d,
        "up_5d": up_spread_5d, "down_5d": down_spread_5d
    }
    pipeline_results.append(res_dict)

    # Save the last run's arrays for plotting in Cell 4
    if run == CONFIG["num_runs"]:
        last_actuals, last_lowers, last_uppers, last_means = actuals_5d, lowers_5d, uppers_5d, means_5d

    # Free GPU memory
    del ensemble_models
    torch.cuda.empty_cache()

print("\nPipeline execution complete.")

# 1. Print all results sequentially
print("\n" + "="*60)
print("FINAL PIPELINE AGGREGATED REPORT")
print("="*60)

for res in pipeline_results:
    print(f"\nRUN {res['run']} | Train: {res['train_range']} | Test: {res['test_range']}")
    print("-" * 60)
    print(f"[1D] Hit Rate: {res['hr_1d']:.2f}% | Avg Range: {res['rng_1d']:.2f}% | Dir. Accuracy: {res['dir_1d']:.2f}%")
    print(f"[5D] Hit Rate: {res['hr_5d']:.2f}% | Avg Range: {res['rng_5d']:.2f}% | Dir. Accuracy: {res['dir_5d']:.2f}%")
    print(f"[5D Skew] Upside: +{res['up_5d']:.2f}% | Downside: -{res['down_5d']:.2f}%")

# 2. Plot the final run's 5D Forecast
def plot_backtest_coverage(actuals, lowers, uppers, means, title):
    plt.figure(figsize=(16, 7))
    x_axis = np.arange(len(actuals))

    plt.plot(x_axis, actuals, color='black', marker='o', markersize=3, label='Actual Log Return', alpha=0.8)
    plt.plot(x_axis, means, color='purple', linestyle='-', linewidth=2, alpha=0.9, label='Predicted Median (50th Pct)')
    plt.plot(x_axis, uppers, color='green', linestyle='--', alpha=0.7, label='Predicted Upside (90th Pct)')
    plt.plot(x_axis, lowers, color='red', linestyle='--', alpha=0.7, label='Predicted Downside (10th Pct)')

    plt.fill_between(x_axis, lowers, uppers, color='blue', alpha=0.1, label='Asymmetric 80% Zone')
    plt.axhline(0, color='gray', linestyle=':', alpha=0.5)

    plt.title(title, fontsize=14)
    plt.xlabel("Test Set Days (Chronological)", fontsize=12)
    plt.ylabel("Log Return", fontsize=12)
    plt.legend(loc='upper left')
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

plot_backtest_coverage(last_actuals, last_lowers, last_uppers, last_means, f"Pipeline Final Run - 5D Forecast (Test Range: {pipeline_results[-1]['test_range']})")

