class NiftySequenceDataset(Dataset):
    def __init__(self, X, y, vol, sequence_length):
        self.X = X
        self.y = y
        self.vol = vol
        self.sequence_length = sequence_length

    def __len__(self):
        return len(self.X) - self.sequence_length + 1

    def __getitem__(self, idx):
        x_window = self.X[idx : idx + self.sequence_length]
        y_target = self.y[idx + self.sequence_length - 1]
        vol_target = self.vol[idx + self.sequence_length - 1]
        return torch.tensor(x_window), torch.tensor(y_target), torch.tensor(vol_target)

def get_random_oos_split(total_length, min_train_size=1000, test_size=230, purge_gap=5):
    max_train_idx = total_length - test_size - purge_gap
    if max_train_idx <= min_train_size:
        raise ValueError("Dataset too small.")
    train_end = random.randint(min_train_size, max_train_idx)
    return {
        'train': (0, train_end),
        'test': (train_end + purge_gap, train_end + purge_gap + test_size)
    }

print("Data successfully loaded. Configured for decoupled Sequence Lengths.")

import torch.nn as nn
import torch.nn.functional as F

def weighted_quantile_loss(preds, target, quantiles, downside_weight=1.0, median_weight=2.0, upside_weight=1.0):
    target_exp = target.unsqueeze(-1)
    errors = target_exp - preds
    losses = torch.max(quantiles * errors, (quantiles - 1.0) * errors)
    weights = torch.tensor([downside_weight, median_weight, upside_weight], device=preds.device).view(1, 1, 3)
    weighted_losses = losses * weights
    return weighted_losses.mean()

class RobustInstanceNorm(nn.Module):
    def __init__(self, num_features, eps=1e-5):
        super().__init__()
        self.gamma = nn.Parameter(torch.ones(num_features))
        self.beta = nn.Parameter(torch.zeros(num_features))
        self.eps = eps

    def forward(self, x):
        median = torch.median(x, dim=1, keepdim=True)[0]
        mad = torch.median(torch.abs(x - median), dim=1, keepdim=True)[0]
        x_norm = (x - median) / (mad + self.eps)
        return x_norm * self.gamma + self.beta

def generate_decay_mask(seq_len, decay_rate=0.15):
    mask = torch.zeros(seq_len, seq_len)
    for i in range(seq_len):
        for j in range(seq_len):
            if j <= i:
                mask[i, j] = -decay_rate * (i - j)
            else:
                mask[i, j] = float('-inf')
    return mask

class GLU(nn.Module):
    def __init__(self, input_size):
        super().__init__()
        self.fc1 = nn.Linear(input_size, input_size)
        self.fc2 = nn.Linear(input_size, input_size)

    def forward(self, x):
        return torch.sigmoid(self.fc1(x)) * self.fc2(x)

class GatedResidualNetwork(nn.Module):
    def __init__(self, input_size, hidden_size, output_size, dropout=0.1):
        super().__init__()
        self.fc1 = nn.Linear(input_size, hidden_size)
        self.elu = nn.ELU()
        self.fc2 = nn.Linear(hidden_size, output_size)
        self.dropout = nn.Dropout(dropout)
        self.gate = GLU(output_size)
        self.layer_norm = nn.LayerNorm(output_size)
        self.skip_proj = nn.Linear(input_size, output_size) if input_size != output_size else nn.Identity()

    def forward(self, x):
        residual = self.skip_proj(x)
        x = self.fc1(x)
        x = self.elu(x)
        x = self.fc2(x)
        x = self.dropout(x)
        x = self.gate(x)
        return self.layer_norm(residual + x)

class AdvancedMultiTaskTFT(nn.Module):
    def __init__(self, input_dim, seq_len=21, d_model=32, nhead=4, dropout=0.2, num_targets=2, num_grn_layers=3, decay_rate=0.15):
        super().__init__()
        self.num_targets = num_targets
        self.robust_norm = RobustInstanceNorm(input_dim)

        layers = []
        in_size = input_dim
        for i in range(num_grn_layers):
            out_size = d_model if i == num_grn_layers - 1 else d_model * 2
            layers.append(GatedResidualNetwork(in_size, d_model * 2, out_size, dropout))
            in_size = out_size
        self.grn_in = nn.Sequential(*layers)

        pe = torch.zeros(seq_len, d_model)
        position = torch.arange(0, seq_len, dtype=torch.float).unsqueeze(1)
        div_term = torch.exp(torch.arange(0, d_model, 2).float() * (-math.log(10000.0) / d_model))
        pe[:, 0::2] = torch.sin(position * div_term)
        pe[:, 1::2] = torch.cos(position * div_term)
        self.register_buffer('pe', pe.unsqueeze(0))

        self.register_buffer('decay_mask', generate_decay_mask(seq_len, decay_rate))
        self.attention = nn.MultiheadAttention(embed_dim=d_model, num_heads=nhead, dropout=dropout, batch_first=True)
        self.layer_norm = nn.LayerNorm(d_model)
        self.grn_out = GatedResidualNetwork(d_model, d_model, d_model, dropout)

        self.median_layer = nn.Linear(d_model, num_targets)
        self.spread_layer = nn.Linear(d_model, num_targets * 2)
        self.aux_layer = nn.Linear(d_model, num_targets)

    def forward(self, x):
        x = self.robust_norm(x)
        x = self.grn_in(x)
        x = x + self.pe

        mask = self.decay_mask.to(x.device)
        attn_out, _ = self.attention(x, x, x, attn_mask=mask)
        x = self.layer_norm(x + attn_out)

        last_step = x[:, -1, :]
        out = self.grn_out(last_step)

        median = self.median_layer(out)
        spreads = F.softplus(self.spread_layer(out)).view(-1, self.num_targets, 2)
        q10 = median - spreads[:, :, 0]
        q90 = median + spreads[:, :, 1]

        quantile_preds = torch.stack([q10, median, q90], dim=-1)
        aux_preds = self.aux_layer(out)

        return quantile_preds, aux_preds

print("Advanced Causal TFT Architecture Loaded.")

import torch.optim as optim
import matplotlib.pyplot as plt
import numpy as np
import math

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
lower_q = (1.0 - CONFIG["target_ci"]) / 2.0
upper_q = 1.0 - lower_q
QUANTILES = torch.tensor([lower_q, 0.50, upper_q], device=device).view(1, 1, 3)

pipeline_results = []
last_actuals_1d, last_lowers_1d, last_uppers_1d, last_means_1d = None, None, None, None
last_actuals_5d, last_lowers_5d, last_uppers_5d, last_means_5d = None, None, None, None

for run in range(1, CONFIG["num_runs"] + 1):
    print(f"\n" + "="*50)
    print(f"PIPELINE RUN {run}/{CONFIG['num_runs']}")
    print("="*50)

    split = get_random_oos_split(len(X_raw), test_size=CONFIG["test_size"], purge_gap=CONFIG["purge_gap"])
    tr_start, tr_end = split['train']
    te_start, te_end = split['test']
    print(f"Split Locked -> Train: 0-{tr_end} | Test: {te_start}-{te_end}")

    X_train_raw, y_train_raw, vol_train = X_raw[tr_start:tr_end], y_raw[tr_start:tr_end], vol_raw[tr_start:tr_end]
    X_test_raw, y_test_raw, vol_test = X_raw[te_start:te_end], y_raw[te_start:te_end], vol_raw[te_start:te_end]

    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train_raw).astype(np.float32)
    X_test_scaled = scaler.transform(X_test_raw).astype(np.float32)

    # INDEPENDENT LOADERS FOR 1D AND 5D
    train_dataset_1d = NiftySequenceDataset(X_train_scaled, y_train_raw, vol_train, sequence_length=CONFIG["seq_len_1d"])
    test_dataset_1d = NiftySequenceDataset(X_test_scaled, y_test_raw, vol_test, sequence_length=CONFIG["seq_len_1d"])
    train_loader_1d = DataLoader(train_dataset_1d, batch_size=CONFIG["batch_size"], shuffle=True, drop_last=True)
    test_loader_1d = DataLoader(test_dataset_1d, batch_size=CONFIG["batch_size"], shuffle=False)

    train_dataset_5d = NiftySequenceDataset(X_train_scaled, y_train_raw, vol_train, sequence_length=CONFIG["seq_len_5d"])
    test_dataset_5d = NiftySequenceDataset(X_test_scaled, y_test_raw, vol_test, sequence_length=CONFIG["seq_len_5d"])
    train_loader_5d = DataLoader(train_dataset_5d, batch_size=CONFIG["batch_size"], shuffle=True, drop_last=True)
    test_loader_5d = DataLoader(test_dataset_5d, batch_size=CONFIG["batch_size"], shuffle=False)

    ensemble_models_1d = []
    ensemble_models_5d = []

    # ---------------------------------------------------------
    # TRAIN 1D ENSEMBLES
    # ---------------------------------------------------------
    print(f"\n  -> Training 1D Ensembles (Seq: {CONFIG['seq_len_1d']})...")
    for i in range(CONFIG["n_ensembles"]):
        model_1d = AdvancedMultiTaskTFT(
            input_dim=len(feature_cols), seq_len=CONFIG["seq_len_1d"], d_model=CONFIG["d_model"],
            nhead=CONFIG["nhead"], dropout=CONFIG["dropout"], num_targets=1,
            num_grn_layers=CONFIG["num_grn_layers"], decay_rate=CONFIG["attn_decay_rate"]
        ).to(device)

        optimizer = optim.AdamW(model_1d.parameters(), lr=CONFIG["lr"], weight_decay=1e-4)
        scheduler = optim.lr_scheduler.CosineAnnealingWarmRestarts(optimizer, T_0=10, T_mult=2) if CONFIG["use_lr_scheduler"] else None

        for epoch in range(CONFIG["epochs"]):
            model_1d.train()
            epoch_loss = 0.0
            for X_batch, y_batch, vol_batch in train_loader_1d:
                X_batch, y_batch, vol_batch = X_batch.to(device), y_batch.to(device), vol_batch.to(device)
                y_1d = y_batch[:, 0:1]

                optimizer.zero_grad()
                q_preds, aux_preds = model_1d(X_batch)
                vol_expanded = vol_batch.unsqueeze(-1) + 1e-6
                y_scaled = y_1d / vol_expanded

                loss_q = weighted_quantile_loss(q_preds, y_scaled, QUANTILES, CONFIG["downside_weight"], CONFIG["median_weight"], CONFIG["upside_weight"])
                loss_aux = F.mse_loss(aux_preds, torch.abs(y_scaled))
                loss = loss_q + (CONFIG["aux_task_weight"] * loss_aux)
                loss.backward()
                torch.nn.utils.clip_grad_norm_(model_1d.parameters(), max_norm=1.0)
                optimizer.step()
                epoch_loss += loss.item()
            if scheduler: scheduler.step()
        ensemble_models_1d.append(model_1d)
        print(f"     [1D] Model {i+1} Final Loss: {epoch_loss/len(train_loader_1d):.5f}")

    # ---------------------------------------------------------
    # TRAIN 5D ENSEMBLES (With Sqrt(5) Volatility Fix)
    # ---------------------------------------------------------
    print(f"\n  -> Training 5D Ensembles (Seq: {CONFIG['seq_len_5d']})...")
    for i in range(CONFIG["n_ensembles"]):
        model_5d = AdvancedMultiTaskTFT(
            input_dim=len(feature_cols), seq_len=CONFIG["seq_len_5d"], d_model=CONFIG["d_model"],
            nhead=CONFIG["nhead"], dropout=CONFIG["dropout"], num_targets=1,
            num_grn_layers=CONFIG["num_grn_layers"], decay_rate=CONFIG["attn_decay_rate"]
        ).to(device)

        optimizer = optim.AdamW(model_5d.parameters(), lr=CONFIG["lr"], weight_decay=1e-4)
        scheduler = optim.lr_scheduler.CosineAnnealingWarmRestarts(optimizer, T_0=10, T_mult=2) if CONFIG["use_lr_scheduler"] else None

        for epoch in range(CONFIG["epochs"]):
            model_5d.train()
            epoch_loss = 0.0
            for X_batch, y_batch, vol_batch in train_loader_5d:
                X_batch, y_batch, vol_batch = X_batch.to(device), y_batch.to(device), vol_batch.to(device)
                y_5d = y_batch[:, 1:2]

                optimizer.zero_grad()
                q_preds, aux_preds = model_5d(X_batch)

                # FIX: Multiply expected volatility by sqrt(time)
                vol_expanded = (vol_batch * math.sqrt(5)).unsqueeze(-1) + 1e-6
                y_scaled = y_5d / vol_expanded

                loss_q = weighted_quantile_loss(q_preds, y_scaled, QUANTILES, CONFIG["downside_weight"], CONFIG["median_weight"], CONFIG["upside_weight"])
                loss_aux = F.mse_loss(aux_preds, torch.abs(y_scaled))
                loss = loss_q + (CONFIG["aux_task_weight"] * loss_aux)
                loss.backward()
                torch.nn.utils.clip_grad_norm_(model_5d.parameters(), max_norm=1.0)
                optimizer.step()
                epoch_loss += loss.item()
            if scheduler: scheduler.step()
        ensemble_models_5d.append(model_5d)
        print(f"     [5D] Model {i+1} Final Loss: {epoch_loss/len(train_loader_5d):.5f}")

    # ---------------------------------------------------------
    # EVALUATE OOS (Independent Inference Loops)
    # ---------------------------------------------------------
    actuals_1d, lowers_1d, uppers_1d, means_1d = [], [], [], []
    actuals_5d, lowers_5d, uppers_5d, means_5d = [], [], [], []

    for m in ensemble_models_1d: m.eval()
    for m in ensemble_models_5d: m.eval()

    with torch.no_grad():
        # Evaluate 1D
        for X_batch, y_batch, vol_batch in test_loader_1d:
            X_batch_gpu, vol_batch_gpu = X_batch.to(device), vol_batch.to(device)
            y_actual = y_batch.numpy()
            all_q_1d = [m(X_batch_gpu)[0] for m in ensemble_models_1d]
            q_preds_scaled_1d = torch.mean(torch.stack(all_q_1d), dim=0)
            vol_multiplier = vol_batch_gpu.unsqueeze(-1).unsqueeze(-1)
            q_preds_real_1d = (q_preds_scaled_1d * vol_multiplier).cpu().numpy()

            for b in range(X_batch.shape[0]):
                lowers_1d.append(q_preds_real_1d[b, 0, 0]); means_1d.append(q_preds_real_1d[b, 0, 1]); uppers_1d.append(q_preds_real_1d[b, 0, 2]); actuals_1d.append(y_actual[b, 0])

        # Evaluate 5D
        for X_batch, y_batch, vol_batch in test_loader_5d:
            X_batch_gpu, vol_batch_gpu = X_batch.to(device), vol_batch.to(device)
            y_actual = y_batch.numpy()
            all_q_5d = [m(X_batch_gpu)[0] for m in ensemble_models_5d]
            q_preds_scaled_5d = torch.mean(torch.stack(all_q_5d), dim=0)
            vol_multiplier = (vol_batch_gpu * math.sqrt(5)).unsqueeze(-1).unsqueeze(-1)
            q_preds_real_5d = (q_preds_scaled_5d * vol_multiplier).cpu().numpy()

            for b in range(X_batch.shape[0]):
                lowers_5d.append(q_preds_real_5d[b, 0, 0]); means_5d.append(q_preds_real_5d[b, 0, 1]); uppers_5d.append(q_preds_real_5d[b, 0, 2]); actuals_5d.append(y_actual[b, 1])

    hits_1d = sum(1 for a, l, u in zip(actuals_1d, lowers_1d, uppers_1d) if l <= a <= u)
    hits_5d = sum(1 for a, l, u in zip(actuals_5d, lowers_5d, uppers_5d) if l <= a <= u)

    ranges_1d = (np.array(uppers_1d) - np.array(lowers_1d)) * 100
    ranges_5d = (np.array(uppers_5d) - np.array(lowers_5d)) * 100

    res_dict = {
        "run": run, "train_range": f"0-{tr_end}", "test_range": f"{te_start}-{te_end}",
        "hr_1d": (hits_1d / len(actuals_1d)) * 100, "rng_1d": np.mean(ranges_1d), "rng_1d_min": np.min(ranges_1d), "rng_1d_max": np.max(ranges_1d), "dir_1d": np.mean(np.sign(means_1d) == np.sign(actuals_1d)) * 100,
        "hr_5d": (hits_5d / len(actuals_5d)) * 100, "rng_5d": np.mean(ranges_5d), "rng_5d_min": np.min(ranges_5d), "rng_5d_max": np.max(ranges_5d), "dir_5d": np.mean(np.sign(means_5d) == np.sign(actuals_5d)) * 100,
        "up_5d": np.mean(np.array(uppers_5d) - np.array(means_5d)) * 100, "down_5d": np.mean(np.array(means_5d) - np.array(lowers_5d)) * 100
    }
    pipeline_results.append(res_dict)

    if run == CONFIG["num_runs"]:
        last_actuals_1d, last_lowers_1d, last_uppers_1d, last_means_1d = actuals_1d, lowers_1d, uppers_1d, means_1d
        last_actuals_5d, last_lowers_5d, last_uppers_5d, last_means_5d = actuals_5d, lowers_5d, uppers_5d, means_5d

    del ensemble_models_1d, ensemble_models_5d
    torch.cuda.empty_cache()

print("\nPipeline execution complete.")

import matplotlib.pyplot as plt
import numpy as np

# --- AGGREGATE PRINTING ---
print("\n" + "="*60)
print("FINAL PIPELINE AGGREGATED REPORT")
print("="*60)

for res in pipeline_results:
    print(f"\nRUN {res['run']} | Train: {res['train_range']} | Test: {res['test_range']}")
    print("-" * 60)
    print(f"[1D] Hit Rate: {res['hr_1d']:.2f}% | Avg Range: {res['rng_1d']:.2f}% (Min: {res['rng_1d_min']:.2f}%, Max: {res['rng_1d_max']:.2f}%) | Dir. Accuracy: {res['dir_1d']:.2f}%")
    print(f"[5D] Hit Rate: {res['hr_5d']:.2f}% | Avg Range: {res['rng_5d']:.2f}% (Min: {res['rng_5d_min']:.2f}%, Max: {res['rng_5d_max']:.2f}%) | Dir. Accuracy: {res['dir_5d']:.2f}%")
    print(f"[5D Skew] Upside: +{res['up_5d']:.2f}% | Downside: -{res['down_5d']:.2f}%")

# --- PLOTTING ---
def plot_backtest_coverage(actuals, lowers, uppers, means, title):
    plt.figure(figsize=(16, 7))
    x_axis = np.arange(len(actuals))

    plt.plot(x_axis, actuals, color='black', marker='o', markersize=3, label='Actual Log Return', alpha=0.8)
    plt.plot(x_axis, means, color='purple', linestyle='-', linewidth=2, alpha=0.9, label='Predicted Median (50th Pct)')
    plt.plot(x_axis, uppers, color='green', linestyle='--', alpha=0.7, label='Predicted Upside (90th Pct)')
    plt.plot(x_axis, lowers, color='red', linestyle='--', alpha=0.7, label='Predicted Downside (10th Pct)')

    plt.fill_between(x_axis, lowers, uppers, color='blue', alpha=0.1, label='Target Scaled Confidence Zone')

    ranges_pct = (np.array(uppers) - np.array(lowers)) * 100
    min_idx = np.argmin(ranges_pct)
    max_idx = np.argmax(ranges_pct)

    plt.vlines(x=min_idx, ymin=lowers[min_idx], ymax=uppers[min_idx], color='gold', linewidth=3, label=f'Min Range ({ranges_pct[min_idx]:.2f}%)', zorder=4)
    plt.vlines(x=max_idx, ymin=lowers[max_idx], ymax=uppers[max_idx], color='darkorange', linewidth=3, label=f'Max Range ({ranges_pct[max_idx]:.2f}%)', zorder=4)

    plt.axhline(0, color='gray', linestyle=':', alpha=0.5)

    plt.title(title, fontsize=14)
    plt.xlabel("Test Set Days (Chronological)", fontsize=12)
    plt.ylabel("Log Return", fontsize=12)
    plt.legend(loc='upper left')
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

plot_backtest_coverage(
    last_actuals_1d, last_lowers_1d, last_uppers_1d, last_means_1d,
    f"Advanced Model - 1D Forecast (Test Range: {pipeline_results[-1]['test_range']})"
)

plot_backtest_coverage(
    last_actuals_5d, last_lowers_5d, last_uppers_5d, last_means_5d,
    f"Advanced Model - 5D Forecast (Test Range: {pipeline_results[-1]['test_range']})"
)

import torch.optim as optim
import numpy as np
import math

print("\n" + "="*60)
print("PHASE 4b: EXPANDING WINDOW WALK-FORWARD VALIDATION")
print("="*60)

DAYS_PER_YEAR = 252
TR_YEARS = 4
TEST_YEARS = 1

min_train_size = TR_YEARS * DAYS_PER_YEAR
step_size = TEST_YEARS * DAYS_PER_YEAR
purge_gap = CONFIG["purge_gap"]

wf_actuals_1d, wf_lowers_1d, wf_uppers_1d, wf_means_1d = [], [], [], []
wf_actuals_5d, wf_lowers_5d, wf_uppers_5d, wf_means_5d = [], [], [], []

wf_base_prices_1d = []
wf_base_prices_5d = []

train_end = min_train_size
fold = 1

while train_end + purge_gap + max(CONFIG["seq_len_1d"], CONFIG["seq_len_5d"]) < len(X_raw):
    te_start = train_end + purge_gap
    te_end = min(te_start + step_size, len(X_raw))

    print(f"\n" + "-"*50)
    print(f"FOLD {fold} | Train: 0 to {train_end} | Test: {te_start} to {te_end}")
    print("-"*50)

    X_train_raw, y_train_raw, vol_train = X_raw[0:train_end], y_raw[0:train_end], vol_raw[0:train_end]
    X_test_raw, y_test_raw, vol_test = X_raw[te_start:te_end], y_raw[te_start:te_end], vol_raw[te_start:te_end]

    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train_raw).astype(np.float32)
    X_test_scaled = scaler.transform(X_test_raw).astype(np.float32)

    # INDEPENDENT LOADERS
    train_dataset_1d = NiftySequenceDataset(X_train_scaled, y_train_raw, vol_train, sequence_length=CONFIG["seq_len_1d"])
    test_dataset_1d = NiftySequenceDataset(X_test_scaled, y_test_raw, vol_test, sequence_length=CONFIG["seq_len_1d"])
    train_loader_1d = DataLoader(train_dataset_1d, batch_size=CONFIG["batch_size"], shuffle=True, drop_last=True)
    test_loader_1d = DataLoader(test_dataset_1d, batch_size=CONFIG["batch_size"], shuffle=False)

    train_dataset_5d = NiftySequenceDataset(X_train_scaled, y_train_raw, vol_train, sequence_length=CONFIG["seq_len_5d"])
    test_dataset_5d = NiftySequenceDataset(X_test_scaled, y_test_raw, vol_test, sequence_length=CONFIG["seq_len_5d"])
    train_loader_5d = DataLoader(train_dataset_5d, batch_size=CONFIG["batch_size"], shuffle=True, drop_last=True)
    test_loader_5d = DataLoader(test_dataset_5d, batch_size=CONFIG["batch_size"], shuffle=False)

    ensemble_models_1d = []
    ensemble_models_5d = []

    # --- TRAIN 1D ENSEMBLES ---
    print("  -> Training 1D Ensembles...")
    for i in range(CONFIG["n_ensembles"]):
        model_1d = AdvancedMultiTaskTFT(
            input_dim=len(feature_cols), seq_len=CONFIG["seq_len_1d"], d_model=CONFIG["d_model"],
            nhead=CONFIG["nhead"], dropout=CONFIG["dropout"], num_targets=1,
            num_grn_layers=CONFIG["num_grn_layers"], decay_rate=CONFIG["attn_decay_rate"]
        ).to(device)
        optimizer = optim.AdamW(model_1d.parameters(), lr=CONFIG["lr"], weight_decay=1e-4)

        for epoch in range(CONFIG["epochs"]):
            model_1d.train()
            for X_batch, y_batch, vol_batch in train_loader_1d:
                X_batch, y_batch, vol_batch = X_batch.to(device), y_batch.to(device), vol_batch.to(device)
                y_1d = y_batch[:, 0:1]
                optimizer.zero_grad()
                q_preds, aux_preds = model_1d(X_batch)

                vol_expanded = vol_batch.unsqueeze(-1) + 1e-6
                y_scaled = y_1d / vol_expanded

                loss_q = weighted_quantile_loss(q_preds, y_scaled, QUANTILES, CONFIG["downside_weight"], CONFIG["median_weight"], CONFIG["upside_weight"])
                loss_aux = F.mse_loss(aux_preds, torch.abs(y_scaled))
                loss = loss_q + (CONFIG["aux_task_weight"] * loss_aux)
                loss.backward()
                torch.nn.utils.clip_grad_norm_(model_1d.parameters(), max_norm=1.0)
                optimizer.step()
        ensemble_models_1d.append(model_1d)

    # --- TRAIN 5D ENSEMBLES ---
    print("  -> Training 5D Ensembles...")
    for i in range(CONFIG["n_ensembles"]):
        model_5d = AdvancedMultiTaskTFT(
            input_dim=len(feature_cols), seq_len=CONFIG["seq_len_5d"], d_model=CONFIG["d_model"],
            nhead=CONFIG["nhead"], dropout=CONFIG["dropout"], num_targets=1,
            num_grn_layers=CONFIG["num_grn_layers"], decay_rate=CONFIG["attn_decay_rate"]
        ).to(device)
        optimizer = optim.AdamW(model_5d.parameters(), lr=CONFIG["lr"], weight_decay=1e-4)

        for epoch in range(CONFIG["epochs"]):
            model_5d.train()
            for X_batch, y_batch, vol_batch in train_loader_5d:
                X_batch, y_batch, vol_batch = X_batch.to(device), y_batch.to(device), vol_batch.to(device)
                y_5d = y_batch[:, 1:2]
                optimizer.zero_grad()
                q_preds, aux_preds = model_5d(X_batch)

                vol_expanded = (vol_batch * math.sqrt(5)).unsqueeze(-1) + 1e-6
                y_scaled = y_5d / vol_expanded

                loss_q = weighted_quantile_loss(q_preds, y_scaled, QUANTILES, CONFIG["downside_weight"], CONFIG["median_weight"], CONFIG["upside_weight"])
                loss_aux = F.mse_loss(aux_preds, torch.abs(y_scaled))
                loss = loss_q + (CONFIG["aux_task_weight"] * loss_aux)
                loss.backward()
                torch.nn.utils.clip_grad_norm_(model_5d.parameters(), max_norm=1.0)
                optimizer.step()
        ensemble_models_5d.append(model_5d)

    # --- EVALUATE CURRENT FOLD ---
    fold_actuals_1d, fold_lowers_1d, fold_uppers_1d, fold_means_1d = [], [], [], []
    fold_actuals_5d, fold_lowers_5d, fold_uppers_5d, fold_means_5d = [], [], [], []

    for m in ensemble_models_1d: m.eval()
    for m in ensemble_models_5d: m.eval()

    with torch.no_grad():
        for X_batch, y_batch, vol_batch in test_loader_1d:
            X_batch_gpu, vol_batch_gpu = X_batch.to(device), vol_batch.to(device)
            y_actual = y_batch.numpy()
            all_q_1d = [m(X_batch_gpu)[0] for m in ensemble_models_1d]
            q_preds_scaled_1d = torch.mean(torch.stack(all_q_1d), dim=0)
            vol_multiplier = vol_batch_gpu.unsqueeze(-1).unsqueeze(-1)
            q_preds_real_1d = (q_preds_scaled_1d * vol_multiplier).cpu().numpy()

            for b in range(X_batch.shape[0]):
                fold_lowers_1d.append(q_preds_real_1d[b, 0, 0]); fold_means_1d.append(q_preds_real_1d[b, 0, 1]); fold_uppers_1d.append(q_preds_real_1d[b, 0, 2]); fold_actuals_1d.append(y_actual[b, 0])

        for X_batch, y_batch, vol_batch in test_loader_5d:
            X_batch_gpu, vol_batch_gpu = X_batch.to(device), vol_batch.to(device)
            y_actual = y_batch.numpy()
            all_q_5d = [m(X_batch_gpu)[0] for m in ensemble_models_5d]
            q_preds_scaled_5d = torch.mean(torch.stack(all_q_5d), dim=0)
            vol_multiplier = (vol_batch_gpu * math.sqrt(5)).unsqueeze(-1).unsqueeze(-1)
            q_preds_real_5d = (q_preds_scaled_5d * vol_multiplier).cpu().numpy()

            for b in range(X_batch.shape[0]):
                fold_lowers_5d.append(q_preds_real_5d[b, 0, 0]); fold_means_5d.append(q_preds_real_5d[b, 0, 1]); fold_uppers_5d.append(q_preds_real_5d[b, 0, 2]); fold_actuals_5d.append(y_actual[b, 1])

    wf_actuals_1d.extend(fold_actuals_1d); wf_lowers_1d.extend(fold_lowers_1d); wf_uppers_1d.extend(fold_uppers_1d); wf_means_1d.extend(fold_means_1d)
    wf_actuals_5d.extend(fold_actuals_5d); wf_lowers_5d.extend(fold_lowers_5d); wf_uppers_5d.extend(fold_uppers_5d); wf_means_5d.extend(fold_means_5d)

    # Store exact Spot_Close bases explicitly aligned with the sequence offsets
    fold_base_prices_1d = df_pd['Spot_Close'].values[te_start + CONFIG["seq_len_1d"] - 1 : te_start + CONFIG["seq_len_1d"] - 1 + len(fold_actuals_1d)]
    wf_base_prices_1d.extend(fold_base_prices_1d)

    fold_base_prices_5d = df_pd['Spot_Close'].values[te_start + CONFIG["seq_len_5d"] - 1 : te_start + CONFIG["seq_len_5d"] - 1 + len(fold_actuals_5d)]
    wf_base_prices_5d.extend(fold_base_prices_5d)

    h_1d = sum(1 for a, l, u in zip(fold_actuals_1d, fold_lowers_1d, fold_uppers_1d) if l <= a <= u)
    h_5d = sum(1 for a, l, u in zip(fold_actuals_5d, fold_lowers_5d, fold_uppers_5d) if l <= a <= u)

    r_1d = (np.array(fold_uppers_1d) - np.array(fold_lowers_1d)) * 100
    r_5d = (np.array(fold_uppers_5d) - np.array(fold_lowers_5d)) * 100

    print(f"  [Fold {fold} Quick Report]")
    print(f"  -> 1D Hit Rate: {(h_1d/len(fold_actuals_1d))*100:.2f}% | Avg Range: {np.mean(r_1d):.2f}% (Min: {np.min(r_1d):.2f}%, Max: {np.max(r_1d):.2f}%)")
    print(f"  -> 5D Hit Rate: {(h_5d/len(fold_actuals_5d))*100:.2f}% | Avg Range: {np.mean(r_5d):.2f}% (Min: {np.min(r_5d):.2f}%, Max: {np.max(r_5d):.2f}%)")

    train_end += step_size
    fold += 1

    del ensemble_models_1d, ensemble_models_5d
    torch.cuda.empty_cache()

# --- FINAL AGGREGATE SUMMARY ---
print("\n" + "="*60)
print("EXPANDING WINDOW WALK-FORWARD VALIDATION COMPLETE")
print("="*60)

total_days_1d = len(wf_actuals_1d)
total_days_5d = len(wf_actuals_5d)

agg_hits_1d = sum(1 for a, l, u in zip(wf_actuals_1d, wf_lowers_1d, wf_uppers_1d) if l <= a <= u)
agg_hits_5d = sum(1 for a, l, u in zip(wf_actuals_5d, wf_lowers_5d, wf_uppers_5d) if l <= a <= u)

agg_r_1d = (np.array(wf_uppers_1d) - np.array(wf_lowers_1d)) * 100
agg_r_5d = (np.array(wf_uppers_5d) - np.array(wf_lowers_5d)) * 100

print(f"Total Model Folds Executed : {fold - 1}")
print("-" * 60)
print(f"[AGGREGATE 1D PERFORMANCE] (Tested Days: {total_days_1d})")
print(f"  Overall Hit Rate         : {(agg_hits_1d/total_days_1d)*100:.2f}%")
print(f"  Overall Avg Range        : {np.mean(agg_r_1d):.2f}%")
print(f"  Absolute Min Range       : {np.min(agg_r_1d):.2f}%")
print(f"  Absolute Max Range       : {np.max(agg_r_1d):.2f}%")
print("-" * 60)
print(f"[AGGREGATE 5D PERFORMANCE] (Tested Days: {total_days_5d})")
print(f"  Overall Hit Rate         : {(agg_hits_5d/total_days_5d)*100:.2f}%")
print(f"  Overall Avg Range        : {np.mean(agg_r_5d):.2f}%")
print(f"  Absolute Min Range       : {np.min(agg_r_5d):.2f}%")
print(f"  Absolute Max Range       : {np.max(agg_r_5d):.2f}%")
print("="*60)
print("Proceed to Cell 6 for Universal Point Translation and Plotting.")

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

print("\n" + "="*70)
print("PHASE 5: UNIVERSAL WALK-FORWARD EVALUATION & TRANSLATION")
print("="*70)

base_prices_1d = np.array(wf_base_prices_1d)
base_prices_5d = np.array(wf_base_prices_5d)

actuals_1d = np.array(wf_actuals_1d)
lowers_1d = np.array(wf_lowers_1d)
uppers_1d = np.array(wf_uppers_1d)
means_1d = np.array(wf_means_1d)

actuals_5d = np.array(wf_actuals_5d)
lowers_5d = np.array(wf_lowers_5d)
uppers_5d = np.array(wf_uppers_5d)
means_5d = np.array(wf_means_5d)

# 2. Calculate Exact Prices at Target Dates
actual_prices_1d = base_prices_1d * np.exp(actuals_1d)
lower_bounds_1d = base_prices_1d * np.exp(lowers_1d)
upper_bounds_1d = base_prices_1d * np.exp(uppers_1d)
means_prices_1d = base_prices_1d * np.exp(means_1d)

actual_prices_5d = base_prices_5d * np.exp(actuals_5d)
lower_bounds_5d = base_prices_5d * np.exp(lowers_5d)
upper_bounds_5d = base_prices_5d * np.exp(uppers_5d)
means_prices_5d = base_prices_5d * np.exp(means_5d)

# 3. Calculate Log Return Metrics (%)
ranges_pct_1d = (uppers_1d - lowers_1d) * 100
ranges_pct_5d = (uppers_5d - lowers_5d) * 100

dir_acc_1d = np.mean(np.sign(means_1d) == np.sign(actuals_1d)) * 100
dir_acc_5d = np.mean(np.sign(means_5d) == np.sign(actuals_5d)) * 100

up_spread_pct_5d = np.mean(uppers_5d - means_5d) * 100
down_spread_pct_5d = np.mean(means_5d - lowers_5d) * 100

# 4. Calculate Breaches and Point Metrics
hits_1d = np.sum((actual_prices_1d >= lower_bounds_1d) & (actual_prices_1d <= upper_bounds_1d))
breaches_1d = len(actual_prices_1d) - hits_1d
hit_rate_1d = (hits_1d / len(actual_prices_1d)) * 100
point_ranges_1d = upper_bounds_1d - lower_bounds_1d

hits_5d = np.sum((actual_prices_5d >= lower_bounds_5d) & (actual_prices_5d <= upper_bounds_5d))
breaches_5d = len(actual_prices_5d) - hits_5d
hit_rate_5d = (hits_5d / len(actual_prices_5d)) * 100
point_ranges_5d = upper_bounds_5d - lower_bounds_5d

# 5. Print Global Report
