print(f"  Directional Accuracy  : {dir_acc_1d:.2f}%")
print(f"  Log Return % Range    : {np.mean(ranges_pct_1d):.2f}% (Min: {np.min(ranges_pct_1d):.2f}%, Max: {np.max(ranges_pct_1d):.2f}%)")
print(f"  Index Point Range     : {np.mean(point_ranges_1d):.1f} pts (Min: {np.min(point_ranges_1d):.1f}, Max: {np.max(point_ranges_1d):.1f})")
print("-" * 70)
