# 6. Plotting Functions
def plot_log_returns(actuals, lowers, uppers, means, title):
    plt.figure(figsize=(16, 6))
    x_axis = np.arange(len(actuals))

    plt.plot(x_axis, actuals, color='black', marker='o', markersize=2, label='Actual Log Return', alpha=0.7, linewidth=0.8)
    plt.plot(x_axis, means, color='purple', linestyle='-', linewidth=1.5, alpha=0.9, label='Predicted Median (50th Pct)')
    plt.plot(x_axis, uppers, color='green', linestyle='--', alpha=0.7, label='Predicted Upside (90th Pct)')
    plt.plot(x_axis, lowers, color='red', linestyle='--', alpha=0.7, label='Predicted Downside (10th Pct)')

    plt.fill_between(x_axis, lowers, uppers, color='blue', alpha=0.1, label='Target Scaled Confidence Zone')

    ranges_pct = (np.array(uppers) - np.array(lowers)) * 100
    min_idx = np.argmin(ranges_pct)
    max_idx = np.argmax(ranges_pct)

    plt.vlines(x=min_idx, ymin=lowers[min_idx], ymax=uppers[min_idx], color='gold', linewidth=3, label=f'Min Volatility Event ({ranges_pct[min_idx]:.2f}%)', zorder=4)
    plt.vlines(x=max_idx, ymin=lowers[max_idx], ymax=uppers[max_idx], color='darkorange', linewidth=3, label=f'Max Volatility Event ({ranges_pct[max_idx]:.2f}%)', zorder=4)

    plt.axhline(0, color='gray', linestyle=':', alpha=0.5)
    plt.title(title, fontsize=14, fontweight='bold')
    plt.xlabel("Walk-Forward Test Days (Chronological)", fontsize=12)
    plt.ylabel("Log Return", fontsize=12)
    plt.legend(loc='upper left')
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

def plot_absolute_prices(actuals, lowers, uppers, means, title):
    plt.figure(figsize=(16, 6))
    x_axis = np.arange(len(actuals))

    plt.plot(x_axis, actuals, color='black', marker='o', markersize=2, label='Actual Target Close Price', alpha=0.7, linewidth=1)
    plt.plot(x_axis, means, color='purple', linestyle='-', linewidth=1.5, alpha=0.9, label='Predicted Target Price')
    plt.plot(x_axis, uppers, color='green', linestyle='-', linewidth=1, alpha=0.8, label='Upper Bound (Short Call Strike)')
    plt.plot(x_axis, lowers, color='red', linestyle='-', linewidth=1, alpha=0.8, label='Lower Bound (Short Put Strike)')

    plt.fill_between(x_axis, lowers, uppers, color='blue', alpha=0.1, label='Iron Condor Profit Zone')

    breach_indices = np.where((actuals < lowers) | (actuals > uppers))[0]
    plt.scatter(breach_indices, actuals[breach_indices], color='red', s=25, zorder=5, label='Price Breach (Loss Event)')

    plt.title(title, fontsize=14, fontweight='bold')
    plt.xlabel("Walk-Forward Test Days (Chronological)", fontsize=12)
    plt.ylabel("NIFTY 50 Index Points", fontsize=12)
    plt.legend(loc='upper left')
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

# 7. Generate All 4 Plots
plot_log_returns(actuals_1d, lowers_1d, uppers_1d, means_1d, "PLOT 1: 1D Ahead Forecast vs Actual (Log Returns Scale)")
plot_absolute_prices(actual_prices_1d, lower_bounds_1d, upper_bounds_1d, means_prices_1d, "PLOT 2: 1D Ahead Forecast vs Actual (Underlying NIFTY Points)")

plot_log_returns(actuals_5d, lowers_5d, uppers_5d, means_5d, "PLOT 3: 5D Ahead Forecast vs Actual (Log Returns Scale)")
plot_absolute_prices(actual_prices_5d, lower_bounds_5d, upper_bounds_5d, means_prices_5d, "PLOT 4: 5D Ahead Forecast vs Actual (Underlying NIFTY Points)")

