def calc_concordance(feat_col, expected_relation):
    if expected_relation == 'positive':
        match = ((eda_df[feat_col] > 0) & (eda_df[target] > 0)) | ((eda_df[feat_col] < 0) & (eda_df[target] < 0))
    else:
        match = ((eda_df[feat_col] > 0) & (eda_df[target] < 0)) | ((eda_df[feat_col] < 0) & (eda_df[target] > 0))
    return match.mean() * 100

