print(f"Intraday Crude Oil (Expected -) : {calc_concordance('Intraday_Drift_crudeoil', 'negative'):.2f}% alignment")

# --- SECTION 2: SIGNAL-TO-NOISE RATIO (SNR) ---
print("\n[2] CONDITIONAL SIGNAL-TO-NOISE RATIO (Annualized)")
print("Formula: (Mean Nifty Return | Condition) / (Std Dev Nifty Return | Condition) * sqrt(252)")
print("-" * 80)

def calc_snr(condition):
    subset = eda_df[condition][target]
    if len(subset) < 10: return 0.0, 0, 0.0
    mean_ret = subset.mean()
    std_ret = subset.std()
    snr = (mean_ret / std_ret) * np.sqrt(252) if std_ret > 0 else 0
    return snr, len(subset), mean_ret * 100

conditions = {
    "S&P 500 Overnight is UP": eda_df['Overnight_Momentum_sp500'] > 0,
    "S&P 500 Overnight is DOWN": eda_df['Overnight_Momentum_sp500'] < 0,
    "Crude Oil Overnight is UP": eda_df['Overnight_Momentum_crudeoil'] > 0,
    "Crude Oil Overnight is DOWN": eda_df['Overnight_Momentum_crudeoil'] < 0,
    "Options Skew is POSITIVE (Fear)": eda_df['Options_Skew_25d'] > 0,
    "Options Skew is NEGATIVE (Greed)": eda_df['Options_Skew_25d'] < 0,
}

print(f"{'Condition':<35} | {'Days':<5} | {'Avg 1D Ret':<10} | {'Target SNR'}")
for name, cond in conditions.items():
    snr, count, mean_ret = calc_snr(cond)
    print(f"{name:<35} | {count:<5} | {mean_ret:>8.3f}% | {snr:>8.2f}")


# --- SECTION 3: ASYMMETRIC FEATURE COMBINATIONS ---
print("\n[3] ASYMMETRIC FEATURE COMBINATIONS (High Conviction Setups)")
print("Testing overlapping extreme conditions for directional edge.")
print("-" * 80)

combo_1 = (eda_df['Overnight_Momentum_sp500'] < 0) & (eda_df['Overnight_Momentum_crudeoil'] > 0)
combo_2 = (eda_df['Overnight_Momentum_sp500'] > 0) & (eda_df['Overnight_Momentum_crudeoil'] < 0)
combo_3 = (eda_df['Overnight_Momentum_sp500'] < 0) & (eda_df['Overnight_Momentum_hang_seng'] < 0)
combo_4 = (eda_df['Options_Skew_25d'] > np.percentile(eda_df['Options_Skew_25d'], 80)) & (eda_df['Overnight_Momentum_sp500'] < 0)

def evaluate_combo(mask, expected_dir):
    subset = eda_df[mask][target]
    if len(subset) == 0: return "No events"
    win_rate = (subset < 0).mean() * 100 if expected_dir == 'down' else (subset > 0).mean() * 100
    return f"Events: {len(subset):<4} | Expected: {expected_dir.upper():<4} | Realized Win Rate: {win_rate:.1f}% | Avg Move: {subset.mean()*100:.3f}%"

print(f"S&P Down AND Crude Up          -> {evaluate_combo(combo_1, 'down')}")
print(f"S&P Up   AND Crude Down        -> {evaluate_combo(combo_2, 'up')}")
print(f"S&P Down AND Hang Seng Down    -> {evaluate_combo(combo_3, 'down')}")
print(f"Extreme Options Skew + S&P Down-> {evaluate_combo(combo_4, 'down')}")

