"""#### b. Implementation of Variable Selection Network and Asymmetric Feature Combinations along with a Directional Penalty in the Loss Function

Tried Approaches -
- Single two tower model for predicting direction and a range around it.
- Separate directional and variance prediction models.
- Adding a range width loss component to limit average range.
- Adding 40th and 60th %ile predictions to tighten the net range in the pinball loss.

Best Found Approach so far -
- Range width loss component combined with pinball loss in the variance engine. Adding a deep cross talk between directional and variance engines to leverage the directional accuracy. A very small weight (0.01) given to range width loss component minimises the hit rate loss occuring as a consequence.
- 40th and 60th %ile addition.
"""

# ================================================================================
# CELL 1 — DATA PREPARATION
# Changes vs previous:
#   + GEX columns loaded via direct merge from skew parquet when not present in
#     master file — eliminates need to regenerate master file for feature changes.
#   + All other features and config values UNCHANGED.
# ================================================================================

