# ── Schedule / contract parameters ───────────────────────────────────────────
EXPIRY_SHIFT_DATE = pd.Timestamp("2025-09-01")  # Thu→Tue from this date

def nifty_lot_size(dt: pd.Timestamp) -> int:
    d = dt.date() if hasattr(dt, 'date') else dt
    if d < pd.Timestamp("2024-05-01").date():   return 50
    elif d < pd.Timestamp("2024-12-01").date(): return 25
    else:                                        return 75

CONFIG = {
    "num_runs"                  : 1,
    "seq_len_1d"                : 10,
    "d_model"                   : 48,
    "nhead"                     : 4,
    "dropout"                   : 0.3,
    "num_grn_layers"            : 3,
    "epochs"                    : 45,
    "batch_size"                : 64,
    "lr"                        : 0.001,
    "use_lr_scheduler"          : True,
    "n_ensembles"               : 5,
    "dir_weight"                : 1.5,
    "outer_quantile_weight"     : 1.5,
    "inner_quantile_weight"     : 0.75,
    "df"                        : 4.5,
    "outer_ci_pct"              : 85,
    "inner_ci_pct"              : 20,
    "inner_outer_ratio_weight"  : 0.50,
    "dir_feature_subsample_ratio": 0.75,
    "aux_task_weight"           : 0.0,
    "attn_decay_rate"           : 0.20,
    "test_size"                 : 180,
    "purge_gap"                 : 15,
    "anchor_epoch_multiplier"   : 1.5,
    # Width loss: 0.0 = disabled → exact prior model, no gradient change.
    "width_cos_weight"          : 0.0,
}

_df_param = CONFIG["df"]
inner_q = (1 + CONFIG["inner_ci_pct"] / 100) / 2
outer_q = (1 + CONFIG["outer_ci_pct"] / 100) / 2
CONFIG["inner_outer_ratio_target"] = round(
    t.ppf(inner_q, _df_param) / t.ppf(outer_q, _df_param), 3)
print(f"IO Ratio Target: {CONFIG['inner_outer_ratio_target']:.03f}")

# 1. Load Data
processed_dir   = Path("/content/drive/MyDrive/Processed Trading Data")
master_out_file = processed_dir / "nifty_master_file.parquet"
df_pl = pl.read_parquet(master_out_file)
df_pd = df_pl.to_pandas()
df_pd['Date'] = pd.to_datetime(df_pd['Date'])

# 2. Vol-Regime Awareness Features (UNCHANGED)
df_pd['Vol_Change_1D']     = df_pd['Realized_Vol_Ann'].pct_change(1).clip(-2, 2)
df_pd['Vol_Change_5D']     = df_pd['Realized_Vol_Ann'].pct_change(5).clip(-2, 2)
df_pd['Vol_of_Vol_10D']    = df_pd['Realized_Vol_Ann'].rolling(10).std()
df_pd['Recent_Max_AbsRet'] = df_pd['Target_Ret_1D'].shift(1).abs().rolling(5).max()

# 3. Momentum Consistency Features (UNCHANGED)
for col in ['Overnight_Momentum_sp500', 'Overnight_Momentum_crudeoil',
            'Overnight_Momentum_hang_seng']:
    sign_col = np.sign(df_pd[col])
    df_pd[f'{col}_Consist_3D'] = sign_col.rolling(3).sum()
    df_pd[f'{col}_Consist_5D'] = sign_col.rolling(5).sum()

# 4. Vol-of-Vol Features (UNCHANGED)
df_pd['VoV_5D'] = df_pd['Realized_Vol_Ann'].rolling(5).std()
df_pd['Vol_Regime_Zscore'] = (
    (df_pd['Realized_Vol_Ann'] - df_pd['Realized_Vol_Ann'].rolling(20).mean()) /
    (df_pd['Realized_Vol_Ann'].rolling(20).std() + 1e-6)
).clip(-3, 3)
df_pd['Recent_Vol_Drawdown'] = (
    df_pd['Realized_Vol_Ann'] /
    (df_pd['Realized_Vol_Ann'].rolling(10).max() + 1e-6)
).clip(0.05, 1.5)
df_pd['Vol_MA_Ratio'] = (
    df_pd['Realized_Vol_Ann'].rolling(5).mean() /
    (df_pd['Realized_Vol_Ann'].rolling(20).mean() + 1e-6)
).clip(0.1, 5.0)

# 5. New Feature Groups (UNCHANGED)
_close   = df_pd['Spot_Close']
_open    = df_pd['Spot_Open']
_high    = df_pd['Spot_High']
_low     = df_pd['Spot_Low']
_vol     = df_pd['Realized_Vol_Ann']
_hist_lr = np.log(_close / _close.shift(1))

# Group A: Intraday Candle Structure
_hl_range = np.log(_high / _low).clip(0, 0.10)
df_pd['HL_Range_Zscore'] = (
    (_hl_range - _hl_range.rolling(20, min_periods=5).mean()) /
    (_hl_range.rolling(20, min_periods=5).std() + 1e-6)
).clip(-3, 3)
df_pd['Overnight_Gap_Abs'] = np.log(_open / _close.shift(1)).abs().clip(0, 0.05)
_upper_shadow = np.log(_high / np.maximum(_open, _close)).clip(0, 0.05)
_lower_shadow = np.log(np.minimum(_open, _close) / _low).clip(0, 0.05)
df_pd['Shadow_Imbalance'] = (_lower_shadow - _upper_shadow).clip(-0.05, 0.05)

# Group B: Vol-Regime Transition (UNCHANGED)
_down_ret = _hist_lr.where(_hist_lr < 0, 0.0)
_up_ret   = _hist_lr.where(_hist_lr > 0, 0.0)
df_pd['SemiVar_Down_10D'] = (
    _down_ret.rolling(10, min_periods=5).std() * np.sqrt(252)
).clip(0, 1.5).fillna(0)
df_pd['SemiVar_Up_10D'] = (
    _up_ret.rolling(10, min_periods=5).std() * np.sqrt(252)
).clip(0, 1.5).fillna(0)
df_pd['SemiVar_Ratio_10D'] = (
    df_pd['SemiVar_Down_10D'] / (df_pd['SemiVar_Up_10D'] + 1e-6)
).clip(0.1, 5.0)
_below_mean = (_vol < _vol.rolling(20, min_periods=5).mean()).astype(int)
_streak, _s = [], 0
for v in _below_mean:
    _s = _s + 1 if v else 0
    _streak.append(_s)
df_pd['Vol_Compression_Streak'] = np.log1p(np.array(_streak, dtype=np.float32))
df_pd['Vol_Accel_3D'] = (_vol / (_vol.shift(3) + 1e-6)).clip(0.2, 5.0)

# Group C/D: NIFTY-Native Directional Signals
df_pd['NIFTY_Overnight_Gap'] = np.log(_open / _close.shift(1)).clip(-0.05, 0.05)
df_pd['NIFTY_Intraday_Ret']  = np.log(_close / _open).clip(-0.05, 0.05)
_intra_sign = np.sign(df_pd['NIFTY_Intraday_Ret'])
df_pd['NIFTY_Intraday_Consist_3D'] = _intra_sign.rolling(3).sum()
df_pd['NIFTY_Intraday_Consist_5D'] = _intra_sign.rolling(5).sum()
df_pd['PCR_OI_Change_1D'] = df_pd['PCR_OI'].pct_change(1).clip(-2, 2)
df_pd['PCR_OI_Zscore'] = (
    (df_pd['PCR_OI'] - df_pd['PCR_OI'].rolling(20, min_periods=5).mean()) /
    (df_pd['PCR_OI'].rolling(20, min_periods=5).std() + 1e-6)
).clip(-3, 3)

# ── DTE Regime Features (UNCHANGED) ──────────────────────────────────────────
def _next_expiry_date(ts: pd.Timestamp) -> pd.Timestamp:
    target_dow = 1 if ts >= EXPIRY_SHIFT_DATE else 3
    days_ahead = (target_dow - ts.weekday()) % 7
    return ts + pd.Timedelta(days=days_ahead)

_dte_raw = df_pd['Date'].apply(
    lambda d: (_next_expiry_date(d) - d).days
).astype(int)

df_pd['DTE_R0_Expiry']  = (_dte_raw == 0).astype(np.float32)
df_pd['DTE_R1_PreExp']  = (_dte_raw == 1).astype(np.float32)
df_pd['DTE_R2_MidWeek'] = (_dte_raw.isin([2, 3])).astype(np.float32)
df_pd['DTE_R3_PostExp'] = (_dte_raw.isin([4, 5, 6])).astype(np.float32)

df_pd['DTE_PostExp_x_SP500Mom'] = (
    df_pd['DTE_R3_PostExp'] * df_pd['Overnight_Momentum_sp500']
).astype(np.float32)

