def plot_shifted_predictions_plotly(dates, actuals, lowers, uppers, means, title):
    fig    = go.Figure()
    ranges = np.array(uppers) - np.array(lowers)
    min_idx, max_idx = np.argmin(ranges), np.argmax(ranges)
    fig.add_trace(go.Scatter(x=list(dates) + list(dates)[::-1],
        y=list(uppers) + list(lowers)[::-1],
        fill='toself', fillcolor='rgba(0,0,255,0.1)',
        line=dict(color='rgba(255,255,255,0)'), name='85% CI'))
    fig.add_trace(go.Scatter(x=dates, y=uppers, mode='lines',
        line=dict(color='green', dash='dash'), name='Upside bound'))
    fig.add_trace(go.Scatter(x=dates, y=lowers, mode='lines',
        line=dict(color='red', dash='dash'), name='Downside bound'))
    fig.add_trace(go.Scatter(x=dates, y=means, mode='lines',
        line=dict(color='purple', width=2), name='Directional core'))
    fig.add_trace(go.Scatter(x=dates, y=actuals, mode='markers+lines',
        line=dict(color='black', width=1), marker=dict(size=4), name='Actual'))
    fig.add_trace(go.Scatter(x=[dates[max_idx]], y=[uppers[max_idx]],
        mode='markers', marker=dict(size=14, symbol='star', color='darkorange'),
        name='Max range'))
    fig.add_annotation(x=dates[max_idx], y=uppers[max_idx],
        text=f"Max<br>{ranges[max_idx]*100:.2f}%",
        showarrow=True, ax=0, ay=-40, font=dict(color='darkorange', size=10))
    fig.add_trace(go.Scatter(x=[dates[min_idx]], y=[lowers[min_idx]],
        mode='markers', marker=dict(size=14, symbol='star', color='gold'),
        name='Min range'))
    fig.add_annotation(x=dates[min_idx], y=lowers[min_idx],
        text=f"Min<br>{ranges[min_idx]*100:.2f}%",
        showarrow=True, ax=0, ay=40, font=dict(color='goldenrod', size=10))
    fig.update_layout(title=title, xaxis_title='Prediction date (T)',
        yaxis_title='Log return', hovermode='x unified',
        template='plotly_white', height=600)
    fig.show()


