    print(f"\n  [11] Model Confidence Set  (α = 10%, block={mcs['block_size']})")
    print(f"       t_R = {mcs['t_R']:+.4f}   p_MCS = {mcs['p_mcs']:.5f}")
    print(f"       Model in MCS : {'YES ✓' if mcs['model_in_mcs'] else ' NO ✗'}"
          f"   |   Naive in MCS : {'YES' if mcs['naive_in_mcs'] else ' NO'}")
    print(f"       {mcs['conclusion']}")

    # ══════════════════════════════════════════════════════════════════════════
    # [12]  Economic Value
