    ev_tag = "BEATS B&H ✓" if ev["model_beats_bh"] else "below B&H"
    print(f"\n  [12] Economic Value  "
          f"[γ={ev['risk_aversion']}, tc={ev['tc_bps']} bps]  [{ev_tag}]")
    print(f"       Sharpe (ann)  — Model : {ev['sharpe_model']:+.3f}"
          f"   B&H : {ev['sharpe_bh']:+.3f}")
    print(f"       CEQ (ann)     — Model : {ev['ceq_model_ann_pct']:+.3f}%"
          f"   B&H : {ev['ceq_bh_ann_pct']:+.3f}%"
          f"   Cash : {ev['ceq_cash_ann_pct']:+.3f}%")
    print(f"       EV vs B&H : {ev['ev_vs_bh_ann_pct']:+.3f}%"
          f"   EV vs Cash : {ev['ev_vs_cash_ann_pct']:+.3f}%")
    print(f"       Max DD — Model : {ev['max_drawdown_model_pct']:.2f}%"
          f"   B&H : {ev['max_drawdown_bh_pct']:.2f}%"
          f"   Mean |w| : {ev['mean_abs_position']:.3f}")

    # ══════════════════════════════════════════════════════════════════════════
    # [13]  Regime Stratification
    # ══════════════════════════════════════════════════════════════════════════
    tgt = rg["target_hr"]
    print(f"\n  [13] Regime-Conditional Stratification  (target HR = {tgt:.0f}%)")

    # (A) Volatility regimes
    _hdr = f"  {'Regime':<26} {'n':>5}  {'Vol Range':>12}  {'HR':>7}  " \
           f"{'Wink_m':>9}  {'Wink_n':>9}  {'Ratio':>6}  {'DirAcc':>7}  {'OK?':>4}"
    print(f"\n       -- (A) Volatility Regimes --")
    print(f"       {_hdr.strip()}")
    print(f"       {'-'*92}")
    for r in rg["vol_regimes"]:
        ok  = "YES" if r["coverage_ok"] else " NO"
        bt  = " ◀" if r["beats_naive"] else "  "
