        print(f"       {r['regime']:<26} {r['n']:>5}  {vr:>12}  "
              f"{r['hit_rate_pct']:>6.2f}%  "
              f"{r['mean_winkler']:>9.6f}  {r['naive_winkler']:>9.6f}  "
              f"{r['wink_ratio']:>6.3f}  "
              f"{r['dir_acc_pct']:>6.2f}%  {ok:>4}{bt}")

