print(f"""
Column guide:
  DM_p    Analytical HAC Diebold-Mariano p-value (two-sided)
  Q1HR    Hit-rate in tightest quintile (target = {100*(1-_CI_ALPHA):.0f}%)
  Kup     Kupiec unconditional coverage binomial test
  DirAcc  Directional accuracy (* = significant vs 50%)
  RankIC  Spearman rank IC (width vs |return|)
#   %BeatNv % of days model Winkler < naive Winkler
  CRPS_S  CRPS skill score vs zero-mean naive (>0 = better)
  OOS_R²  Out-of-sample R² vs zero-mean benchmark
  BB_p    Block-bootstrap DM p-value (two-sided)
  PIT     OK = KS test cannot reject U(0,1)  |  NG = non-uniform
  MCS     Model Confidence Set membership (IN / OUT at α=10%)
  EV_BH   Economic value vs buy-and-hold (ann. CEQ, % p.a.)

Zone key:
  A  = DM significant + Q1 coverage ≥ {100*(1-_CI_ALPHA):.0f}% → trade
  A- = directionally better but not yet significant → paper-trade
  B  = no detectable edge over rolling-vol naive
  C  = statistically worse than naive → recalibrate
{SEP}""")

