# ================================================================================
# CELL 9 — FULL-DATASET TRAINING & MODEL WEIGHT STORAGE
#
# PURPOSE:
#   Train a final production ensemble on the ENTIRE available dataset and persist
#   weights in both .pt (PyTorch) and .onnx formats. Produces a fully self-contained
#   metadata.json that is the single source of truth for inference — no notebook
#   cells, no training code, and no hardcoded CI values required downstream.
#
# DEPLOYMENT TARGET:
#   AWS Lambda + MongoDB
#     - Binary weight files (.pt / .onnx) → MongoDB GridFS
#     - metadata.json                     → MongoDB document (regular collection)
#     - Lambda reads metadata to reconstruct preprocessing, quantile labels,
#       architecture, and postprocessing without any reference to training code.
#
# DESIGN GUARANTEES:
#   1. ALL CI labels are generic (q_lower_outer, q_upper_inner, etc.) — derived
#      from CONFIG at runtime. No "85" or "20" hardcoded anywhere.
#   2. Metadata carries a complete inference_spec: feature order, scaler params,
#      vol-scaling method, output names, quantile levels, and a step-by-step
#      inference recipe. If architecture or features change, re-running this
#      cell regenerates a fully up-to-date spec.
#   3. Per-model dir-feature subsets are preserved in both .pt checkpoints and
#      baked into their corresponding ONNX graphs, so each ensemble member is
#      independently loadable.
#   4. dte_state_idx is included in arch (was missing in prior version).
#   5. ONNX export failures are caught and logged — the .pt path always succeeds.
# ================================================================================

import json
import math
import torch
import torch.nn as nn
import numpy as np
from datetime import datetime
from pathlib import Path
from sklearn.preprocessing import StandardScaler
from torch.utils.data import DataLoader

print("=" * 72)
print("CELL 9: FULL-DATASET FINAL MODEL TRAINING")
print("=" * 72)

# ── Output directory ──────────────────────────────────────────────────────────
FINAL_MODELS_DIR = Path("/content/drive/MyDrive/Final Models")
FINAL_MODELS_DIR.mkdir(parents=True, exist_ok=True)
print(f"\nOutput directory : {FINAL_MODELS_DIR}")

# ── Timestamp for this training run ──────────────────────────────────────────
_ts = datetime.now().strftime("%Y%m%d_%H%M%S")
print(f"Run timestamp    : {_ts}")

# ── Derive CI-band labels and quantile levels from CONFIG (no hardcoding) ─────
# These are computed once and referenced everywhere below so that changing
# outer_ci_pct / inner_ci_pct in CONFIG automatically flows through to all
# saved artefacts.
_outer_ci_pct  = CONFIG["outer_ci_pct"]          # e.g. 85
_inner_ci_pct  = CONFIG["inner_ci_pct"]          # e.g. 20
_outer_alpha   = (100 - _outer_ci_pct) / 200.0   # e.g. 0.075
_inner_alpha   = (100 - _inner_ci_pct) / 200.0   # e.g. 0.400

# Ordered to match model forward() output positions 0-4
_QUANTILE_LEVELS = [
    _outer_alpha,
    _inner_alpha,
    0.5,                     # expected_return (median/mean)
    1.0 - _inner_alpha,
    1.0 - _outer_alpha,
]

# Generic output names — no CI number baked into the string key
_OUTPUT_NAMES = [
    "q_lower_outer",         # position 0
    "q_lower_inner",         # position 1
    "expected_return",       # position 2
    "q_upper_inner",         # position 3
    "q_upper_outer",         # position 4
    "aux_pred",              # position 5  (auxiliary task head)
]

print(f"\nCI config        : outer={_outer_ci_pct}%, inner={_inner_ci_pct}%")
print(f"Quantile levels  : {[round(q, 4) for q in _QUANTILE_LEVELS]}")
print(f"Output names     : {_OUTPUT_NAMES}")

# ── Dataset info ──────────────────────────────────────────────────────────────
print(f"\nDataset size     : {len(X_raw)} rows")
print(f"Feature cols     : {len(feature_cols)} "
      f"({len(var_features)} var + {len(dir_features_1d)} dir)")
print(f"CONFIG snapshot  : d_model={CONFIG['d_model']} | nhead={CONFIG['nhead']} "
      f"| dropout={CONFIG['dropout']} | epochs={CONFIG['epochs']} "
      f"| n_ensembles={CONFIG['n_ensembles']}")

# ── Fit scalers on full dataset ───────────────────────────────────────────────
sc_std_final = StandardScaler()
sc_dir_final = StandardScaler(with_mean=False)

X_final = np.zeros_like(X_raw, dtype=np.float32)
X_final[:, VAR_IDX]     = sc_std_final.fit_transform(X_raw[:, VAR_IDX])
X_final[:, ALL_DIR_IDX] = sc_dir_final.fit_transform(X_raw[:, ALL_DIR_IDX])

# vol_raw: EWMA-smoothed Realized_Vol_Ann, used as per-sample divisor in training.
# At inference: compute the same EWMA on your live Realized_Vol_Ann series and
# use the latest value to scale model outputs back to return space.
dataset_final = NiftySequenceDataset(X_final, y_raw, vol_raw, CONFIG["seq_len_1d"])
loader_final  = DataLoader(
    dataset_final,
    batch_size=CONFIG["batch_size"],
    shuffle=True,
    drop_last=True,
)

print(f"\nTraining samples : {len(dataset_final)} sequences")
print(f"Batches/epoch    : {len(loader_final)}")
print("\nStarting full-dataset training...")

# ── Train ensemble on full data ───────────────────────────────────────────────
final_models, final_dir_idx_list = _train_ensemble(
    loader_tr      = loader_final,
    seq_len        = CONFIG["seq_len_1d"],
    dir_idx_tensor = IDX_DIR_1D,
    y_col          = 0,
    vol_scale_fn   = lambda vb: vb.unsqueeze(-1) + 1e-6,
    tag            = "FINAL",
)

# ── ONNX export wrapper ───────────────────────────────────────────────────────
class _ONNXInferenceWrapper(nn.Module):
    """
    Wraps AnchoredCrossAttentionTFT for ONNX export.

    Bakes idx_var and model_dir_idx as buffers so the exported graph accepts
    exactly ONE external input: the scaled feature sequence tensor x.

    Input
    -----
    x : float32  (batch_size, seq_len, n_total_features)
        Fully preprocessed — VAR features StandardScaler-normalised,
        DIR features StandardScaler(with_mean=False)-normalised.

    Outputs  (all float32, shape (batch_size, 1), in *normalised* return space)
    -------
    q_lower_outer   — lower bound of outer CI band
    q_lower_inner   — lower bound of inner CI band
    expected_return — point forecast
    q_upper_inner   — upper bound of inner CI band
    q_upper_outer   — upper bound of outer CI band
    aux_pred        — auxiliary task head (|return| prediction)

    Postprocessing
    --------------
    Multiply each output by vol_ewma (scalar, EWMA-span=10 of Realized_Vol_Ann)
    to convert from normalised space back to return space.
    For a 5-day horizon multiply by vol_ewma * sqrt(5) instead.
    """
    def __init__(self, model: nn.Module,
                 idx_var: torch.Tensor,
                 model_dir_idx: torch.Tensor):
        super().__init__()
        self.model = model
        self.register_buffer("_idx_var",       idx_var.long())
        self.register_buffer("_model_dir_idx", model_dir_idx.long())

    def forward(self, x: torch.Tensor):
        # Returns 6-tuple matching _OUTPUT_NAMES order
        return self.model(x, self._idx_var, self._model_dir_idx)


# ── Save model weights (.pt and .onnx) ───────────────────────────────────────
_ONNX_OPSET    = 18          # opset 18 — minimum for PyTorch 2.x TorchScript exporter
# NOTE: dynamo=False is set on every torch.onnx.export call below.
# The dynamo-based exporter (default in PyTorch ≥2.1) has no decomposition for
# aten.median.dim (used in RobustInstanceNorm) and fails with a DispatchError.
# The legacy TorchScript exporter (dynamo=False) supports torch.median natively
# and is stable for this model graph.
_seq_len       = CONFIG["seq_len_1d"]
_n_total_feats = len(feature_cols)

saved_pt_paths   = []
saved_onnx_paths = []
onnx_export_log  = []        # per-model export status for metadata

for i, (model, model_dir_idx) in enumerate(zip(final_models, final_dir_idx_list)):
    model.eval()
    is_anchor = (i == 0)
    _base_name = f"nifty_1d_{_ts}_model{i + 1}"

    # ── .pt checkpoint ───────────────────────────────────────────────────────
    pt_path = FINAL_MODELS_DIR / f"{_base_name}.pt"
    torch.save(
        {
            # ── Weights ──────────────────────────────────────────────────────
            "state_dict"      : model.state_dict(),

            # ── Per-model index tensors ───────────────────────────────────────
            # model_dir_idx may be a subsampled subset of IDX_DIR_1D for
            # non-anchor ensemble members (dir_feature_subsample_ratio < 1.0).
            "model_dir_idx"   : model_dir_idx.cpu(),
            "VAR_IDX"         : VAR_IDX,
            "DIR_IDX_1D"      : DIR_IDX_1D,         # full dir set (reference)
            "ALL_DIR_IDX"     : ALL_DIR_IDX,
            "VOL_STATE_IDX"   : VOL_STATE_IDX,
            "DTE_STATE_IDX"   : DTE_STATE_IDX,

            # ── Scalers ───────────────────────────────────────────────────────
            "sc_std_mean"     : sc_std_final.mean_.tolist(),
            "sc_std_scale"    : sc_std_final.scale_.tolist(),
            "sc_dir_scale"    : sc_dir_final.scale_.tolist(),

            # ── Architecture (complete — enough to reconstruct model object) ──
            "arch": {
                "num_var_feats" : len(VAR_IDX),
                "num_dir_feats" : int(len(model_dir_idx)),   # this model's dir count
                "vol_state_idx" : VOL_STATE_IDX,
                "dte_state_idx" : DTE_STATE_IDX,             # was missing in prior ver.
                "seq_len"       : _seq_len,
                "d_model"       : CONFIG["d_model"],
                "nhead"         : CONFIG["nhead"],
                "dropout"       : CONFIG["dropout"],
                "num_targets"   : 1,
                "num_grn_layers": CONFIG["num_grn_layers"],
                "decay_rate"    : CONFIG["attn_decay_rate"],
            },

            # ── Inference metadata ────────────────────────────────────────────
            "output_names"    : _OUTPUT_NAMES,
            "quantile_levels" : _QUANTILE_LEVELS,
            "outer_ci_pct"    : _outer_ci_pct,
            "inner_ci_pct"    : _inner_ci_pct,
            "vol_ewma_span"   : 10,
            "is_anchor"       : is_anchor,
            "timestamp"       : _ts,
        },
        pt_path,
    )
    saved_pt_paths.append(str(pt_path))
    print(f"  [pt  ] Saved model {i + 1}: {pt_path.name}")

    # ── .onnx export ─────────────────────────────────────────────────────────
    onnx_path   = FINAL_MODELS_DIR / f"{_base_name}.onnx"
    onnx_status = "ok"
    onnx_error  = None

    try:
        _wrapper = _ONNXInferenceWrapper(
            model,
            IDX_VAR.cpu(),
            model_dir_idx.cpu(),
        ).cpu()
        _wrapper.eval()

        # Dummy input: batch=1, seq_len, all features
        _dummy = torch.zeros(1, _seq_len, _n_total_feats, dtype=torch.float32)

        with torch.no_grad():
            torch.onnx.export(
                _wrapper,
                _dummy,
                str(onnx_path),
                dynamo              = False,     # force legacy TorchScript exporter;
                                                 # dynamo exporter lacks aten.median.dim
                opset_version       = _ONNX_OPSET,
                input_names         = ["feature_sequence"],
                output_names        = _OUTPUT_NAMES,
                dynamic_axes        = {
                    "feature_sequence": {0: "batch_size"},
                    **{name: {0: "batch_size"} for name in _OUTPUT_NAMES},
                },
                do_constant_folding = True,
                export_params       = True,
            )

        # Sanity-check: reload and run dummy inference
        import onnxruntime as ort
        _sess    = ort.InferenceSession(str(onnx_path),
                                        providers=["CPUExecutionProvider"])
        _out     = _sess.run(None, {"feature_sequence": _dummy.numpy()})
        assert len(_out) == 6, "ONNX output count mismatch"
        saved_onnx_paths.append(str(onnx_path))
        print(f"  [onnx] Saved model {i + 1}: {onnx_path.name}  (opset {_ONNX_OPSET})")

    except ImportError:
        onnx_status = "skipped_no_onnxruntime"
        onnx_error  = "onnxruntime not installed — .onnx file written but not verified"
        # Still attempt export even without ort for validation
        try:
            torch.onnx.export(
                _wrapper, _dummy, str(onnx_path),
                dynamo=False,
                opset_version=_ONNX_OPSET,
                input_names=["feature_sequence"],
                output_names=_OUTPUT_NAMES,
                dynamic_axes={"feature_sequence": {0: "batch_size"},
                              **{n: {0: "batch_size"} for n in _OUTPUT_NAMES}},
                do_constant_folding=True, export_params=True,
            )
            saved_onnx_paths.append(str(onnx_path))
            print(f"  [onnx] Saved model {i + 1}: {onnx_path.name}  "
                  f"(unverified — install onnxruntime to validate)")
        except Exception as _e2:
            onnx_status = "failed"
            onnx_error  = str(_e2)
            print(f"  [onnx] ⚠  Export FAILED for model {i + 1}: {_e2}")

    except Exception as _e:
        onnx_status = "failed"
        onnx_error  = str(_e)
        print(f"  [onnx] ⚠  Export FAILED for model {i + 1}: {_e}")
        print(f"           .pt checkpoint is unaffected and fully usable.")

    onnx_export_log.append({
        "model_index" : i + 1,
        "status"      : onnx_status,
        "error"       : onnx_error,
        "onnx_file"   : onnx_path.name if onnx_status != "failed" else None,
    })

