import gc
import json
import torch
import torch.nn as nn
import numpy as np
from pathlib import Path
from collections import namedtuple

# ── The timestamp Cell 9 printed ─────────────────────────────────────────────
_CONVERT_TIMESTAMP = _ts
_ONNX_OPSET  = 17
_MODELS_DIR  = FINAL_MODELS_DIR

# ── Load onnxruntime ─────────────────────────────────────────────────────────
try:
    import onnxruntime as ort
except ImportError:
    raise ImportError("onnxruntime not installed. Run: !pip install onnxruntime -q")

print("=" * 68)
print("CELL 10: PT → ONNX CONVERSION")
print("=" * 68)

# ── Traceable Median Patch ───────────────────────────────────────────────────
# This replaces torch.median with a sort-based version that ONNX can export.
# It mimics the return type (namedtuple of values/indices) used by torch.median.
def traceable_median(input, dim=None, keepdim=False):
    if dim is None:
        # Global median: sort flattened and pick middle
        flat = input.view(-1)
        k = (flat.numel() - 1) // 2
        return flat.sort().values[k]
    else:
        # Median along dim: sort and slice middle index
        sorted_tensor = input.sort(dim=dim).values
        k = (input.shape[dim] - 1) // 2
        values = sorted_tensor.narrow(dim, k, 1)
        if not keepdim:
            values = values.squeeze(dim)

        # Create a dummy indices tensor to match torch.median signature
        indices = torch.zeros_like(values, dtype=torch.long)
        MedianResults = namedtuple('MedianResults', ['values', 'indices'])
        return MedianResults(values, indices)

# ── Load metadata ──────────────────────────────────────────────────────────────
_meta_path = _MODELS_DIR / f"nifty_1d_{_CONVERT_TIMESTAMP}_meta.json"
with open(_meta_path, encoding="utf-8") as _fh:
    _meta = json.load(_fh)

_n_total_feats = _meta["feature_registry"]["n_total_features"]
_seq_len       = _meta["config"]["seq_len_1d"]
_output_names  = _meta["output_spec"]["output_names"]

# ── ONNX wrapper ──────────────────────────────────────────────────────────────
class _ONNXWrapper(nn.Module):
    def __init__(self, model: nn.Module, idx_var: torch.Tensor, model_dir_idx: torch.Tensor):
        super().__init__()
        self.model = model
        self.register_buffer("_idx_var", idx_var.long())
        self.register_buffer("_model_dir_idx", model_dir_idx.long())

    def forward(self, x: torch.Tensor):
        return self.model(x, self._idx_var, self._model_dir_idx)

# ── Conversion Loop ──────────────────────────────────────────────────────────
_dummy = torch.zeros(1, _seq_len, _n_total_feats, dtype=torch.float32)
_onnx_log_new = {}
converted, failed = [], []

# Save original median to restore later
original_median = torch.median

for _member in _meta["model_files"]:
    _midx = _member["model_index"]
    _pt_name = _member.get("pt_file")
    _onnx_name = f"nifty_1d_{_CONVERT_TIMESTAMP}_model{_midx}.onnx"
    _onnx_path = _MODELS_DIR / _onnx_name

    print(f"\n[model {_midx}]")

    if not _pt_name or not (_MODELS_DIR / _pt_name).exists():
        print(f"  SKIP — File not found")
        failed.append(_midx)
        continue

    _ckpt = torch.load(_MODELS_DIR / _pt_name, map_location="cpu", weights_only=False)
    _model = AnchoredCrossAttentionTFT(**_ckpt["arch"])
    _model.load_state_dict(_ckpt["state_dict"])
    _model.eval()

    _wrapper = _ONNXWrapper(_model, torch.tensor(VAR_IDX), _ckpt["model_dir_idx"].cpu())
    _wrapper.eval()

    try:
        # --- APPLY PATCH ---
        torch.median = traceable_median

        with torch.no_grad():
            torch.onnx.export(
                _wrapper, _dummy, str(_onnx_path),
                dynamo=False,
                training=torch.onnx.TrainingMode.TRAINING,
                opset_version=_ONNX_OPSET,
                input_names=["feature_sequence"],
                output_names=_output_names,
                dynamic_axes={"feature_sequence": {0: "batch_size"},
                              **{n: {0: "batch_size"} for n in _output_names}},
                do_constant_folding=False,
                export_params=True
            )

        # --- RESTORE ORIGINAL ---
        torch.median = original_median

        # Validation
        _sess = ort.InferenceSession(str(_onnx_path), providers=["CPUExecutionProvider"])
        _ort_out = _sess.run(None, {"feature_sequence": _dummy.numpy()})

        print(f"  OK    {_onnx_name} ({_onnx_path.stat().st_size/1024:.1f} KB)")
        converted.append(_midx)
        _onnx_log_new[_midx] = {"onnx_file": _onnx_name, "status": "ok"}

    except Exception as _e:
        torch.median = original_median # Ensure restoration on failure
        print(f"  FAIL  {_e}")
        failed.append(_midx)
        _onnx_log_new[_midx] = {"onnx_file": None, "status": "failed", "error": str(_e)}

    finally:
        del _model, _wrapper, _ckpt
        gc.collect()

# ── Patch metadata.json ──────────────────────────────────────────────────────
_meta_changed = False
for _member in _meta["model_files"]:
    _idx = _member["model_index"]
    if _idx in _onnx_log_new:
        _log = _onnx_log_new[_idx]
        _member["onnx_file"] = _log["onnx_file"]
        _member["onnx_export_status"] = _log["status"]
        _meta_changed = True

if _meta_changed:
    _meta["all_onnx_files"] = [f"nifty_1d_{_CONVERT_TIMESTAMP}_model{i}.onnx" for i in converted]
    with open(_meta_path, "w", encoding="utf-8") as _fh:
        json.dump(_meta, _fh, indent=2, default=str)
    print(f"\nMetadata updated: {_meta_path.name}")

print(f"\nCONVERSION COMPLETE. Converted: {len(converted)}, Failed: {len(failed)}")

