# ==============================================================================
# CELL 3 — HANSEN (1994) SKEWED STUDENT-t DISTRIBUTION
# Full implementation: log-PDF, CDF (closed-form), PPF (numerical inversion)
# ==============================================================================

class HansenSkewT:
    """
    Hansen's (1994) standardized Skewed Student-t distribution.

    Parameterisation:
        eta  (float > 2)  : degrees of freedom
        lam  (float ∈ (-1,1)) : skewness; lam<0 → left-skewed, lam>0 → right-skewed

    The distribution is standardized: E[Z]=0, Var[Z]=1.

    PDF:
        f(z; η, λ) = bc · (1 + (bz+a)² / [(1±λ)²(η-2)])^{-(η+1)/2}
        where the ± switches at threshold z* = -a/b.

    The CDF has a closed form via the standard Student-t CDF (scipy.stats.t).
    The PPF is obtained by numerical inversion of the CDF.

    Reference:
        Hansen, B.E. (1994). Autoregressive Conditional Density Estimation.
        International Economic Review, 35(3), 705–730.
    """

    @staticmethod
    def _abc(eta: float, lam: float):
        """
        Compute the three constants a, b, c in Hansen (1994).

        c  = Γ((η+1)/2) / (√(π(η-2)) · Γ(η/2))   [normalisation]
        a  = 4λc(η-2)/(η-1)                         [mean correction]
        b  = √(1 + 3λ² - a²)                        [scale correction so Var=1]
        """
        log_c = gammaln((eta + 1) / 2) - 0.5 * np.log(np.pi * (eta - 2)) - gammaln(eta / 2)
        c = np.exp(log_c)
        a = 4.0 * lam * c * (eta - 2.0) / (eta - 1.0)
        b = np.sqrt(1.0 + 3.0 * lam**2 - a**2)
        return a, b, c

    @classmethod
    def logpdf(cls, z, eta: float, lam: float):
        """
        Log-PDF: log f(z; η, λ).

        Gradient w.r.t. parameters exists everywhere except at z = -a/b.
        Safe for use in log-likelihood maximisation.
        """
        z   = np.asarray(z, dtype=np.float64)
        a, b, c = cls._abc(eta, lam)

        bza   = b * z + a
        left  = z < (-a / b)
        scale = np.where(left, 1.0 - lam, 1.0 + lam)     # denominator per side

        # Core: -(η+1)/2 · log(1 + u²/(η-2)),   u = bza/scale
        u          = bza / scale
        log_kernel = -(eta + 1.0) / 2.0 * np.log1p(u**2 / (eta - 2.0))

        return np.log(b) + np.log(c) + log_kernel

    @classmethod
    def cdf(cls, z, eta: float, lam: float):
        """
        CDF via closed-form mapping to scipy Student-t CDF.

        Derivation:
          The density in each half is a scaled, shifted standard-t kernel.
          Integrating piece-wise and matching at z* = -a/b gives:

          F(z) = (1-λ) · T_η(u_L · √(η/(η-2)))       for z < z*
          F(z) = (1+λ) · T_η(u_R · √(η/(η-2))) - λ   for z ≥ z*

          where T_η = scipy.stats.t CDF with df=η,
                u_L = (bz+a)/(1-λ),  u_R = (bz+a)/(1+λ).

          The factor √(η/(η-2)) converts from the variance-1 standardised-t
          parameterisation (which Hansen uses) to scipy's parameterisation
          (which has variance η/(η-2)).
        """
        z   = np.atleast_1d(np.asarray(z, dtype=np.float64))
        a, b, _ = cls._abc(eta, lam)
        sf  = np.sqrt(eta / (eta - 2.0))    # standardisation factor

        res   = np.empty_like(z)
        left  = z < (-a / b)

        if left.any():
            u = (b * z[left] + a) / (1.0 - lam) * sf
            res[left] = (1.0 - lam) * scipy_stats.t.cdf(u, df=eta)

        if (~left).any():
            u = (b * z[~left] + a) / (1.0 + lam) * sf
            res[~left] = (1.0 + lam) * scipy_stats.t.cdf(u, df=eta) - lam

        return float(res[0]) if res.size == 1 else res

    @classmethod
    def ppf(cls, p, eta: float, lam: float, tol: float = 1e-10):
        """
        Percent-point function (quantile function) by numerically inverting the CDF.

        Uses scipy.optimize.brentq. Bracket is ±40 standard deviations,
        which is sufficient even for η=2.1 (very fat tails).
        """
        p   = np.atleast_1d(np.asarray(p, dtype=np.float64))
        out = np.empty_like(p)

        for i, pi in enumerate(p):
            if pi <= 0.0:
                out[i] = -np.inf; continue
            if pi >= 1.0:
                out[i] =  np.inf; continue
            f = lambda z: cls.cdf(z, eta, lam) - pi
            # Start with ±10; expand if needed (protects against very fat tails)
            lo, hi = -10.0, 10.0
            for _ in range(20):
                if f(lo) < 0: break
                lo *= 2.0
            for _ in range(20):
                if f(hi) > 0: break
                hi *= 2.0
            out[i] = brentq(f, lo, hi, xtol=tol, maxiter=200)

        return float(out[0]) if out.size == 1 else out


def _validate_skewt():
    """Sanity checks on the HansenSkewT implementation."""
    print("Validating HansenSkewT...")

    # 1. At lam=0 the distribution is symmetric: median = 0
    q50 = HansenSkewT.ppf(0.5, eta=5.0, lam=0.0)
    assert abs(q50) < 1e-6, f"PPF(0.5) should be 0 at lam=0, got {q50}"

    # 2. CDF is the inverse of PPF
    for tau in [0.05, 0.25, 0.50, 0.75, 0.95]:
        z = HansenSkewT.ppf(tau, eta=6.0, lam=0.1)
        p = HansenSkewT.cdf(z, eta=6.0, lam=0.1)
        assert abs(p - tau) < 1e-8, f"CDF(PPF({tau})) = {p:.8f}, expected {tau}"

    # 3. Log-PDF integrates to ~1
    zz  = np.linspace(-10, 10, 2000)
    dz  = zz[1] - zz[0]
    pdf = np.exp(HansenSkewT.logpdf(zz, eta=5.0, lam=-0.2))
    integral = np.sum(pdf) * dz
    assert abs(integral - 1.0) < 1e-3, f"PDF integral = {integral:.5f}, expected 1.0"

    # 4. Skewness direction check (sign of skew, not median vs 0)
    #    Hansen Skew-t is standardised to mean=0, Var=1.
    #    For left-skew (lam<0): mean < median, and since mean=0, median > 0.
    #    For right-skew (lam>0): mean > median, and since mean=0, median < 0.
    med_neg = HansenSkewT.ppf(0.5, eta=5.0, lam=-0.3)
    assert med_neg > 0, (
        f"Left-skew (lam<0): distribution is standardised so mean=0. "
        f"For negative skew, median > mean = 0. Got median={med_neg:.5f}"
    )
    med_pos = HansenSkewT.ppf(0.5, eta=5.0, lam=+0.3)
    assert med_pos < 0, (
        f"Right-skew (lam>0): median < mean = 0. Got median={med_pos:.5f}"
    )

    # 5. Asymmetry check: outer quantiles are wider on the skewed side
    #    lam < 0 (left-skew): left tail heavier → q_0.075 further from 0 than q_0.925
    lo = abs(HansenSkewT.ppf(0.075, eta=5.0, lam=-0.3))
    hi = abs(HansenSkewT.ppf(0.925, eta=5.0, lam=-0.3))
    assert lo > hi, f"Left-skew: |q_0.075|={lo:.4f} should exceed |q_0.925|={hi:.4f}"

    print("  All checks passed.")
    print(f"  PPF(0.075, η=5, λ=−0.1) = {HansenSkewT.ppf(0.075, 5.0, -0.1):.4f}")
    print(f"  PPF(0.925, η=5, λ=−0.1) = {HansenSkewT.ppf(0.925, 5.0, -0.1):.4f}")
    print(f"  Median at λ=−0.3        = {HansenSkewT.ppf(0.5,   5.0, -0.3):.4f}  (>0, correct)")
    print(f"  Median at λ=+0.3        = {HansenSkewT.ppf(0.5,   5.0, +0.3):.4f}  (<0, correct)")


_validate_skewt()

# ==============================================================================
# CELL 4 — GJR-GARCH-X MODEL
#
# Model equations:
#   Mean:     r_t = μ + φ·r_{t-1} + δ'·z_t^{dir} + ε_t
#   Variance: h_t = ω + (α + γ·I_{t-1})·ε_{t-1}² + β·h_{t-1} + θ'·z_t^{var}
#   Innovation: ε_t = √h_t · u_t,   u_t ~ SkewT(η, λ)
#   Leverage indicator: I_{t-1} = 1{ε_{t-1} < 0}
#   Stationarity: α + γ/2 + β < 1
#
# Parameter vector (packed):
#   [μ, φ, δ₁..δ_K, ω, α, γ, β, θ₁..θ_M, η, λ]
#   where K = n_dir_pcs, M = n_var_pcs
# ==============================================================================

class GJRGARCHXModel:
    """
    GJR-GARCH(1,1)-X with ARMAX(1) mean and Hansen Skewed-t distribution.

    The model captures:
      - Volatility clustering (GARCH α, β terms)
      - Leverage effect: negative shocks raise variance more (GJR γ term)
      - Cross-asset directional signals in the mean (z_t^{dir} PCs)
      - Options/vol-regime signals in the variance (z_t^{var} PCs)
      - Fat tails and asymmetry via the Skewed Student-t distribution
    """

    def __init__(self, n_dir_pcs: int = 2, n_var_pcs: int = 2):
        self.n_dir_pcs = n_dir_pcs
        self.n_var_pcs = n_var_pcs
        self.params_   = None
        self.h_in_     = None     # in-sample conditional variances
        self.eps_in_   = None     # in-sample residuals
        self.y_last_   = None     # last in-sample return (for AR(1) initialisation)
        self.loglik_   = None
        self.aic_      = None
        self.bic_      = None
        self.fitted_   = False

    # ── Parameter packing ─────────────────────────────────────────────────────

    def _n_params(self):
        return 2 + self.n_dir_pcs + 4 + self.n_var_pcs + 2

    def _unpack(self, p):
        i = 0
        mu    = p[i]; i += 1
        phi   = p[i]; i += 1
        delta = p[i:i + self.n_dir_pcs]; i += self.n_dir_pcs
        omega = p[i]; i += 1
        alpha = p[i]; i += 1
        gam   = p[i]; i += 1
        beta  = p[i]; i += 1
        theta = p[i:i + self.n_var_pcs]; i += self.n_var_pcs
        eta   = p[i]; i += 1
        lam   = p[i]; i += 1
        return mu, phi, delta, omega, alpha, gam, beta, theta, eta, lam

    def _pack(self, mu, phi, delta, omega, alpha, gam, beta, theta, eta, lam):
        return np.concatenate([[mu, phi], delta, [omega, alpha, gam, beta], theta, [eta, lam]])

    # ── GJR-GARCH-X filter ────────────────────────────────────────────────────

    @staticmethod
    def _filter(y, x_mean, x_var, mu, phi, delta, omega, alpha, gam, beta, theta,
                y_lag_init=0.0, h_init=None, eps_init=0.0):
        """
        Sequential GJR-GARCH-X filter.

        Arguments:
            y           : (T,) returns
            x_mean      : (T, K) directional PCs
            x_var       : (T, M) variance PCs
            mu..lam     : model parameters
            y_lag_init  : r_{t-1} for the first step (last training return for OOS)
            h_init      : h_{t-1} for the first step (None → use unconditional var)
            eps_init    : ε_{t-1} for the first step (last training residual for OOS)

        Returns:
            eps : (T,) residuals r_t - μ_t
            h   : (T,) conditional variances (BEFORE observing r_t)
        """
        T      = len(y)
        K      = len(delta)
        M      = len(theta)
        eps    = np.empty(T)
        h      = np.empty(T)

        # Build mean (fully vectorized — no sequential dependency in ARMAX mean)
        y_lag     = np.empty(T)
        y_lag[0]  = y_lag_init
        y_lag[1:] = y[:-1]

        mean_t = mu + phi * y_lag
        if K > 0:
            mean_t = mean_t + x_mean @ delta
        eps_arr = y - mean_t          # all residuals

        # Unconditional variance as default h_init
        sig2_unc = np.var(eps_arr) if h_init is None else h_init

        eps_prev = eps_init
        h_prev   = sig2_unc

        for t in range(T):
            ind   = 1.0 if eps_prev < 0.0 else 0.0
            h_t   = omega + (alpha + gam * ind) * eps_prev**2 + beta * h_prev
            if M > 0:
                h_t = h_t + float(np.dot(theta, x_var[t]))
            h_t   = max(h_t, 1e-12)    # variance floor for numerical stability

            h[t]      = h_t
            eps[t]    = eps_arr[t]
            eps_prev  = eps_arr[t]
            h_prev    = h_t

        return eps, h

    # ── Negative log-likelihood ───────────────────────────────────────────────

    def _negloglik(self, p, y, x_mean, x_var):
        try:
            mu, phi, delta, omega, alpha, gam, beta, theta, eta, lam = self._unpack(p)

            # Hard parameter constraints (return large penalty if violated)
            if omega <= 1e-12: return 1e12
            if alpha < 0.0:   return 1e12
            if gam   < 0.0:   return 1e12
            if beta  < 0.0:   return 1e12
            if alpha + gam / 2.0 + beta >= 0.9999: return 1e12   # stationarity
            if eta   <= 2.01:  return 1e12
            if abs(lam) >= 0.9999: return 1e12

            eps, h = self._filter(y, x_mean, x_var,
                                  mu, phi, delta, omega, alpha, gam, beta, theta)

            # Standardised residuals: z_t = ε_t / √h_t
            z    = eps / np.sqrt(h)

            # Log-likelihood per observation:
            #   log p(r_t) = log f_SkewT(z_t) − ½ log h_t
            ll   = HansenSkewT.logpdf(z, eta, lam) - 0.5 * np.log(h)

            val  = -np.sum(ll)
            return val if np.isfinite(val) else 1e12

        except Exception:
            return 1e12

    # ── Fit ──────────────────────────────────────────────────────────────────

    def fit(self, y, x_mean, x_var, verbose=True):
        """
        Fit GJR-GARCH-X via maximum likelihood estimation (L-BFGS-B).

        Args:
            y       : (T,) raw log-returns
            x_mean  : (T, K) standardised directional PCs
            x_var   : (T, M) standardised variance PCs
            verbose : print fit summary

        Returns self.
        """
        T  = len(y)
        s2 = float(np.var(y))

        # ── Starting values ────────────────────────────────────────────────────
        # Based on stylized facts of equity index daily returns:
        #   β ≈ 0.85-0.90 (high persistence), α ≈ 0.05-0.10, γ ≈ 0.05 (leverage),
        #   ω = σ²_unc · (1 - α - γ/2 - β)
        base_starts = [
            # (beta_init, alpha_init, gam_init, eta_init, lam_init)
            (0.85, 0.06, 0.06, 8.0,  -0.10),
            (0.88, 0.05, 0.05, 5.0,  -0.05),
            (0.80, 0.10, 0.08, 12.0, -0.15),
            (0.90, 0.04, 0.04, 6.0,   0.00),
        ]

        best_val, best_res = np.inf, None

        for b0, a0, g0, e0, l0 in base_starts[:GARCH_CFG['n_restarts']]:
            om0  = max(s2 * (1.0 - a0 - g0 / 2.0 - b0), 1e-8)
            p0   = self._pack(
                np.mean(y), 0.01,                     # mu, phi
                np.zeros(self.n_dir_pcs),              # delta
                om0, a0, g0, b0,                       # omega, alpha, gamma, beta
                np.zeros(self.n_var_pcs),              # theta
                e0, l0                                  # eta, lam
            )

            # Parameter bounds
            bounds = (
                [(-0.05,  0.05)]                           +   # mu
                [(-0.3,   0.3)]                            +   # phi
                [(-5.0,   5.0)] * self.n_dir_pcs           +   # delta
                [(1e-10,  s2 * 0.5)]                       +   # omega
                [(0.0,    0.45)]                           +   # alpha
                [(0.0,    0.45)]                           +   # gamma (leverage)
                [(0.01,   0.999)]                          +   # beta
                [(-3.0,   3.0)] * self.n_var_pcs           +   # theta
                [(2.05,   50.0)]                           +   # eta
                [(-0.95,  0.95)]                               # lam
            )

            try:
                res = minimize(
                    self._negloglik, p0, args=(y, x_mean, x_var),
                    method='L-BFGS-B', bounds=bounds,
                    options={'maxiter': GARCH_CFG['max_iter'],
                             'ftol': 1e-12, 'gtol': 1e-8}
                )
                if np.isfinite(res.fun) and res.fun < best_val:
                    best_val, best_res = res.fun, res
            except Exception as e:
                if verbose:
                    print(f"      Start failed: {e}")

        if best_res is None:
            raise RuntimeError("All optimisation starts failed. Check data quality.")

        # ── Extract parameters ─────────────────────────────────────────────────
        p = best_res.x
        mu, phi, delta, omega, alpha, gam, beta, theta, eta, lam = self._unpack(p)

        self.params_ = dict(mu=mu, phi=phi, delta=delta,
                            omega=omega, alpha=alpha, gamma=gam,
                            beta=beta, theta=theta, eta=eta, lam=lam,
                            persistence=alpha + gam / 2.0 + beta)

        # In-sample filter (for OOS initialisation)
        self.eps_in_, self.h_in_ = self._filter(
            y, x_mean, x_var, mu, phi, delta, omega, alpha, gam, beta, theta
        )
        self.y_last_ = float(y[-1])

        # Information criteria
        T_fit        = T
        self.loglik_ = -best_val
        self.aic_    = -2.0 * self.loglik_ + 2.0 * self._n_params()
        self.bic_    = -2.0 * self.loglik_ + self._n_params() * np.log(T_fit)
        self.fitted_ = True

        if verbose:
            p = self.params_
            print(f"      μ={p['mu']:.5f}  φ={p['phi']:.4f}  ω={p['omega']:.2e}")
            print(f"      α={p['alpha']:.4f}  γ={p['gamma']:.4f}  β={p['beta']:.4f}")
            print(f"      Persistence={p['persistence']:.4f}  η={p['eta']:.2f}  λ={p['lam']:.4f}")
            print(f"      LogLik={self.loglik_:.2f}  AIC={self.aic_:.2f}  BIC={self.bic_:.2f}")

        return self

    # ── Out-of-sample one-step-ahead filter ───────────────────────────────────

    def forecast_oos(self, y_oos, x_mean_oos, x_var_oos):
        """
        One-step-ahead OOS forecasts using fixed in-sample parameters.

        The variance filter is initialised from the terminal in-sample state
        (h_{T_train}, ε_{T_train}) and the AR(1) mean uses r_{T_train} as the
        first lag.  Parameters are kept fixed at MLE estimates.

        Returns:
            mu_t   : (T_oos,) conditional mean forecasts
            sigma_t: (T_oos,) conditional std dev forecasts
            h_t    : (T_oos,) conditional variance forecasts
        """
        assert self.fitted_, "Call .fit() first."
        T_oos = len(y_oos)
        p = self.params_

        # Mean equation (vectorised)
        y_lag = np.empty(T_oos)
        y_lag[0]  = self.y_last_        # last in-sample return
        y_lag[1:] = y_oos[:-1]
        mu_t = p['mu'] + p['phi'] * y_lag
        if self.n_dir_pcs > 0:
            mu_t = mu_t + x_mean_oos @ p['delta']

        # Variance filter (initialised from in-sample terminal state)
        eps_oos    = y_oos - mu_t       # actual OOS residuals (needed to advance filter)
        h_oos      = np.empty(T_oos)
        eps_prev   = float(self.eps_in_[-1])
        h_prev     = float(self.h_in_[-1])

        for t in range(T_oos):
            ind   = 1.0 if eps_prev < 0.0 else 0.0
            h_t   = (p['omega']
                     + (p['alpha'] + p['gamma'] * ind) * eps_prev**2
                     + p['beta'] * h_prev)
            if self.n_var_pcs > 0:
                h_t += float(np.dot(p['theta'], x_var_oos[t]))
            h_t   = max(h_t, 1e-12)

            h_oos[t]  = h_t
            eps_prev  = eps_oos[t]      # update filter with actual residual
            h_prev    = h_t

        return mu_t, np.sqrt(h_oos), h_oos

# ==============================================================================
# CELL 5 — PCA DIMENSIONALITY REDUCTION UTILITIES
#
# Purpose: compress 21 directional features → K PCs (mean equation exogenous)
#          compress 30 variance features    → M PCs (variance equation exogenous)
#
# CRITICAL: Both StandardScaler and PCA are fitted ONLY on training data and
#           then applied (transform-only) to the test data.
#           Fitting on the full dataset would constitute look-ahead leakage.
# ==============================================================================

class FoldPCA:
    """
    Per-fold PCA pipeline.  Fitted on training data, applied to test data.
    Separate pipelines for directional and variance feature groups.
    """

    def __init__(self, n_dir_pcs: int = 2, n_var_pcs: int = 2):
        self.n_dir_pcs    = n_dir_pcs
        self.n_var_pcs    = n_var_pcs
        self.scaler_dir_  = None
        self.scaler_var_  = None
        self.pca_dir_     = None
        self.pca_var_     = None
        self.var_dir_     = None   # explained variance ratios
        self.var_var_     = None

    def fit_transform(self, X_dir_tr, X_var_tr):
        """
        Fit scalers and PCAs on training data, transform training data.
        Returns (dir_pcs_train, var_pcs_train).
        """
        # Directional features → K PCs for mean equation
        self.scaler_dir_ = StandardScaler()
        self.pca_dir_    = PCA(n_components=self.n_dir_pcs, random_state=42)
        dir_pcs_tr = self.pca_dir_.fit_transform(
            self.scaler_dir_.fit_transform(X_dir_tr)
        )
        self.var_dir_ = self.pca_dir_.explained_variance_ratio_

        # Variance features → M PCs for variance equation
        self.scaler_var_ = StandardScaler()
        self.pca_var_    = PCA(n_components=self.n_var_pcs, random_state=42)
        var_pcs_tr = self.pca_var_.fit_transform(
            self.scaler_var_.fit_transform(X_var_tr)
        )
        self.var_var_ = self.pca_var_.explained_variance_ratio_

        return dir_pcs_tr.astype(np.float64), var_pcs_tr.astype(np.float64)

    def transform(self, X_dir_te, X_var_te):
        """
        Apply fitted scalers and PCAs to test data (no refitting).
        Returns (dir_pcs_test, var_pcs_test).
        """
        assert self.pca_dir_ is not None, "Call fit_transform() first."
        dir_pcs_te = self.pca_dir_.transform(
            self.scaler_dir_.transform(X_dir_te)
        )
        var_pcs_te = self.pca_var_.transform(
            self.scaler_var_.transform(X_var_te)
        )
        return dir_pcs_te.astype(np.float64), var_pcs_te.astype(np.float64)

    def summary(self, fold: int):
        print(f"  [Fold {fold}] PCA explained variance:")
        print(f"    Dir PCs ({self.n_dir_pcs}): " +
              "  ".join(f"PC{i+1}={v:.1%}" for i, v in enumerate(self.var_dir_)))
        print(f"    Var PCs ({self.n_var_pcs}): " +
              "  ".join(f"PC{i+1}={v:.1%}" for i, v in enumerate(self.var_var_)))

# ==============================================================================
# CELL 6 — WALK-FORWARD VALIDATION ENGINE
#
# Replicates the exact six-fold rolling walk-forward from the report.
# For each fold:
#   1. Extract train / test splits (with 15-day purge gap)
#   2. Fit PCA on training data → transform both splits
#   3. Fit GJR-GARCH-X on training returns + PCs
#   4. Filter OOS to get μ_t, σ_t, h_t for each test day
#   5. Compute analytical quantiles from Skewed-t(μ_t, σ_t, η_hat, λ_hat)
#   6. Collect results into the same dict format used by the ML model
#
# The first (seq_len-1 = 9) rows of each test fold are skipped to maintain
# identical test dates with the ML model's sequence-based dataset.
# ==============================================================================

def generate_quantiles(mu: np.ndarray, sigma: np.ndarray, eta: float, lam: float):
    """
    Compute the five quantile outputs matching the ML model format.

    q_{7.5}, q_{40}, μ, q_{60}, q_{92.5}

    The quantiles of r_t | F_{t-1} under the GJR-GARCH-X model are:
        q_τ(t) = μ_t + σ_t · PPF_SkewT(τ; η, λ)

    This is an exact analytical result (modulo numerical PPF precision).
    No simulation or bootstrapping needed.
    """
    # Pre-compute PPF values (scalar, same for all t since η, λ are scalars)
    ppf_outer_lo = HansenSkewT.ppf(Q_LEVELS['outer_lo'], eta, lam)
    ppf_inner_lo = HansenSkewT.ppf(Q_LEVELS['inner_lo'], eta, lam)
    ppf_inner_hi = HansenSkewT.ppf(Q_LEVELS['inner_hi'], eta, lam)
    ppf_outer_hi = HansenSkewT.ppf(Q_LEVELS['outer_hi'], eta, lam)

    q_out_lo = mu + sigma * ppf_outer_lo
    q_in_lo  = mu + sigma * ppf_inner_lo
    q_in_hi  = mu + sigma * ppf_inner_hi
    q_out_hi = mu + sigma * ppf_outer_hi

    return q_out_lo, q_in_lo, q_in_hi, q_out_hi


def run_walk_forward():
    """
    Execute the six-fold walk-forward and return fold-level and continuous results.
    """
    print("=" * 65)
    print("GARCH WALK-FORWARD VALIDATION  (6 folds)")
    print("=" * 65)

    skip       = GARCH_CFG['seq_len'] - 1    # = 9; to match ML model test dates
    n_dir      = GARCH_CFG['n_dir_pcs']
    n_var      = GARCH_CFG['n_var_pcs']

    fold_results = []      # per-fold series dicts
    fold_models  = []      # fitted model objects (for inspection)

    # Containers for the continuous (concatenated) WF series
    wf_actuals   = []
    wf_lo_out    = []
    wf_hi_out    = []
    wf_lo_in     = []
    wf_hi_in     = []
    wf_means     = []
    wf_vols_ann  = []
    wf_intra     = []
    wf_dates     = []

    for fold_idx, fold in enumerate(WF_FOLDS, start=1):
        tr_start, tr_end = fold['train']
        te_start, te_end = fold['test']

        # Guard: skip fold if insufficient data
        if te_end > N:
            te_end = N
        if te_start >= te_end:
            print(f"Fold {fold_idx}: insufficient data, stopping.")
            break

        n_test = te_end - te_start
        print(f"\n{'-'*55}")
        print(f"FOLD {fold_idx}  |  Train: {tr_start}–{tr_end}  "
              f"Test: {te_start}–{te_end}  [n≈{n_test}]")

        # ── Splits ───────────────────────────────────────────────────────────
        y_tr    = y_ret[tr_start:tr_end]
        y_te    = y_ret[te_start:te_end]
        Xd_tr   = X_dir_raw[tr_start:tr_end]
        Xd_te   = X_dir_raw[te_start:te_end]
        Xv_tr   = X_var_raw[tr_start:tr_end]
        Xv_te   = X_var_raw[te_start:te_end]
        v_te    = vol_ann_all[te_start:te_end]
        int_te  = intraday_dir_raw[te_start:te_end]
        d_te    = dates_all[te_start:te_end]

        # ── PCA (fit on train only) ───────────────────────────────────────────
        pca = FoldPCA(n_dir_pcs=n_dir, n_var_pcs=n_var)
        dir_pcs_tr, var_pcs_tr = pca.fit_transform(Xd_tr, Xv_tr)
        dir_pcs_te, var_pcs_te = pca.transform(Xd_te, Xv_te)
        pca.summary(fold_idx)

        # ── Fit GJR-GARCH-X ──────────────────────────────────────────────────
        print(f"  Fitting GJR-GARCH({n_var})-X({n_dir})...")
        model = GJRGARCHXModel(n_dir_pcs=n_dir, n_var_pcs=n_var)
        model.fit(y_tr, dir_pcs_tr, var_pcs_tr, verbose=True)
        fold_models.append(model)

        eta_hat = model.params_['eta']
        lam_hat = model.params_['lam']

        # ── OOS filter ───────────────────────────────────────────────────────
        mu_oos, sig_oos, h_oos = model.forecast_oos(y_te, dir_pcs_te, var_pcs_te)

        # ── Quantiles ────────────────────────────────────────────────────────
        q_lo_out, q_lo_in, q_hi_in, q_hi_out = generate_quantiles(
            mu_oos, sig_oos, eta_hat, lam_hat
        )

        # ── Skip first (seq_len-1) rows to align dates with ML model ─────────
        s = skip
        actuals_f  = y_te[s:]
        means_f    = mu_oos[s:]
        lo_out_f   = q_lo_out[s:]
        hi_out_f   = q_hi_out[s:]
        lo_in_f    = q_lo_in[s:]
        hi_in_f    = q_hi_in[s:]
        vols_f     = v_te[s:]
        intra_f    = int_te[s:]
        dates_f    = d_te[s:]

        n_valid = len(actuals_f)

        # Intraday directional accuracy
        valid_mask   = intra_f != 0
        n_intra      = int(valid_mask.sum())
        dir_intraday = float('nan')
        p_intraday   = float('nan')
        if n_intra > 0:
            hits_i     = int((np.sign(means_f[valid_mask]) == intra_f[valid_mask]).sum())
            dir_intraday = hits_i / n_intra * 100
            p_intraday = float(
                scipy_stats.binomtest(hits_i, n_intra, 0.5, alternative='two-sided').pvalue
            )

        hr_out = float(np.mean((lo_out_f <= actuals_f) & (actuals_f <= hi_out_f)) * 100)
        hr_in  = float(np.mean((lo_in_f  <= actuals_f) & (actuals_f <= hi_in_f))  * 100)
        dir_ctc = float(np.mean(np.sign(means_f) == np.sign(actuals_f)) * 100)

        print(f"  [Fold {fold_idx}] 85% HR={hr_out:.2f}%  "
              f"20% HR={hr_in:.2f}%  "
              f"Dir C2C={dir_ctc:.2f}%  "
              f"η={eta_hat:.2f}  λ={lam_hat:.4f}")
        print(f"           Dir Intra={dir_intraday:.2f}%  "
              f"(n={n_intra}, p={p_intraday:.4f})")

        series = {
            'actuals'      : actuals_f.astype(np.float32),
            'lowers_out'   : lo_out_f.astype(np.float32),
            'uppers_out'   : hi_out_f.astype(np.float32),
            'lowers_in'    : lo_in_f.astype(np.float32),
            'uppers_in'    : hi_in_f.astype(np.float32),
            'means'        : means_f.astype(np.float32),
            'vols_ann'     : vols_f.astype(np.float32),
            'intraday_dirs': intra_f.astype(np.float32),
            'dates'        : dates_f,
            'eta'          : eta_hat,
            'lam'          : lam_hat,
        }
        fold_results.append(series)

        # Accumulate for continuous WF
        wf_actuals.append(actuals_f)
        wf_lo_out.append(lo_out_f)
        wf_hi_out.append(hi_out_f)
        wf_lo_in.append(lo_in_f)
        wf_hi_in.append(hi_in_f)
        wf_means.append(means_f)
        wf_vols_ann.append(vols_f)
        wf_intra.append(intra_f)
        wf_dates.append(dates_f)

    # ── Continuous (concatenated) series ─────────────────────────────────────
    wf_series = {
        'actuals'      : np.concatenate(wf_actuals).astype(np.float32),
        'lowers_out'   : np.concatenate(wf_lo_out).astype(np.float32),
        'uppers_out'   : np.concatenate(wf_hi_out).astype(np.float32),
        'lowers_in'    : np.concatenate(wf_lo_in).astype(np.float32),
        'uppers_in'    : np.concatenate(wf_hi_in).astype(np.float32),
        'means'        : np.concatenate(wf_means).astype(np.float32),
        'vols_ann'     : np.concatenate(wf_vols_ann).astype(np.float32),
        'intraday_dirs': np.concatenate(wf_intra).astype(np.float32),
        'dates'        : np.concatenate(wf_dates),
    }

    n_total = len(wf_series['actuals'])
    hr_cont = float(np.mean(
        (wf_series['lowers_out'] <= wf_series['actuals']) &
        (wf_series['actuals']    <= wf_series['uppers_out'])
    ) * 100)
    dir_cont = float(np.mean(
        np.sign(wf_series['means']) == np.sign(wf_series['actuals'])
    ) * 100)

    print(f"\n{'='*65}")
    print(f"WALK-FORWARD COMPLETE  (Total days: {n_total})")
    print(f"  85% Hit Rate : {hr_cont:.2f}%")
    print(f"  Dir C2C      : {dir_cont:.2f}%")
    print(f"{'='*65}")

    return fold_results, wf_series, fold_models

# ==============================================================================
# CELL 7 — STATISTICAL TEST SUITE
# Exact replication of the ML model's Cell 7 tests for direct comparability.
# Tests: DM, Conditional Coverage, Rank IC, Kupiec, Directional, Zone Classify
# ==============================================================================

def winkler_obs(actual, lower, upper, alpha=_CI_ALPHA):
    """Per-observation Winkler score (interval width + miss penalty)."""
    w  = upper - lower
    pl = np.where(actual < lower, (2 / alpha) * (lower - actual), 0.0)
    pu = np.where(actual > upper, (2 / alpha) * (actual - upper), 0.0)
    return w + pl + pu


def naive_bands(vols_ann, horizon_days=1, alpha=_CI_ALPHA):
    """Naive benchmark: rolling-vol band using the outer CI z-score."""
    z = scipy_stats.norm.ppf(1 - alpha / 2)
    per_period_sigma = vols_ann / np.sqrt(252) * np.sqrt(horizon_days)
    return -z * per_period_sigma, +z * per_period_sigma


def dm_test(series, horizon_days=1, alpha=_CI_ALPHA, label=""):
    """
    Diebold–Mariano (1995) test: model Winkler vs. naive rolling-vol Winkler.

    DM statistic:
        d̄ = mean(W_model - W_naive)
        DM = d̄ / SE_HAC(d)   ~  t_{n-1}

    For h=1-day horizon, HAC lag=0 (no multi-step overlap contamination).
    Negative DM  ⟹  model has lower average Winkler  ⟹  model wins.
    """
    a = series['actuals']
    l = series.get('lowers_out', series.get('lowers'))
    u = series.get('uppers_out', series.get('uppers'))
    v = series['vols_ann']
    n = len(a)

    lm    = winkler_obs(a, l, u, alpha)
    nl, nu = naive_bands(v, horizon_days, alpha)
    ln    = winkler_obs(a, nl, nu, alpha)

    d    = lm - ln
    d_bar = float(np.mean(d))
    lag   = max(horizon_days - 1, 0)

    # HAC variance with Bartlett kernel
    gamma_hat = float(np.var(d, ddof=1))
    for k in range(1, lag + 1):
        gk = float(np.mean((d[k:] - d_bar) * (d[:-k] - d_bar)))
        gamma_hat += 2.0 * (1.0 - k / (lag + 1.0)) * gk
    se = np.sqrt(max(gamma_hat, 1e-15) / n)

    dm_stat = d_bar / se
    p_value = float(scipy_stats.t.sf(abs(dm_stat), df=n - 1) * 2)

    return {
        'label': label, 'n': n, 'horizon_days': horizon_days,
        'dm_stat'              : round(float(dm_stat),     4),
        'p_value'              : round(p_value,            5),
        'model_wins'           : bool(dm_stat < 0 and p_value < 0.05),
        'directionally_better' : bool(dm_stat < 0),
        'model_mean_wink'      : round(float(np.mean(lm)), 6),
        'naive_mean_wink'      : round(float(np.mean(ln)), 6),
        'pct_days_model_wins'  : round(float(np.mean(lm < ln) * 100), 1),
        'mean_diff'            : round(float(d_bar),       6),
    }


def conditional_coverage(series, n_quintiles=5, alpha=_CI_ALPHA, label=""):
    """
    Conditional coverage by width quintile.

    Tests whether the model achieves the target hit rate (1-α = 85%) uniformly
    across tight and wide bands.  Failure at Q1 (tightest bands) indicates
    systematic overconfidence on low-volatility days.
    """
    a      = series['actuals']
    l      = series.get('lowers_out', series.get('lowers'))
    u      = series.get('uppers_out', series.get('uppers'))
    widths = u - l
    hits   = (l <= a) & (a <= u)
    target = (1.0 - alpha) * 100
    edges  = np.percentile(widths, np.linspace(0, 100, n_quintiles + 1))
    rows   = []

    for i in range(n_quintiles):
        lo_e = edges[i]; hi_e = edges[i + 1]
        mask = (widths >= lo_e) if i == n_quintiles - 1 else (widths >= lo_e) & (widths < hi_e)
        if mask.sum() == 0:
            continue
        hr_q   = float(hits[mask].mean() * 100)
        w_q    = float(widths[mask].mean() * 100)
        absa_q = float(np.abs(a[mask]).mean() * 100)
        eff_q  = float(widths[mask].mean() / (np.abs(a[mask]).mean() + 1e-9))
        rows.append({
            'quintile'       : i + 1,
            'n'              : int(mask.sum()),
            'width_range'    : (round(float(edges[i] * 100), 3), round(float(edges[i+1] * 100), 3)),
            'avg_width_pct'  : round(w_q, 3),
            'hit_rate_pct'   : round(hr_q, 2),
            'mean_abs_ret_pct': round(absa_q, 3),
            'width_eff'      : round(eff_q, 3),
            'coverage_ok'    : bool(hr_q >= target),
        })

    tight_ok = rows[0]['coverage_ok'] if rows else False
    return {
        'label': label, 'target_hr': target,
        'q1_coverage_ok': tight_ok,
        'q1_hr': rows[0]['hit_rate_pct'] if rows else None,
        'quintiles': rows,
    }


def rank_ic_test(series, label=""):
    """
    Rank Information Coefficient: Spearman ρ between band width and |actual return|.

    A positive, significant IC confirms the model has genuine uncertainty
    quantification skill — it correctly predicts which days are volatile.
    |IC| > 0.20 = strong, 0.10–0.20 = moderate, < 0.10 = weak.
    """
    a      = series['actuals']
    l      = series.get('lowers_out', series.get('lowers'))
    u      = series.get('uppers_out', series.get('uppers'))
    widths = u - l
    n      = len(a)
    ic, p  = scipy_stats.spearmanr(widths, np.abs(a))
    t_stat = float(ic) * np.sqrt((n - 2) / max(1.0 - float(ic)**2, 1e-12))
    level  = "strong" if abs(float(ic)) > 0.20 else "moderate" if abs(float(ic)) > 0.10 else "weak"
    return {
        'label': label, 'n': n,
        'rank_ic'     : round(float(ic),     4),
        'p_value'     : round(float(p),      5),
        't_stat'      : round(float(t_stat), 3),
        'skill_level' : level,
        'significant' : bool(float(p) < 0.05),
    }


def kupiec_test(series, alpha=_CI_ALPHA, label=""):
    """
    Kupiec (1995) Proportion-of-Failures (POF) test.

    H₀: violation rate = α  (unconditional correct coverage)
    Uses a two-sided binomial test.
    """
    a    = series['actuals']
    l    = series.get('lowers_out', series.get('lowers'))
    u    = series.get('uppers_out', series.get('uppers'))
    n    = len(a)
    hits = int(np.sum((l <= a) & (a <= u)))
    viols = n - hits
    obs_vr = viols / n
    z_stat = (obs_vr - alpha) / np.sqrt(alpha * (1 - alpha) / n)
    try:
        binom_p = float(scipy_stats.binomtest(viols, n, alpha, alternative='two-sided').pvalue)
    except AttributeError:
        binom_p = float(scipy_stats.binom_test(viols, n, alpha, alternative='two-sided'))
    return {
        'label': label, 'n': n,
        'expected_hr_pct'  : round((1 - alpha) * 100, 1),
        'observed_hr_pct'  : round(hits / n * 100, 2),
        'observed_viol_pct': round(obs_vr * 100, 2),
        'z_stat'           : round(float(z_stat), 3),
        'binom_p'          : round(binom_p, 5),
        'passes'           : bool(binom_p > 0.05),
    }


def christoffersen_test(actuals, lowers, uppers):
    """
    Christoffersen (1998) interval independence test.

    Tests H₀ that violations I_t are i.i.d. Bernoulli(α).
    A significant p-value indicates clustered violations (e.g. during a crash),
    which is a failure of the model to dynamically adjust its intervals.
    """
    hits = ((lowers <= actuals) & (actuals <= uppers)).astype(int)
    n    = len(hits)
    n00  = int(((hits[:-1] == 0) & (hits[1:] == 0)).sum())
    n01  = int(((hits[:-1] == 0) & (hits[1:] == 1)).sum())
    n10  = int(((hits[:-1] == 1) & (hits[1:] == 0)).sum())
    n11  = int(((hits[:-1] == 1) & (hits[1:] == 1)).sum())
    if (n00 + n01) == 0 or (n10 + n11) == 0:
        return {'p_value': 1.0, 'clustered': False}
    pi_01 = n01 / (n00 + n01)
    pi_10 = n10 / (n10 + n11)
    pi    = (n01 + n11) / max(n - 1, 1)
    if pi in (0.0, 1.0) or pi_01 in (0.0, 1.0) or pi_10 in (0.0, 1.0):
        return {'p_value': 1.0, 'clustered': False}
    try:
        lr = -2.0 * (
            n00 * np.log(max(1 - pi, 1e-10))     + n01 * np.log(max(pi, 1e-10))
          + n10 * np.log(max(1 - pi, 1e-10))     + n11 * np.log(max(pi, 1e-10))
          - n00 * np.log(max(1 - pi_01, 1e-10))  - n01 * np.log(max(pi_01, 1e-10))
          - n10 * np.log(max(1 - pi_10, 1e-10))  - n11 * np.log(max(pi_10, 1e-10))
        )
        p = float(1 - scipy_stats.chi2.cdf(lr, df=1))
    except Exception:
        p = 1.0
    return {'p_value': p, 'clustered': bool(p < 0.05)}


def directional_test(series, label=""):
    """
    One-sided binomial test: Is directional accuracy > 50%?

    Note: This uses p=0.5 as the null (same as ML model for comparability).
    The correct null is the historical up-day frequency (~51.3%), but
    we keep p=0.5 here to match the ML model's implementation exactly.
    """
    actuals   = series['actuals']
    forecasts = series['means']
    n         = len(actuals)
    hits      = int(np.sum(np.sign(actuals) == np.sign(forecasts)))
    acc       = hits / n
    try:
        p_value = float(scipy_stats.binomtest(hits, n, p=0.5, alternative='greater').pvalue)
    except AttributeError:
        p_value = float(scipy_stats.binom_test(hits, n, p=0.5, alternative='greater'))
    return {
        'label': label, 'n': n, 'hits': hits,
        'accuracy'    : round(acc * 100, 2),
        'p_value'     : round(p_value, 5),
        'significant' : bool(p_value < 0.05),
    }


def pit_test(series, label="", n_bins=10):
    """
    Probability Integral Transform (PIT) uniformity test.

    Under a correctly specified model, U_t = F_t(r_t) ~ Uniform[0,1].
    We compute U_t by evaluating the Skewed-t CDF at each observation and
    test uniformity via the KS test.

    This is a strictly stronger test than coverage: it checks the full
    distributional shape, not just tail probabilities.

    Returns:
        ks_stat  : Kolmogorov-Smirnov statistic
        ks_p     : p-value (large p = consistent with uniformity)
        pit_vals : array of U_t values (for histogram plotting)
    """
    actuals = series['actuals']
    means   = series['means']
    # We need sigma_t for each observation; approximate from band width
    # σ_t = (q_92.5 - q_7.5) / (PPF(0.925) - PPF(0.075))
    # Use the stored eta and lam to compute the denominator
    eta = series.get('eta', 5.0)
    lam = series.get('lam', -0.1)
    denom = (HansenSkewT.ppf(0.925, eta, lam) - HansenSkewT.ppf(0.075, eta, lam))
    denom = max(denom, 1e-6)
    lo_out = series.get('lowers_out', series.get('lowers'))
    hi_out = series.get('uppers_out', series.get('uppers'))
    sigma_approx = (hi_out - lo_out) / denom

    # Standardised residuals
    z = (actuals - means) / np.maximum(sigma_approx, 1e-8)

    # PIT values
    pit_vals = HansenSkewT.cdf(z, eta, lam)

    ks_stat, ks_p = scipy_stats.kstest(pit_vals, 'uniform')

    return {
        'label'   : label,
        'ks_stat' : round(float(ks_stat), 5),
        'ks_p'    : round(float(ks_p),    5),
        'uniform' : bool(ks_p > 0.05),
        'pit_vals': pit_vals,
    }


def classify_zone(dm, cc, ic, kup, dr, label=""):
    """Zone A/A-/B/C classification (identical logic to ML model Cell 7)."""
    dm_stat_neg = dm['dm_stat'] < 0
    dm_sig      = dm['p_value'] < 0.05
    q1_ok       = cc['q1_coverage_ok']
    dir_sig     = dr['significant']

    if dm_stat_neg and dm_sig and q1_ok:
        zone = "A"
        desc = (f"Model beats naive. Q1 stable. "
                f"Dir Acc: {dr['accuracy']}% ({'Sig' if dir_sig else 'Non-sig'})")
    elif dm_stat_neg and (not dm_sig or not q1_ok):
        zone = "A-"
        desc = "Model directionally better but DM not significant or Q1 borderline."
    elif not dm_stat_neg and dm_sig:
        zone = "C"
        desc = "Model statistically worse than naive. Recalibrate variance."
    else:
        zone = "B"
        desc = "No detectable edge over rolling-vol naive."

    return {
        'label': label, 'zone': zone, 'description': desc,
        'dm_stat': dm['dm_stat'], 'dm_p': dm['p_value'],
        'model_beats_naive'  : dm['directionally_better'],
        'dm_significant'     : bool(dm['model_wins'] or (dm['directionally_better'] and dm_sig)),
        'pct_days_model_wins': dm['pct_days_model_wins'],
        'q1_coverage_ok'     : q1_ok, 'q1_hr': cc['q1_hr'],
        'kupiec_passes'      : kup['passes'],
        'rank_ic'            : ic['rank_ic'],
        'rank_ic_significant': ic['significant'],
        'dir_acc': dr['accuracy'], 'dir_sig': dir_sig,
        'model_wink': dm['model_mean_wink'], 'naive_wink': dm['naive_mean_wink'],
    }


def run_full_test_suite(series, label="", verbose=True):
    """
    Run all six statistical tests on a given series dict.
    Returns a dict of all results.
    """
    dm  = dm_test(series,            label=label)
    cc  = conditional_coverage(series, label=label)
    ic  = rank_ic_test(series,       label=label)
    kup = kupiec_test(series,        label=label)
    dr  = directional_test(series,   label=label)
    pit = pit_test(series,           label=label)
    zn  = classify_zone(dm, cc, ic, kup, dr, label=label)

    # Christoffersen
    a   = series['actuals']
    l   = series.get('lowers_out', series.get('lowers'))
    u   = series.get('uppers_out', series.get('uppers'))
    chri = christoffersen_test(a, l, u)

    if verbose:
        print(f"\n{'─'*60}")
        print(f"  {label}  |  n={dm['n']}  |  1D horizon")
        print(f"{'─'*60}")
        print(f"  [1] DM: stat={dm['dm_stat']:+.4f}  p={dm['p_value']:.5f}  "
              f"{'[SIGNIFICANT]' if dm['model_wins'] else '[not significant]'}")
        print(f"       Model Wink={dm['model_mean_wink']:.6f}  "
              f"Naive Wink={dm['naive_mean_wink']:.6f}  "
              f"Days model tighter={dm['pct_days_model_wins']}%")
        print(f"  [2] Conditional Coverage by Width Quintile  (target HR = 85%)")
        print(f"      {'Q':<5} {'n':>5} {'Avg Width':>12} {'Hit Rate':>10} "
              f"{'Mean|Ret|':>10} {'Eff':>6}  OK?")
        print(f"      {'─'*58}")
        for q in cc['quintiles']:
            ok_str = "YES" if q['coverage_ok'] else " NO"
            key_str = "<-- KEY" if q['quintile'] == 1 else ""
            print(f"      Q{q['quintile']:<4} {q['n']:>5} "
                  f"{q['avg_width_pct']:>11.3f}% "
                  f"{q['hit_rate_pct']:>9.2f}% "
                  f"{q['mean_abs_ret_pct']:>9.3f}% "
                  f"{q['width_eff']:>6.2f}   {ok_str}  {key_str}")
        print(f"  [3] Rank IC: {ic['rank_ic']:+.4f}  "
              f"t={ic['t_stat']:+.3f}  p={ic['p_value']:.5f}  "
              f"({'significant' if ic['significant'] else 'not significant'})")
        print(f"  [4] Kupiec: HR={kup['observed_hr_pct']:.2f}%  "
              f"z={kup['z_stat']:.3f}  p={kup['binom_p']:.5f}  "
              f"[{'PASS' if kup['passes'] else 'FAIL'}]")
        print(f"  [5] Directional: Acc={dr['accuracy']:.2f}%  "
              f"p={dr['p_value']:.5f}  "
              f"({'SIGNIFICANT' if dr['significant'] else 'not significant'})")
        print(f"  [6] PIT (KS):  stat={pit['ks_stat']:.5f}  p={pit['ks_p']:.5f}  "
              f"({'Uniform ✓' if pit['uniform'] else 'NOT uniform ✗'})")
        print(f"  [7] Christoffersen: p={chri['p_value']:.4f}  "
              f"clustered={chri['clustered']}")
        print(f"\n  ·· ZONE {zn['zone']} ·· {zn['description']}")

    return dict(dm=dm, cc=cc, ic=ic, kup=kup, dr=dr, pit=pit,
                christo=chri, zone=zn)


