# ══════════════════════════════════════════════════════════════════════════════
# PART A — DATE ALIGNMENT
# Both models were trained on identical walk-forward folds and skip the first
# (seq_len - 1 = 9) rows of each test window.  The dates array stored in each
# series dict is used to inner-join on exact calendar dates.
# ══════════════════════════════════════════════════════════════════════════════

def _align_series(ml_series_list, garch_series_list):
    """
    Inner-join fold-level series on dates, then concatenate.
    Returns aligned (ml_dict, garch_dict) with identical length.
    """
    ml_parts    = {k: [] for k in ("actuals", "lowers_out", "uppers_out",
                                    "lowers_in", "uppers_in", "means",
                                    "vols_ann", "intraday_dirs")}
    garch_parts = {k: [] for k in ml_parts}
    common_dates = []

    for ml_s, g_s in zip(ml_series_list, garch_series_list):
        ml_dates    = pd.to_datetime(ml_s["dates"])
        garch_dates = pd.to_datetime(g_s["dates"])
        shared      = ml_dates.intersection(garch_dates)
        if len(shared) == 0:
            print(f"  WARNING: no overlapping dates for a fold — skipped.")
            continue

        ml_idx    = [np.where(ml_dates    == d)[0][0] for d in shared]
        garch_idx = [np.where(garch_dates == d)[0][0] for d in shared]

        for k in ml_parts:
            src = ml_s.get(k, ml_s.get(k.replace("_out", ""),
                              ml_s.get(k.replace("lowers_out", "lowers")
                                        .replace("uppers_out", "uppers"), None)))
            if src is not None:
                ml_parts[k].append(np.array(src)[ml_idx])

        for k in garch_parts:
            src = g_s.get(k, g_s.get(k.replace("_out", ""),
                             g_s.get(k.replace("lowers_out", "lowers")
                                      .replace("uppers_out", "uppers"), None)))
            if src is not None:
                garch_parts[k].append(np.array(src)[garch_idx])

        common_dates.append(shared)

    ml_aligned    = {k: np.concatenate(v).astype(np.float32)
                     for k, v in ml_parts.items() if v}
    garch_aligned = {k: np.concatenate(v).astype(np.float32)
                     for k, v in garch_parts.items() if v}
    all_dates     = np.concatenate(common_dates)

    return ml_aligned, garch_aligned, all_dates


print("\n[A] Aligning series on common calendar dates...")
ml_aln, g_aln, aligned_dates = _align_series(wf_series_1d, fold_results)
n_aligned = len(ml_aln["actuals"])
print(f"    Common observations: {n_aligned}  "
      f"(ML total={len(wf_continuous_1d['actuals'])}, "
      f"GARCH total={len(wf_series['actuals'])})")

# Verify actuals are identical (they should be — same test dates)
_max_diff = float(np.max(np.abs(ml_aln["actuals"] - g_aln["actuals"])))
print(f"    Max |actual_ML − actual_GARCH| = {_max_diff:.2e}  "
      f"({'OK — same actuals' if _max_diff < 1e-5 else 'WARNING — actuals differ, check folds'})")


# ══════════════════════════════════════════════════════════════════════════════
# PART B — DM TEST: ML vs GARCH BASELINE
# d_t = W_ML(t) − W_GARCH(t)
# d_bar < 0  ⟹  ML has lower mean Winkler  ⟹  ML beats GARCH
# ══════════════════════════════════════════════════════════════════════════════

def _winkler_obs(actual, lower, upper, alpha=_CI_ALPHA_LOCAL):
    w  = upper - lower
    pl = np.where(actual < lower, (2 / alpha) * (lower - actual), 0.0)
    pu = np.where(actual > upper, (2 / alpha) * (actual - upper), 0.0)
    return w + pl + pu


def dm_vs_garch(ml_s, g_s, alpha=_CI_ALPHA_LOCAL, horizon=1, label="",
                n_boot=2000, block_size=None, seed=42):
    """
    Two-sample DM test: ACA-TFT (model) vs GJR-GARCH-X (baseline).

    Analytical HAC-DM + block-bootstrap variant.
    Both use the Winkler interval score at the 85% level.
    """
    a     = ml_s["actuals"].astype(np.float64)
    l_ml  = ml_s["lowers_out"].astype(np.float64)
    u_ml  = ml_s["uppers_out"].astype(np.float64)
    l_g   = g_s["lowers_out"].astype(np.float64)
    u_g   = g_s["uppers_out"].astype(np.float64)
    n     = len(a)

    w_ml  = _winkler_obs(a, l_ml, u_ml, alpha)
    w_g   = _winkler_obs(a, l_g,  u_g,  alpha)

    d     = w_ml - w_g
    d_bar = float(np.mean(d))

    # HAC variance (Bartlett kernel, lag = max(horizon-1, 0))
    lag   = max(horizon - 1, 0)
    gamma = float(np.var(d, ddof=1))
    for k in range(1, lag + 1):
        gk     = float(np.mean((d[k:] - d_bar) * (d[:-k] - d_bar)))
        gamma += 2.0 * (1.0 - k / (lag + 1.0)) * gk
    se      = np.sqrt(max(gamma, 1e-15) / n)
    dm_stat = d_bar / se
    p_hac   = float(scipy_stats.t.sf(abs(dm_stat), df=n - 1) * 2)

    # Block-bootstrap DM
    rng = np.random.default_rng(seed)
    if block_size is None:
        block_size = max(int(round(n ** (1.0 / 3.0))), max(horizon, 2))

    def _block_draw(arr):
        n_blocks = int(np.ceil(n / block_size))
        starts   = rng.integers(0, n, size=n_blocks)
        idx      = np.concatenate([np.arange(s, s + block_size) % n
                                   for s in starts])[:n]
        return arr[idx]

    boot_means  = np.array([float(np.mean(_block_draw(d))) for _ in range(n_boot)])
    centered    = boot_means - float(np.mean(boot_means))
    p_boot_two  = float(np.mean(np.abs(centered) >= abs(d_bar)))
    p_boot_one  = float(np.mean(centered <= d_bar)) if d_bar < 0 else 1.0
    boot_ci_lo  = float(np.percentile(boot_means, 2.5))
    boot_ci_hi  = float(np.percentile(boot_means, 97.5))

    # MCS (2-model, α=10%)
    var_boot  = float(np.var(boot_means - np.mean(boot_means), ddof=0))
    se_boot   = np.sqrt(max(var_boot, 1e-15))
    t_R       = d_bar / se_boot
    boot_t    = (boot_means - float(np.mean(boot_means))) / se_boot
    p_mcs     = float(np.mean(np.abs(boot_t) >= abs(t_R)))
    if p_mcs <= 0.10:
        ml_in_mcs   = bool(d_bar <= 0)
        garch_in_mcs = bool(d_bar > 0)
        mcs_conclusion = ("ML eliminated" if d_bar > 0
                          else "GARCH eliminated — ML lower loss")
    else:
        ml_in_mcs = garch_in_mcs = True
        mcs_conclusion = "Both in MCS — no significant loss difference at 10%"

    ml_beats_garch = bool(d_bar < 0)

    print(f"\n{'─'*68}")
    print(f"  DM TEST: ACA-TFT  vs.  GJR-GARCH-X  [{label}]")
    print(f"{'─'*68}")
    arrow = "<" if dm_stat < 0 else ">"
    sig_hac  = "SIGNIFICANT ✓" if p_hac  < 0.05 else "not significant"
    sig_boot = "SIGNIFICANT ✓" if p_boot_two < 0.05 else "not significant"
    print(f"  n = {n}  |  Horizon: {horizon}D  |  "
          f"Block size (boot): {block_size}  |  B = {n_boot}")
    print(f"\n  Mean Winkler — ML    : {float(np.mean(w_ml)):.6f}")
    print(f"  Mean Winkler — GARCH : {float(np.mean(w_g)):.6f}")
    print(f"  Mean diff (d̄)        : {d_bar:+.6f}  "
          f"({'ML better' if ml_beats_garch else 'GARCH better'})")
    print(f"\n  [Analytical HAC-DM]  stat = {dm_stat:+.4f}  "
          f"p = {p_hac:.5f}  [{sig_hac}]")
    print(f"  [Block-Bootstrap DM] p(2-sided) = {p_boot_two:.4f}  "
          f"p(1-sided) = {p_boot_one:.4f}  [{sig_boot}]")
    print(f"  [95% Boot CI of d̄]  [{boot_ci_lo:+.6f},  {boot_ci_hi:+.6f}]")
    print(f"  [MCS α=10%]          t_R = {t_R:+.4f}  p_MCS = {p_mcs:.4f}")
    print(f"               ML in MCS : {'YES ✓' if ml_in_mcs else ' NO ✗'}"
          f"  |  GARCH in MCS : {'YES' if garch_in_mcs else ' NO'}")
    print(f"               {mcs_conclusion}")
    print(f"\n  Days ML Winkler < GARCH Winkler : "
          f"{float(np.mean(w_ml < w_g) * 100):.1f}%")

    if ml_beats_garch and p_hac < 0.05:
        verdict = "ZONE A — ML BEATS GARCH (HAC DM significant)"
    elif ml_beats_garch and p_boot_two < 0.05:
        verdict = "ZONE A — ML BEATS GARCH (Boot DM significant, HAC borderline)"
    elif ml_beats_garch:
        verdict = "ZONE A- — ML directionally better but not yet significant"
    elif not ml_beats_garch and (p_hac < 0.05 or p_boot_two < 0.05):
        verdict = "ZONE C — GARCH significantly beats ML — investigate"
    else:
        verdict = "ZONE B — No significant difference between models"

    print(f"\n  ══  VERDICT: {verdict}  ══")

    return dict(
        label=label, n=n, dm_stat=dm_stat, p_hac=p_hac,
        p_boot_two=p_boot_two, p_boot_one=p_boot_one,
        boot_ci_lo=boot_ci_lo, boot_ci_hi=boot_ci_hi,
        t_R=t_R, p_mcs=p_mcs,
        ml_in_mcs=ml_in_mcs, garch_in_mcs=garch_in_mcs,
        mcs_conclusion=mcs_conclusion,
        mean_wink_ml=float(np.mean(w_ml)),
        mean_wink_garch=float(np.mean(w_g)),
        d_bar=d_bar, ml_beats_garch=ml_beats_garch,
        pct_days_ml_wins=float(np.mean(w_ml < w_g) * 100),
        verdict=verdict,
        block_size=block_size,
    )


print("\n[B] Running DM tests (ML vs GARCH)...")

# Continuous walk-forward
dm_wf_cont = dm_vs_garch(ml_aln, g_aln,
                          label="WF Continuous [PRIMARY]",
                          horizon=1)

# Per-fold
dm_fold_results = []
for i, (ml_s, g_s) in enumerate(zip(wf_series_1d, fold_results), start=1):
    ml_dates    = pd.to_datetime(ml_s["dates"])
    garch_dates = pd.to_datetime(g_s["dates"])
    shared      = ml_dates.intersection(garch_dates)
    if len(shared) < 20:
        print(f"\n  Fold {i}: too few shared dates ({len(shared)}) — skipped.")
        continue
    ml_idx    = [np.where(ml_dates    == d)[0][0] for d in shared]
    garch_idx = [np.where(garch_dates == d)[0][0] for d in shared]

    _ml_fold = {k: np.array(v)[ml_idx] for k, v in ml_s.items()
                if hasattr(v, '__len__') and len(v) > 0
                and k not in ("dates", "base_prices")}
    _g_fold  = {k: np.array(v)[garch_idx] for k, v in g_s.items()
                if hasattr(v, '__len__') and len(v) > 0
                and k not in ("dates",)}

    # Ensure lowers_out / uppers_out keys exist
    for _s in (_ml_fold, _g_fold):
        if "lowers_out" not in _s and "lowers" in _s:
            _s["lowers_out"] = _s["lowers"]
        if "uppers_out" not in _s and "uppers" in _s:
            _s["uppers_out"] = _s["uppers"]

    r = dm_vs_garch(_ml_fold, _g_fold,
                    label=f"WF Fold {i}",
                    horizon=1)
    dm_fold_results.append(r)


# ══════════════════════════════════════════════════════════════════════════════
# PART C — EXTENDED HEAD-TO-HEAD BATTERY
# Comparative metrics on the aligned continuous series
# ══════════════════════════════════════════════════════════════════════════════

print(f"\n{'='*72}")
print("PART C — EXTENDED HEAD-TO-HEAD METRICS (aligned, n={})".format(n_aligned))
print("=" * 72)

a         = ml_aln["actuals"].astype(np.float64)
v         = ml_aln["vols_ann"].astype(np.float64)
i_dir     = ml_aln["intraday_dirs"].astype(np.float64)

l_ml      = ml_aln["lowers_out"].astype(np.float64)
u_ml      = ml_aln["uppers_out"].astype(np.float64)
li_ml     = ml_aln["lowers_in"].astype(np.float64)
ui_ml     = ml_aln["uppers_in"].astype(np.float64)
m_ml      = ml_aln["means"].astype(np.float64)

l_g       = g_aln["lowers_out"].astype(np.float64)
u_g       = g_aln["uppers_out"].astype(np.float64)
li_g      = g_aln["lowers_in"].astype(np.float64)
ui_g      = g_aln["uppers_in"].astype(np.float64)
m_g       = g_aln["means"].astype(np.float64)

w_ml_arr  = _winkler_obs(a, l_ml, u_ml)
w_g_arr   = _winkler_obs(a, l_g,  u_g)

# ── C1: Coverage ──────────────────────────────────────────────────────────────
hr_ml_85  = float(np.mean((l_ml <= a) & (a <= u_ml)) * 100)
hr_g_85   = float(np.mean((l_g  <= a) & (a <= u_g))  * 100)
hr_ml_20  = float(np.mean((li_ml <= a) & (a <= ui_ml)) * 100)
hr_g_20   = float(np.mean((li_g  <= a) & (a <= ui_g))  * 100)
rng_ml_85 = float(np.mean(u_ml - l_ml) * 100)
rng_g_85  = float(np.mean(u_g  - l_g)  * 100)
rng_ml_20 = float(np.mean(ui_ml - li_ml) * 100)
rng_g_20  = float(np.mean(ui_g  - li_g)  * 100)
io_ml     = float(np.mean(ui_ml - li_ml) / (np.mean(u_ml - l_ml) + 1e-9))
io_g      = float(np.mean(ui_g  - li_g)  / (np.mean(u_g  - l_g)  + 1e-9))

print(f"\n  ── Coverage & Interval Width ──────────────────────────────────────")
print(f"  {'Metric':<35} {'ACA-TFT':>10}  {'GARCH':>10}  {'Winner':>10}")
print(f"  {'─'*68}")
_rows = [
    ("85% Hit Rate (%)",          hr_ml_85,  hr_g_85,  "closer to 85%"),
    ("85% Avg Width (%)",         rng_ml_85, rng_g_85, "narrower"),
    ("20% Core Hit Rate (%)",     hr_ml_20,  hr_g_20,  "closer to 20%"),
    ("20% Core Avg Width (%)",    rng_ml_20, rng_g_20, "narrower"),
    ("Inner/Outer Ratio",         io_ml,     io_g,     "N/A"),
    ("Mean Winkler Score",        float(np.mean(w_ml_arr)), float(np.mean(w_g_arr)), "lower"),
]
for name, v_ml, v_g, rule in _rows:
    if rule == "lower":
        winner = "ML ✓" if v_ml < v_g else "GARCH ✓" if v_g < v_ml else "TIE"
    elif rule == "narrower":
        winner = "ML ✓" if v_ml < v_g else "GARCH ✓" if v_g < v_ml else "TIE"
    elif rule == "closer to 85%":
        winner = "ML ✓" if abs(v_ml - 85) < abs(v_g - 85) else "GARCH ✓"
    elif rule == "closer to 20%":
        winner = "ML ✓" if abs(v_ml - 20) < abs(v_g - 20) else "GARCH ✓"
    else:
        winner = "—"
    print(f"  {name:<35} {v_ml:>10.3f}  {v_g:>10.3f}  {winner:>10}")

# ── C2: Directional Accuracy ──────────────────────────────────────────────────
dir_ml = float(np.mean(np.sign(m_ml) == np.sign(a)) * 100)
dir_g  = float(np.mean(np.sign(m_g)  == np.sign(a)) * 100)
n_hit_ml  = int((np.sign(m_ml) == np.sign(a)).sum())
n_hit_g   = int((np.sign(m_g)  == np.sign(a)).sum())
p_dir_ml  = float(scipy_stats.binomtest(n_hit_ml, n_aligned, 0.5, alternative='greater').pvalue)
p_dir_g   = float(scipy_stats.binomtest(n_hit_g,  n_aligned, 0.5, alternative='greater').pvalue)

valid_m    = i_dir != 0
n_valid    = int(valid_m.sum())
if n_valid > 0:
    hits_intra_ml = int((np.sign(m_ml[valid_m]) == i_dir[valid_m]).sum())
    hits_intra_g  = int((np.sign(m_g[valid_m])  == i_dir[valid_m]).sum())
    dir_intra_ml  = hits_intra_ml / n_valid * 100
    dir_intra_g   = hits_intra_g  / n_valid * 100
    p_intra_ml    = float(scipy_stats.binomtest(hits_intra_ml, n_valid, 0.5, alternative='two-sided').pvalue)
    p_intra_g     = float(scipy_stats.binomtest(hits_intra_g,  n_valid, 0.5, alternative='two-sided').pvalue)
else:
    dir_intra_ml = dir_intra_g = p_intra_ml = p_intra_g = float('nan')

# McNemar test: are the two models' direction calls significantly different?
sign_ml  = np.sign(m_ml) == np.sign(a)
sign_g   = np.sign(m_g)  == np.sign(a)
b_count  = int(( sign_ml & ~sign_g).sum())   # ML correct, GARCH wrong
c_count  = int((~sign_ml &  sign_g).sum())   # GARCH correct, ML wrong
if (b_count + c_count) > 0:
    mcnemar_stat = (abs(b_count - c_count) - 1)**2 / max(b_count + c_count, 1)
    mcnemar_p    = float(scipy_stats.chi2.sf(mcnemar_stat, df=1))
else:
    mcnemar_stat = 0.0; mcnemar_p = 1.0

print(f"\n  ── Directional Accuracy ────────────────────────────────────────────")
print(f"  {'Metric':<35} {'ACA-TFT':>10}  {'GARCH':>10}  {'Winner':>10}")
print(f"  {'─'*68}")
print(f"  {'Dir C2C (%)':<35} {dir_ml:>10.2f}  {dir_g:>10.2f}  "
      f"{'ML ✓' if dir_ml > dir_g else 'GARCH ✓':>10}")
print(f"  {'Dir C2C p-value (>50%)':<35} {p_dir_ml:>10.5f}  {p_dir_g:>10.5f}  "
      f"{'—':>10}")
print(f"  {'Dir Intraday (%)':<35} {dir_intra_ml:>10.2f}  {dir_intra_g:>10.2f}  "
      f"{'ML ✓' if dir_intra_ml > dir_intra_g else 'GARCH ✓':>10}")
print(f"  {'Dir Intraday p-value (2-sided)':<35} {p_intra_ml:>10.5f}  {p_intra_g:>10.5f}  {'—':>10}")
print(f"\n  McNemar test (direction calls differ?):")
print(f"    ML correct / GARCH wrong = {b_count}  |  "
      f"GARCH correct / ML wrong = {c_count}")
print(f"    χ² = {mcnemar_stat:.4f}  p = {mcnemar_p:.5f}  "
      f"({'significantly different call sets' if mcnemar_p < 0.05 else 'call sets not significantly different'})")

# ── C3: CRPS comparison ───────────────────────────────────────────────────────
def _g_crps(y, mu_f, sig_f):
    z   = (y - mu_f) / np.maximum(sig_f, 1e-10)
    Phi = scipy_stats.norm.cdf(z)
    phi = scipy_stats.norm.pdf(z)
    return sig_f * (z * (2.0 * Phi - 1.0) + 2.0 * phi - 1.0 / np.sqrt(np.pi))

# Derive per-day sigma from band width (consistent with Cell 7)
Z_OUTER_DOUBLE = 2.0 * _Z_OUTER    # width = 2*Z*sigma under Gaussian
sig_ml   = np.maximum((u_ml - l_ml) / Z_OUTER_DOUBLE, 1e-10)
sig_g    = np.maximum((u_g  - l_g)  / Z_OUTER_DOUBLE, 1e-10)

crps_ml  = _g_crps(a, m_ml, sig_ml)
crps_g   = _g_crps(a, m_g,  sig_g)
mean_crps_ml = float(np.mean(crps_ml))
mean_crps_g  = float(np.mean(crps_g))

# Paired t-test on CRPS difference
crps_diff  = crps_ml - crps_g
crps_d_bar = float(np.mean(crps_diff))
crps_se    = float(np.std(crps_diff, ddof=1)) / np.sqrt(n_aligned)
crps_t     = crps_d_bar / max(crps_se, 1e-15)
crps_p     = float(scipy_stats.t.sf(abs(crps_t), df=n_aligned - 1) * 2)
crps_skill = 1.0 - mean_crps_ml / max(mean_crps_g, 1e-15)  # ML skill vs GARCH

print(f"\n  ── CRPS (ML vs GARCH baseline) ─────────────────────────────────────")
print(f"  Mean CRPS — ML    : {mean_crps_ml:.6f}")
print(f"  Mean CRPS — GARCH : {mean_crps_g:.6f}")
print(f"  ML Skill vs GARCH : {crps_skill:+.4f}  "
      f"({'ML better' if crps_skill > 0 else 'GARCH better'})")
print(f"  Paired t-test     : t = {crps_t:+.4f}  p = {crps_p:.5f}  "
      f"({'SIGNIFICANT' if crps_p < 0.05 else 'not significant'})")

# ── C4: OOS-R² (ML forecast vs GARCH forecast as benchmark) ──────────────────
# Here the "benchmark" is the GARCH mean, not zero-mean.
# OOS-R² = 1 - MSE(ML) / MSE(GARCH)   w.r.t. actuals
mse_ml    = float(np.mean((a - m_ml)**2))
mse_g     = float(np.mean((a - m_g)**2))
oos_r2_vs_garch = 1.0 - mse_ml / max(mse_g, 1e-15)

# Clark-West adjusted for GARCH benchmark
cw_series_g = (a - m_g)**2 - ((a - m_ml)**2 - (m_ml - m_g)**2)
cw_mean_g   = float(np.mean(cw_series_g))
cw_se_g     = float(np.std(cw_series_g, ddof=1)) / np.sqrt(n_aligned)
cw_stat_g   = cw_mean_g / max(cw_se_g, 1e-15)
cw_p_g      = float(scipy_stats.t.sf(cw_stat_g, df=n_aligned - 1))   # one-sided

print(f"\n  ── OOS R² (ML vs GARCH mean) ───────────────────────────────────────")
print(f"  MSE ML    : {mse_ml:.8f}")
print(f"  MSE GARCH : {mse_g:.8f}")
print(f"  OOS R²    : {oos_r2_vs_garch:+.4f}  "
      f"({'ML lower MSE ✓' if oos_r2_vs_garch > 0 else 'GARCH lower MSE ✗'})")
print(f"  Clark-West stat : {cw_stat_g:+.4f}  p = {cw_p_g:.5f}  "
      f"({'SIGNIFICANT' if cw_p_g < 0.05 else 'not significant'}) [one-sided, H₁: ML > GARCH]")

# ── C5: Rank IC comparison ────────────────────────────────────────────────────
ic_ml, p_ic_ml = scipy_stats.spearmanr(u_ml - l_ml, np.abs(a))
ic_g,  p_ic_g  = scipy_stats.spearmanr(u_g  - l_g,  np.abs(a))

print(f"\n  ── Rank IC (width vs |return|) ─────────────────────────────────────")
print(f"  ML Rank IC    : {float(ic_ml):+.4f}  p = {float(p_ic_ml):.5f}  "
      f"({'significant' if float(p_ic_ml) < 0.05 else 'not significant'})")
print(f"  GARCH Rank IC : {float(ic_g):+.4f}  p = {float(p_ic_g):.5f}  "
      f"({'significant' if float(p_ic_g) < 0.05 else 'not significant'})")
print(f"  IC advantage  : {'ML ✓' if float(ic_ml) > float(ic_g) else 'GARCH ✓'}  "
      f"(Δ = {float(ic_ml) - float(ic_g):+.4f})")

# ── C6: Regime stratification — side-by-side ─────────────────────────────────
print(f"\n  ── Regime-Conditional Winkler Ratio (vs naive) ─────────────────────")
print(f"  Winkler ratio < 1.0 means the model beats naive rolling-vol.")
print(f"  {'─'*68}")

_vol_edges = np.percentile(v, [0, 33.33, 66.67, 100])
_vol_labs  = ["Low Vol", "Mid Vol", "High Vol"]
_naive_lo  = -_Z_OUTER * v / np.sqrt(252)
_naive_hi  =  _Z_OUTER * v / np.sqrt(252)
w_naive    = _winkler_obs(a, _naive_lo, _naive_hi)

print(f"\n  (A) Volatility Regimes")
print(f"  {'Regime':<14} {'n':>5}  {'Wink_ML':>9}  {'Wink_G':>9}  "
      f"{'Wink_N':>9}  {'ML/N':>6}  {'G/N':>6}  {'Better':>8}")
print(f"  {'─'*72}")
for i, label in enumerate(_vol_labs):
    mask = (v >= _vol_edges[i]) & (v < _vol_edges[i+1]) if i < 2 else (v >= _vol_edges[i])
    if mask.sum() < 5: continue
    wm = float(np.mean(w_ml_arr[mask]))
    wg = float(np.mean(w_g_arr[mask]))
    wn = float(np.mean(w_naive[mask]))
    print(f"  {label:<14} {int(mask.sum()):>5}  {wm:>9.6f}  {wg:>9.6f}  "
          f"{wn:>9.6f}  {wm/wn:>6.3f}  {wg/wn:>6.3f}  "
          f"{'ML ✓' if wm < wg else 'GARCH ✓':>8}")

_tail_thresh = float(np.percentile(np.abs(a), 90))
print(f"\n  (B) Tail vs Normal Days  (P90 threshold = {_tail_thresh*100:.3f}%)")
print(f"  {'Regime':<22} {'n':>5}  {'Wink_ML':>9}  {'Wink_G':>9}  "
      f"{'Wink_N':>9}  {'ML/N':>6}  {'G/N':>6}  {'Better':>8}")
print(f"  {'─'*78}")
for mask, rname in [(np.abs(a) > _tail_thresh,  "Tail (|r| > P90)"),
                    (np.abs(a) <= _tail_thresh, "Normal (|r| ≤ P90)")]:
    if mask.sum() < 5: continue
    wm = float(np.mean(w_ml_arr[mask]))
    wg = float(np.mean(w_g_arr[mask]))
    wn = float(np.mean(w_naive[mask]))
    print(f"  {rname:<22} {int(mask.sum()):>5}  {wm:>9.6f}  {wg:>9.6f}  "
          f"{wn:>9.6f}  {wm/wn:>6.3f}  {wg/wn:>6.3f}  "
          f"{'ML ✓' if wm < wg else 'GARCH ✓':>8}")

# ── C7: Economic Value head-to-head ──────────────────────────────────────────
gamma_ev = 3.0;  tc_ev = 10 / 10_000.0
sig_ml_ev   = np.maximum((u_ml - l_ml) / Z_OUTER_DOUBLE, 1e-10)
sig_g_ev    = np.maximum((u_g  - l_g)  / Z_OUTER_DOUBLE, 1e-10)
w_pos_ml    = np.clip(m_ml / np.maximum(gamma_ev * sig_ml_ev**2, 1e-10), -1.0, 1.0)
w_pos_g     = np.clip(m_g  / np.maximum(gamma_ev * sig_g_ev**2,  1e-10), -1.0, 1.0)
tc_ml_arr   = tc_ev * np.abs(np.diff(np.concatenate([[0.0], w_pos_ml])))
tc_g_arr    = tc_ev * np.abs(np.diff(np.concatenate([[0.0], w_pos_g])))
ret_ml_ev   = w_pos_ml * a - tc_ml_arr
ret_g_ev    = w_pos_g  * a - tc_g_arr
ret_bh      = a.copy()

def _ceq_ann(r, gam=3.0):
    return (float(np.mean(r)) - 0.5 * gam * float(np.var(r, ddof=1))) * 252

def _sharpe_ann(r):
    s = float(np.std(r, ddof=1))
    return float(np.mean(r)) / s * np.sqrt(252) if s > 1e-10 else 0.0

ceq_ml   = _ceq_ann(ret_ml_ev)
ceq_g    = _ceq_ann(ret_g_ev)
ceq_bh   = _ceq_ann(ret_bh)
ev_ml_vs_g  = (ceq_ml - ceq_g) * 100
ev_ml_vs_bh = (ceq_ml - ceq_bh) * 100
ev_g_vs_bh  = (ceq_g  - ceq_bh) * 100

print(f"\n  ── Economic Value  [γ={gamma_ev}, tc={int(tc_ev*10000)} bps] ───────────────────────────────")
print(f"  {'Metric':<35} {'ACA-TFT':>10}  {'GARCH':>10}  {'B&H':>10}")
print(f"  {'─'*68}")
print(f"  {'Sharpe (ann)':<35} {_sharpe_ann(ret_ml_ev):>+10.3f}  "
      f"{_sharpe_ann(ret_g_ev):>+10.3f}  {_sharpe_ann(ret_bh):>+10.3f}")
print(f"  {'CEQ ann (%)':<35} {ceq_ml*100:>+10.3f}  "
      f"{ceq_g*100:>+10.3f}  {ceq_bh*100:>+10.3f}")
print(f"  {'EV vs B&H (% p.a.)':<35} {ev_ml_vs_bh:>+10.3f}  {ev_g_vs_bh:>+10.3f}  {'—':>10}")
print(f"  {'EV ML vs GARCH (% p.a.)':<35} {ev_ml_vs_g:>+10.3f}  {'—':>10}  {'—':>10}  "
      f"{'ML ✓' if ev_ml_vs_g > 0 else 'GARCH ✓'}")


# ══════════════════════════════════════════════════════════════════════════════
# PART D — CONSOLIDATED SCORECARD
# ══════════════════════════════════════════════════════════════════════════════

print(f"\n{'='*72}")
print("PART D — CONSOLIDATED HEAD-TO-HEAD SCORECARD")
print("=" * 72)

_SEP = "─" * 72

def _score_row(metric, ml_val, g_val, unit="", winner_rule="higher", note=""):
    if winner_rule == "higher":
        winner = "ML ✓" if float(ml_val) > float(g_val) else "GARCH ✓"
    elif winner_rule == "lower":
        winner = "ML ✓" if float(ml_val) < float(g_val) else "GARCH ✓"
    elif winner_rule == "closer85":
        winner = "ML ✓" if abs(float(ml_val)-85) < abs(float(g_val)-85) else "GARCH ✓"
    else:
        winner = "—"
    ml_str = f"{float(ml_val):.4f}{unit}" if "%" not in unit else f"{float(ml_val):.2f}{unit}"
    g_str  = f"{float(g_val):.4f}{unit}"  if "%" not in unit else f"{float(g_val):.2f}{unit}"
    note_str = f"  ({note})" if note else ""
    print(f"  {metric:<38} {ml_str:>10}  {g_str:>10}  {winner:>8}{note_str}")

print(f"\n  {'Metric':<38} {'ACA-TFT':>10}  {'GARCH':>10}  {'Winner':>8}")
print(f"  {_SEP}")
print(f"  INTERVAL QUALITY")
_score_row("  85% Hit Rate",           hr_ml_85,  hr_g_85,  "%", "closer85")
_score_row("  85% Avg Width",          rng_ml_85, rng_g_85, "%", "lower",  "narrower = more informative")
_score_row("  Mean Winkler Score",     float(np.mean(w_ml_arr)), float(np.mean(w_g_arr)), "", "lower")
_score_row("  Rank IC (width vs |r|)", float(ic_ml), float(ic_g), "", "higher", "uncertainty skill")

print(f"  {_SEP}")
print(f"  DIRECTIONAL SKILL")
_score_row("  Dir Accuracy C2C",       dir_ml,       dir_g,       "%", "higher")
_score_row("  Dir Accuracy Intraday",  dir_intra_ml, dir_intra_g, "%", "higher")

print(f"  {_SEP}")
print(f"  PROBABILISTIC CALIBRATION")
_score_row("  CRPS (ML vs GARCH)",     mean_crps_ml, mean_crps_g, "", "lower")
_score_row("  OOS R² vs GARCH mean",   oos_r2_vs_garch, 0.0, "", "higher")

print(f"  {_SEP}")
print(f"  ECONOMIC VALUE")
_score_row("  Sharpe (ann)",            _sharpe_ann(ret_ml_ev), _sharpe_ann(ret_g_ev), "", "higher")
_score_row("  CEQ ann (%)",             ceq_ml*100,  ceq_g*100,  "%", "higher")
_score_row("  EV vs B&H (% p.a.)",     ev_ml_vs_bh, ev_g_vs_bh, "%", "higher")

print(f"  {_SEP}")
print(f"  DM TEST (ML vs GARCH)")
print(f"  {'  HAC DM stat':<38} {dm_wf_cont['dm_stat']:>+10.4f}  {'—':>10}  "
      f"{'ML ✓' if dm_wf_cont['ml_beats_garch'] else 'GARCH ✓':>8}")
print(f"  {'  HAC DM p-value':<38} {dm_wf_cont['p_hac']:>10.5f}  {'—':>10}  {'—':>8}")
print(f"  {'  Boot DM p-value (2-sided)':<38} {dm_wf_cont['p_boot_two']:>10.4f}  {'—':>10}  {'—':>8}")
print(f"  {'  % days ML Winkler < GARCH':<38} {dm_wf_cont['pct_days_ml_wins']:>10.1f}  {'—':>10}  {'—':>8}")

print(f"\n  {_SEP}")
print(f"  FINAL VERDICT: {dm_wf_cont['verdict']}")
if dm_wf_cont['ml_beats_garch']:
    print(f"  ML CEQ advantage over GARCH: {ev_ml_vs_g:+.2f}% p.a.")
print(f"  {_SEP}")

# ── Per-fold summary ──────────────────────────────────────────────────────────
if dm_fold_results:
    print(f"\n  Per-Fold DM Summary (ML vs GARCH):")
    print(f"  {'Fold':<20} {'DM stat':>9}  {'HAC p':>8}  {'Boot p':>8}  {'ML wins?':>9}")
    print(f"  {'─'*58}")
    for r in dm_fold_results:
        wins = "YES ✓" if r["ml_beats_garch"] else "  NO"
        sig  = "*" if r["p_hac"] < 0.05 else ""
        print(f"  {r['label']:<20} {r['dm_stat']:>+9.4f}  {r['p_hac']:>8.5f}{sig:1}  "
              f"{r['p_boot_two']:>8.4f}  {wins:>9}")
    print(f"  (* = HAC DM p < 0.05)")

# ── Save ──────────────────────────────────────────────────────────────────────
_ts      = datetime.now().strftime("%Y%m%d_%H%M%S")
_out_dir = Path("/content/drive/MyDrive/Model Results")
_out_dir.mkdir(parents=True, exist_ok=True)
_out_path = _out_dir / f"ml_vs_garch_headtohead_{_ts}.txt"

_summary = {
    "timestamp"             : _ts,
    "n_aligned"             : n_aligned,
    "dm_stat_hac"           : round(dm_wf_cont["dm_stat"], 4),
    "dm_p_hac"              : round(dm_wf_cont["p_hac"], 5),
    "dm_p_boot"             : round(dm_wf_cont["p_boot_two"], 4),
    "ml_beats_garch"        : dm_wf_cont["ml_beats_garch"],
    "mcs_conclusion"        : dm_wf_cont["mcs_conclusion"],
    "hr_85_ml"              : round(hr_ml_85, 2),
    "hr_85_garch"           : round(hr_g_85, 2),
    "rng_85_ml"             : round(rng_ml_85, 3),
    "rng_85_garch"          : round(rng_g_85, 3),
    "winkler_ml"            : round(float(np.mean(w_ml_arr)), 6),
    "winkler_garch"         : round(float(np.mean(w_g_arr)), 6),
    "rank_ic_ml"            : round(float(ic_ml), 4),
    "rank_ic_garch"         : round(float(ic_g), 4),
    "dir_c2c_ml"            : round(dir_ml, 2),
    "dir_c2c_garch"         : round(dir_g, 2),
    "crps_ml"               : round(mean_crps_ml, 6),
    "crps_garch"            : round(mean_crps_g, 6),
    "crps_skill_vs_garch"   : round(crps_skill, 4),
    "oos_r2_vs_garch"       : round(oos_r2_vs_garch, 4),
    "ev_ml_vs_garch_pct_pa" : round(ev_ml_vs_g, 3),
    "sharpe_ml"             : round(_sharpe_ann(ret_ml_ev), 3),
    "sharpe_garch"          : round(_sharpe_ann(ret_g_ev), 3),
    "verdict"               : dm_wf_cont["verdict"],
}

import json
with open(_out_path, "w", encoding="utf-8") as f:
    f.write(f"ML vs GARCH Head-to-Head — {_ts}\n\n")
    f.write(json.dumps(_summary, indent=2))
    f.write("\n")

print(f"\nResults saved: {_out_path}")
print(f"\n{'='*72}")
print("ML vs GARCH comparison complete.")
print("=" * 72)

"""## Better Data Sources for Intraday Range Prediction -
If you want to dramatically improve a model predicting intraday ranges, you need features that measure market mechanics and structural positioning, not just price action.

Here are the highest-alpha features you can add using data you mostly already have:

Days to Expiry (DTE): NIFTY intraday volatility behaves completely differently on a Friday (high premium, slow decay) versus a Thursday expiry (gamma spikes, wild pin risk). You must add a feature that counts the trading days remaining until the nearest weekly expiry. The model will naturally learn to tighten bounds early in the week and widen them or expect mean-reversion on 0-DTE.

Market Breadth (Advance/Decline Ratio): NIFTY is market-cap weighted. Sometimes the index is flat, but 40 stocks are down and Reliance is artificially holding the index up. A simple feature taking the ratio of advancing to declining stocks in the NIFTY 50 from the previous day tells the model the "health" of the trend.

USDINR Overnight NDF Movement: The Non-Deliverable Forward market for the Rupee trades overnight. Sudden spikes in USDINR overnight correlate heavily with foreign capital flight and expanded intraday volatility in Indian equities.

Dealer Gamma Exposure (GEX): This is the holy grail for range traders. By calculating the total market maker gamma from the NSE option chain, you can determine if dealers are in "Long Gamma" (meaning they will buy dips and sell rips, keeping the market tightly pinned) or "Short Gamma" (meaning their hedging will exacerbate market moves, leading to wide trend days).

# 9. Improved Model — Structural Feature Enhancements

### Changes Implemented vs Section 7b

#### Cell 1 — Data Preparation
**1. DTE Cyclical Encoding**
- Replaces hard binary thresholds with smooth sine/cosine encoding of the 7-day expiry calendar:
  `DTE_Cyclic_Sin = sin(2π·DTE/7)`, `DTE_Cyclic_Cos = cos(2π·DTE/7)`
- Preserves ordinality and cyclical wrapping so the model sees DTE=6 and DTE=0 as adjacent.
- `WoW_Ret`: log-return from the last expiry close to today's close, capturing intra-week drift.
  No look-ahead — last expiry close is always known at prediction time.

**2. Hurst Exponent + Intraday Kurtosis**
- `Hurst_40D`: rolling 40-day R/S Hurst exponent from daily log-returns.
  H > 0.5 = trending (wider bands warranted), H < 0.5 = mean-reverting (tighter bands warranted).
  Computed via explicit R/S loop; filled with 0.5 (random walk) before sufficient history.
- `Returns_Kurtosis_20D`: rolling 20-day excess kurtosis (pandas .kurt(), normal=0).
  High kurtosis = recent tail events → vol gate should widen outer CI.

**3. Feature Relationship Features (domain-encoded interactions)**
- `VRP_Pos` / `VRP_Neg`: positive and negative VRP components separated.
  Response to positive vs negative VRP is empirically asymmetric.
- `GEX_Neg_x_DTE_R1`: negative GEX on pre-expiry day — structurally dangerous combination.
- `HL_Range_x_GEX_Abs`: yesterday's candle range × |GEX| magnitude — regime instability proxy.
- `VRP_x_Vol_Regime`: VRP sign interacted with vol z-score.
- `Put_Wall_Strength`: (PCR_OI − 1)⁺ × Options_Skew_25d⁺ — explicit put-wall encoding.
- `Overnight_Momentum_*_Tanh_Weight`: tanh-transformed 3D consistency for SP500/Crude/HangSeng.
  Saturates at strong trends; smoother gradient than linear integer counts.

**4. Target: `Target_HL_Range_1D`**
- log(High_{t+1} / Low_{t+1}): next-day intraday high-low range (training label only).
- Added as column 1 of y_raw alongside Target_Ret_1D (column 0).
- No look-ahead: it is a supervised target, identical in nature to Target_Ret_1D.

#### Cell 2 — Model Definition
- **Unchanged** from Section 7b.

#### Cell 3 — Training & Inference
**3. Adaptive Tail Heaviness (Learned DoF)**
- Per-batch adaptive inner/outer ratio target based on current vol regime.
- High-vol batch → lower df → fatter tails → looser IO ratio target.
- Uses `df_vol_sensitivity` (CONFIG): 0.0 = disabled (recovers exact 7b behaviour).
- Vol stats computed from each fold's training split; no look-ahead.

**4. Log-Range Auxiliary Task**
- Aux head now predicts vol-normalised next-day H-L range instead of |return|.
- Supervises the variance tower to associate wide outer bands with high actual realized range.
- Controlled by `aux_task_weight` (set to 0.15; was 0.0 in 7b).

**5. Intraday Range Metric**
- `_run_inference` captures actual HL range in `s["hl_ranges"]`.
- `_compute_metrics` reports Spearman IC between predicted outer-band width and actual HL range.
  Positive significant IC = model width is truly informative about intraday range.

#### Cells 4, 6, 7, 8 — Unchanged
All existing statistical tests, visualizations, and the master summary table are identical to Section 7b.
HL range IC appears only in the quick-metrics print inside Cells 3 and 5.
"""

# ================================================================================
# CELL 1 — DATA PREPARATION  [Section 9]
# Changes vs Section 7b:
#   + New CONFIG params: df_vol_sensitivity, df_min, df_max, hurst_window,
#     kurtosis_window, aux_task_weight (now 0.15)
#   + DTE cyclical encoding: DTE_Cyclic_Sin, DTE_Cyclic_Cos
#   + Intra-week return: WoW_Ret
#   + Structural regime features: Hurst_40D, Returns_Kurtosis_20D
#   + Feature-relationship features: VRP_Pos/Neg, GEX_Neg_x_DTE_R1,
#     HL_Range_x_GEX_Abs, VRP_x_Vol_Regime, Put_Wall_Strength,
#     Overnight_Momentum_*_Tanh_Weight
#   + Target_HL_Range_1D added as column 1 of y_raw (training label only)
#   All feature engineering uses only past/contemporaneous data. No leakage.
# ================================================================================

import pandas as pd
import polars as pl
import numpy as np
import torch
import random
import math
from scipy.stats import t
from torch.utils.data import Dataset, DataLoader
from sklearn.preprocessing import StandardScaler
from pathlib import Path

# ── Schedule / contract parameters ───────────────────────────────────────────
EXPIRY_SHIFT_DATE = pd.Timestamp("2025-09-01")

def nifty_lot_size(dt: pd.Timestamp) -> int:
    d = dt.date() if hasattr(dt, 'date') else dt
    if d < pd.Timestamp("2024-05-01").date():   return 50
    elif d < pd.Timestamp("2024-12-01").date(): return 25
    else:                                        return 75

# ── ALL CONFIGS ───────────────────────────────────────────────────────────────
CONFIG = {
    # ── Identical to Section 7b ───────────────────────────────────────────────
    "num_runs"                  : 1,
    "seq_len_1d"                : 10,
    "d_model"                   : 48,
    "nhead"                     : 4,
    "dropout"                   : 0.3,
    "num_grn_layers"            : 3,
    "epochs"                    : 45,
    "batch_size"                : 64,
    "lr"                        : 0.001,
    "use_lr_scheduler"          : True,
    "n_ensembles"               : 5,
    "dir_weight"                : 1.5,
    "outer_quantile_weight"     : 1.5,
    "inner_quantile_weight"     : 0.75,
    "df"                        : 4.5,
    "outer_ci_pct"              : 85,
    "inner_ci_pct"              : 20,
    "inner_outer_ratio_weight"  : 0.50,
    "dir_feature_subsample_ratio": 0.75,
    "attn_decay_rate"           : 0.20,
    "test_size"                 : 180,
    "purge_gap"                 : 15,
    "anchor_epoch_multiplier"   : 1.5,
    "width_cos_weight"          : 0.0,
    # ── CHANGED: aux task now active (was 0.0); predicts log-range not |ret| ─
    "aux_task_weight"           : 0.15,
    # ── NEW: Adaptive tail heaviness (Learned DoF) ────────────────────────────
    # Set df_vol_sensitivity=0.0 to recover exact 7b behaviour (fixed ratio).
    # With df_vol_sensitivity>0: high-vol batches use lower df (fatter tails).
    "df_vol_sensitivity"        : 0.15,   # 0.0 = disabled
    "df_min"                    : 3.0,    # floor df (heaviest tails)
    "df_max"                    : 12.0,   # ceiling df (thinnest tails)
    # ── NEW: Structural feature windows ──────────────────────────────────────
    "hurst_window"              : 40,     # R/S analysis window (trading days)
    "kurtosis_window"           : 20,     # rolling excess kurtosis window
}

_df_param = CONFIG["df"]
inner_q = (1 + CONFIG["inner_ci_pct"] / 100) / 2
outer_q = (1 + CONFIG["outer_ci_pct"] / 100) / 2
CONFIG["inner_outer_ratio_target"] = round(
    t.ppf(inner_q, _df_param) / t.ppf(outer_q, _df_param), 3)
print(f"IO Ratio Target (base df={_df_param}): {CONFIG['inner_outer_ratio_target']:.03f}")
print(f"Adaptive DoF: sensitivity={CONFIG['df_vol_sensitivity']} "
      f"[{'ACTIVE' if CONFIG['df_vol_sensitivity']>0 else 'DISABLED'}]")
print(f"Log-range aux task weight: {CONFIG['aux_task_weight']}")

# ── 1. Load Data ──────────────────────────────────────────────────────────────
processed_dir   = Path("/content/drive/MyDrive/Processed Trading Data")
master_out_file = processed_dir / "nifty_master_file.parquet"
df_pl = pl.read_parquet(master_out_file)
df_pd = df_pl.to_pandas()
df_pd['Date'] = pd.to_datetime(df_pd['Date'])

# ── 2. Vol-Regime Awareness Features (UNCHANGED) ─────────────────────────────
df_pd['Vol_Change_1D']     = df_pd['Realized_Vol_Ann'].pct_change(1).clip(-2, 2)
df_pd['Vol_Change_5D']     = df_pd['Realized_Vol_Ann'].pct_change(5).clip(-2, 2)
df_pd['Vol_of_Vol_10D']    = df_pd['Realized_Vol_Ann'].rolling(10).std()
df_pd['Recent_Max_AbsRet'] = df_pd['Target_Ret_1D'].shift(1).abs().rolling(5).max()

# ── 3. Momentum Consistency Features (UNCHANGED) ─────────────────────────────
for col in ['Overnight_Momentum_sp500', 'Overnight_Momentum_crudeoil',
            'Overnight_Momentum_hang_seng']:
    sign_col = np.sign(df_pd[col])
    df_pd[f'{col}_Consist_3D'] = sign_col.rolling(3).sum()
    df_pd[f'{col}_Consist_5D'] = sign_col.rolling(5).sum()

# ── 4. Vol-of-Vol Features (UNCHANGED) ───────────────────────────────────────
df_pd['VoV_5D'] = df_pd['Realized_Vol_Ann'].rolling(5).std()
df_pd['Vol_Regime_Zscore'] = (
    (df_pd['Realized_Vol_Ann'] - df_pd['Realized_Vol_Ann'].rolling(20).mean()) /
    (df_pd['Realized_Vol_Ann'].rolling(20).std() + 1e-6)
).clip(-3, 3)
df_pd['Recent_Vol_Drawdown'] = (
    df_pd['Realized_Vol_Ann'] /
    (df_pd['Realized_Vol_Ann'].rolling(10).max() + 1e-6)
).clip(0.05, 1.5)
df_pd['Vol_MA_Ratio'] = (
    df_pd['Realized_Vol_Ann'].rolling(5).mean() /
    (df_pd['Realized_Vol_Ann'].rolling(20).mean() + 1e-6)
).clip(0.1, 5.0)

# ── 5. New Feature Groups (UNCHANGED) ────────────────────────────────────────
_close   = df_pd['Spot_Close']
_open    = df_pd['Spot_Open']
_high    = df_pd['Spot_High']
_low     = df_pd['Spot_Low']
_vol     = df_pd['Realized_Vol_Ann']
_hist_lr = np.log(_close / _close.shift(1))

# Group A: Intraday Candle Structure
_hl_range = np.log(_high / _low).clip(0, 0.10)
df_pd['HL_Range_Zscore'] = (
    (_hl_range - _hl_range.rolling(20, min_periods=5).mean()) /
    (_hl_range.rolling(20, min_periods=5).std() + 1e-6)
).clip(-3, 3)
df_pd['Overnight_Gap_Abs'] = np.log(_open / _close.shift(1)).abs().clip(0, 0.05)
_upper_shadow = np.log(_high / np.maximum(_open, _close)).clip(0, 0.05)
_lower_shadow = np.log(np.minimum(_open, _close) / _low).clip(0, 0.05)
df_pd['Shadow_Imbalance'] = (_lower_shadow - _upper_shadow).clip(-0.05, 0.05)

# Group B: Vol-Regime Transition
_down_ret = _hist_lr.where(_hist_lr < 0, 0.0)
_up_ret   = _hist_lr.where(_hist_lr > 0, 0.0)
df_pd['SemiVar_Down_10D'] = (
    _down_ret.rolling(10, min_periods=5).std() * np.sqrt(252)
).clip(0, 1.5).fillna(0)
df_pd['SemiVar_Up_10D'] = (
    _up_ret.rolling(10, min_periods=5).std() * np.sqrt(252)
).clip(0, 1.5).fillna(0)
df_pd['SemiVar_Ratio_10D'] = (
    df_pd['SemiVar_Down_10D'] / (df_pd['SemiVar_Up_10D'] + 1e-6)
).clip(0.1, 5.0)
_below_mean = (_vol < _vol.rolling(20, min_periods=5).mean()).astype(int)
_streak, _s = [], 0
for v in _below_mean:
    _s = _s + 1 if v else 0
    _streak.append(_s)
df_pd['Vol_Compression_Streak'] = np.log1p(np.array(_streak, dtype=np.float32))
df_pd['Vol_Accel_3D'] = (_vol / (_vol.shift(3) + 1e-6)).clip(0.2, 5.0)

# Group C/D: NIFTY-Native Directional Signals
df_pd['NIFTY_Overnight_Gap'] = np.log(_open / _close.shift(1)).clip(-0.05, 0.05)
df_pd['NIFTY_Intraday_Ret']  = np.log(_close / _open).clip(-0.05, 0.05)
_intra_sign = np.sign(df_pd['NIFTY_Intraday_Ret'])
df_pd['NIFTY_Intraday_Consist_3D'] = _intra_sign.rolling(3).sum()
df_pd['NIFTY_Intraday_Consist_5D'] = _intra_sign.rolling(5).sum()
df_pd['PCR_OI_Change_1D'] = df_pd['PCR_OI'].pct_change(1).clip(-2, 2)
df_pd['PCR_OI_Zscore'] = (
    (df_pd['PCR_OI'] - df_pd['PCR_OI'].rolling(20, min_periods=5).mean()) /
    (df_pd['PCR_OI'].rolling(20, min_periods=5).std() + 1e-6)
).clip(-3, 3)

# ── DTE Regime Features (UNCHANGED) ──────────────────────────────────────────
def _next_expiry_date(ts: pd.Timestamp) -> pd.Timestamp:
    target_dow = 1 if ts >= EXPIRY_SHIFT_DATE else 3
    days_ahead = (target_dow - ts.weekday()) % 7
    return ts + pd.Timedelta(days=days_ahead)

_dte_raw = df_pd['Date'].apply(
    lambda d: (_next_expiry_date(d) - d).days
).astype(int)

df_pd['DTE_R0_Expiry']  = (_dte_raw == 0).astype(np.float32)
df_pd['DTE_R1_PreExp']  = (_dte_raw == 1).astype(np.float32)
df_pd['DTE_R2_MidWeek'] = (_dte_raw.isin([2, 3])).astype(np.float32)
df_pd['DTE_R3_PostExp'] = (_dte_raw.isin([4, 5, 6])).astype(np.float32)

df_pd['DTE_PostExp_x_SP500Mom'] = (
    df_pd['DTE_R3_PostExp'] * df_pd['Overnight_Momentum_sp500']
).astype(np.float32)

_regime_counts = {
    'R0_Expiry' : int(df_pd['DTE_R0_Expiry'].sum()),
    'R1_PreExp' : int(df_pd['DTE_R1_PreExp'].sum()),
    'R2_MidWeek': int(df_pd['DTE_R2_MidWeek'].sum()),
    'R3_PostExp': int(df_pd['DTE_R3_PostExp'].sum()),
}
_sum_check = sum(_regime_counts.values())
print(f"DTE regimes: {_regime_counts} | Sum={_sum_check} | Rows={len(df_pd)} "
      f"| {'OK' if _sum_check == len(df_pd) else 'MISMATCH'}")

# ── GEX Features (UNCHANGED) ─────────────────────────────────────────────────
_gex_required = ['GEX_Raw', 'GEX_Zscore', 'GEX_Pos', 'GEX_Neg']
_gex_missing  = [c for c in _gex_required if c not in df_pd.columns]

if _gex_missing:
    print(f"GEX columns {_gex_missing} missing — merging from skew parquet...")
    _skew_path = processed_dir / "nifty_options_skew.parquet"
    _skew_df   = (
        pl.read_parquet(_skew_path, columns=['Date'] + _gex_required).to_pandas()
    )
    _skew_df['Date'] = pd.to_datetime(_skew_df['Date'])
    df_pd = df_pd.merge(_skew_df, on='Date', how='left')
    for _c in _gex_required:
        df_pd[_c] = df_pd[_c].ffill().fillna(0.0)
    print(f"  Merged. Rows with GEX: {int(df_pd['GEX_Raw'].notna().sum())} / {len(df_pd)}")
else:
    print("GEX columns present in master file.")

for _col in _gex_required:
    assert _col in df_pd.columns, f"'{_col}' still missing."

df_pd['GEX_x_DTE_R0'] = (
    df_pd['GEX_Zscore'] * df_pd['DTE_R0_Expiry']
).astype(np.float32)

