# ── NEW 1: DTE Cyclical Encoding ─────────────────────────────────────────────
# Smooth sine/cosine on 7-day calendar cycle. DTE=0 and DTE=7 map to same
# position, preserving the weekly periodicity without hard binary thresholds.
# Uses only _dte_raw (already computed above). No leakage.
df_pd['DTE_Cyclic_Sin'] = np.sin(2.0 * np.pi * _dte_raw.values / 7.0).astype(np.float32)
df_pd['DTE_Cyclic_Cos'] = np.cos(2.0 * np.pi * _dte_raw.values / 7.0).astype(np.float32)
print(f"DTE cyclic encoding: sin range [{df_pd['DTE_Cyclic_Sin'].min():.3f}, "
      f"{df_pd['DTE_Cyclic_Sin'].max():.3f}]")

# ── NEW 2: WoW_Ret — Intra-Week Return From Last Expiry ──────────────────────
# Log return from the previous expiry's closing price to today's closing price.
# Captures where the market stands within its weekly expiry cycle.
# No look-ahead: previous expiry close is always known at 9:15 AM on prediction day.
# On expiry day itself: WoW_Ret = total return of the just-completed week.
_close_vals_arr  = df_pd['Spot_Close'].values
_expiry_day_mask = (_dte_raw == 0).values
_last_exp_px_arr = np.full(len(df_pd), np.nan)
_last_known_px   = np.nan
for _i in range(len(df_pd)):
    _last_exp_px_arr[_i] = _last_known_px
    if _expiry_day_mask[_i]:
        _last_known_px = _close_vals_arr[_i]
# Fill rows before first expiry with the first available close
_first_close_val = float(_close_vals_arr[0])
_last_exp_px_arr = np.where(np.isnan(_last_exp_px_arr), _first_close_val, _last_exp_px_arr)

df_pd['WoW_Ret'] = np.log(
    _close_vals_arr / _last_exp_px_arr
).clip(-0.15, 0.15).astype(np.float32)
df_pd['WoW_Ret'] = pd.Series(df_pd['WoW_Ret']).fillna(0.0).values.astype(np.float32)
print(f"WoW_Ret: range [{df_pd['WoW_Ret'].min():.4f}, {df_pd['WoW_Ret'].max():.4f}]")

# ── NEW 3: Hurst Exponent — Rolling R/S Analysis ─────────────────────────────
# H > 0.5 = trending (momentum), H < 0.5 = mean-reverting, H = 0.5 = random walk.
# Rolling window from past returns only → no look-ahead.
# Filled with 0.5 (random-walk neutral) for initial rows lacking sufficient history.
def _compute_rolling_hurst(returns_arr: np.ndarray, window: int) -> np.ndarray:
    """R/S Hurst exponent, rolling window. O(N·window) time."""
    n      = len(returns_arr)
    hurst_out = np.full(n, np.nan)
    for _i in range(window - 1, n):
        _x   = returns_arr[_i - window + 1 : _i + 1]
        _std = float(np.std(_x, ddof=1))
        if _std < 1e-10:
            hurst_out[_i] = 0.5
            continue
        _cum = np.cumsum(_x - np.mean(_x))
        _R   = float(np.max(_cum) - np.min(_cum))
        if _R < 1e-10:
            hurst_out[_i] = 0.5
        else:
            hurst_out[_i] = np.log(_R / _std) / np.log(window)
    return hurst_out

_log_ret_for_hurst = np.concatenate([
    [0.0],
    np.log(_close_vals_arr[1:] / np.maximum(_close_vals_arr[:-1], 1e-6))
])
_hurst_raw = _compute_rolling_hurst(_log_ret_for_hurst, CONFIG["hurst_window"])
df_pd['Hurst_40D'] = (
    pd.Series(_hurst_raw).fillna(0.5).clip(0.1, 0.9).values.astype(np.float32)
)
print(f"Hurst_40D: range [{df_pd['Hurst_40D'].min():.3f}, "
      f"{df_pd['Hurst_40D'].max():.3f}] | mean={df_pd['Hurst_40D'].mean():.3f}")

# ── NEW 4: Rolling Return Kurtosis ───────────────────────────────────────────
# Excess kurtosis of daily log returns (normal=0). High kurtosis = recent jump risk.
# Pandas .kurt() returns excess kurtosis. Uses only past returns → no leakage.
_ret_series_for_kurt = np.log(
    _close / _close.shift(1)
).fillna(0)
df_pd['Returns_Kurtosis_20D'] = (
    _ret_series_for_kurt.rolling(CONFIG["kurtosis_window"], min_periods=5)
    .kurt()
    .clip(-10, 30)
    .fillna(0)
    .astype(np.float32)
)
print(f"Returns_Kurtosis_20D: range [{df_pd['Returns_Kurtosis_20D'].min():.2f}, "
      f"{df_pd['Returns_Kurtosis_20D'].max():.2f}]")

# ── NEW 5: Feature Relationship / Domain-Encoded Features ────────────────────
# These encode known financial relationships directly, reducing the model's
# burden of re-discovering multiplicative / asymmetric interactions from scratch.

# VRP split: positive (implied > realized → premium selling opportunity, compresses vol)
#             negative (realized > implied → vol regime shift, widens expected range)
df_pd['VRP_Pos'] = np.maximum(df_pd['VRP_Daily'].values,  0.0).astype(np.float32)
df_pd['VRP_Neg'] = np.maximum(-df_pd['VRP_Daily'].values, 0.0).astype(np.float32)

# Pre-expiry × negative GEX: dealer short-gamma ON pre-expiry day → dangerous combo
df_pd['GEX_Neg_x_DTE_R1'] = (
    df_pd['GEX_Neg'].values * df_pd['DTE_R1_PreExp'].values
).astype(np.float32)

# Intraday range z-score × |GEX| magnitude: fat candle + high gamma = instability signal
df_pd['HL_Range_x_GEX_Abs'] = (
    df_pd['HL_Range_Zscore'].values * np.abs(df_pd['GEX_Zscore'].values)
).clip(-9.0, 9.0).astype(np.float32)

# VRP × vol regime: premium enriched in high-vol regime vs low-vol have opposite dynamics
df_pd['VRP_x_Vol_Regime'] = (
    df_pd['VRP_Daily'].values * df_pd['Vol_Regime_Zscore'].values
).clip(-3.0, 3.0).astype(np.float32)

# Put wall strength: (PCR_OI − 1)⁺ × skew⁺ → bearish positioning composite
# Positive only: signal fires when both put OI and put vol premium are elevated.
df_pd['Put_Wall_Strength'] = (
    np.maximum(df_pd['PCR_OI'].values - 1.0, 0.0) *
    np.maximum(df_pd['Options_Skew_25d'].values, 0.0)
).clip(0, 10.0).astype(np.float32)

# tanh-transformed 3D momentum consistency: smooth directional prior [-1, 1]
# Saturates for strong trends; provides finer gradient than linear integer counts.
for _mkt in ['sp500', 'crudeoil', 'hang_seng']:
    _c = f'Overnight_Momentum_{_mkt}_Consist_3D'
    df_pd[f'Overnight_Momentum_{_mkt}_Tanh_Weight'] = (
        np.tanh(df_pd[_c].values * 0.5)
    ).astype(np.float32)

print("Feature-relationship features computed.")

# ── NEW 6: Target — Next-Day Intraday H-L Range ──────────────────────────────
# log(High_{t+1} / Low_{t+1}) — used ONLY as a training label for the aux task.
# Not used as a feature (no look-ahead). Same temporal contract as Target_Ret_1D.
