# CELL 2 — MODEL DEFINITION  [Section 9]
# UNCHANGED from Section 7b — architecture is identical.
# The adaptive ratio target is injected via the config dict at training time
# (Cell 3), so no changes are needed here.
# ================================================================================

import torch.nn as nn
import torch.nn.functional as F
import torch
import math


def multi_quantile_pinball_loss(q_out_low, q_in_low, expected_return,
                                q_in_high, q_out_high, target, config):
    out_alpha = (100 - config.get("outer_ci_pct", 60)) / 200.0
    in_alpha  = (100 - config.get("inner_ci_pct", 20)) / 200.0
    q_levels  = [out_alpha, in_alpha, 1.0 - in_alpha, 1.0 - out_alpha]

    dir_loss = F.l1_loss(expected_return, target)

    mu_det     = expected_return.detach()
    target_res = target - mu_det
    preds_iso = [
        q_out_low  - expected_return + mu_det,
        q_in_low   - expected_return + mu_det,
        q_in_high  - expected_return + mu_det,
        q_out_high - expected_return + mu_det,
    ]
    outer_w = config.get("outer_quantile_weight", 1.5)
    inner_w = config.get("inner_quantile_weight", 0.75)
    weights  = [outer_w, inner_w, inner_w, outer_w]

    var_loss = 0.0
    for pred, q, w in zip(preds_iso, q_levels, weights):
        errors   = target_res - pred
        loss_val = torch.max(q * errors, (q - 1.0) * errors)
        if q == q_levels[1] or q == q_levels[2]:
            is_outside = (
                (target_res < preds_iso[1]) | (target_res > preds_iso[2])
            ).float()
            loss_val = loss_val * (1.0 + 0.20 * is_outside)
        var_loss += w * loss_val.mean()
    var_loss = var_loss / sum(weights)

    ratio_weight = config.get("inner_outer_ratio_weight", 0.0)
    if ratio_weight > 0.0:
        inner_width  = q_in_high - q_in_low
        outer_width  = (q_out_high - q_out_low).detach()
        actual_ratio = inner_width / (outer_width + 1e-5)
        # NOTE: target_ratio may be adaptive (per-batch) when called from
        # training with an overridden config dict. This is the hook for
        # Section 9's learned-DoF feature — no code change needed here.
        target_ratio = config.get("inner_outer_ratio_target", 0.289)
        ratio_loss   = F.mse_loss(
            actual_ratio, torch.full_like(actual_ratio, target_ratio))
        var_loss = var_loss + ratio_weight * ratio_loss

    width_cos_weight = config.get("width_cos_weight", 0.0)
    if width_cos_weight <= 0.0:
        return dir_loss, var_loss, None

    outer_width_per_sample = q_out_high - q_out_low
    is_missed   = ((target < q_out_low) | (target > q_out_high)).float().detach()
    n_missed    = is_missed.sum().clamp(min=1.0)
    ref_width   = outer_width_per_sample.detach().median().clamp(min=0.05)
    miss_penalty = (
        torch.exp(-outer_width_per_sample / ref_width) * is_missed
    ).sum() / n_missed
    return dir_loss, var_loss, miss_penalty


class RobustInstanceNorm(nn.Module):
    def __init__(self, num_features, eps=1e-5):
        super().__init__()
        self.gamma = nn.Parameter(torch.ones(num_features))
        self.beta  = nn.Parameter(torch.zeros(num_features))
        self.eps   = eps
    def forward(self, x):
        if len(x.shape) == 3:
            med = torch.median(x, dim=1, keepdim=True)[0]
            mad = torch.median(torch.abs(x - med), dim=1, keepdim=True)[0]
        else:
            med = torch.median(x, dim=0, keepdim=True)[0]
            mad = torch.median(torch.abs(x - med), dim=0, keepdim=True)[0]
        return (x - med) / (mad + self.eps) * self.gamma + self.beta


def generate_decay_mask(seq_len, decay_rate=0.15):
    mask = torch.zeros(seq_len, seq_len)
    for i in range(seq_len):
        for j in range(seq_len):
            if j <= i: mask[i, j] = -decay_rate * (i - j)
            else:      mask[i, j] = float('-inf')
    return mask


class GLU(nn.Module):
    def __init__(self, input_size):
        super().__init__()
        self.fc1 = nn.Linear(input_size, input_size)
        self.fc2 = nn.Linear(input_size, input_size)
    def forward(self, x): return torch.sigmoid(self.fc1(x)) * self.fc2(x)


class GatedResidualNetwork(nn.Module):
    def __init__(self, input_size, hidden_size, output_size, dropout=0.1):
        super().__init__()
        self.fc1        = nn.Linear(input_size, hidden_size)
        self.elu        = nn.ELU()
        self.fc2        = nn.Linear(hidden_size, output_size)
        self.dropout    = nn.Dropout(dropout)
        self.gate       = GLU(output_size)
        self.layer_norm = nn.LayerNorm(output_size)
        self.skip_proj  = nn.Linear(input_size, output_size) if input_size != output_size else nn.Identity()
    def forward(self, x):
        residual = self.skip_proj(x)
        x = self.fc1(x); x = self.elu(x); x = self.fc2(x)
        x = self.dropout(x); x = self.gate(x)
        return self.layer_norm(residual + x)


class AnchoredCrossAttentionTFT(nn.Module):
    def __init__(self, num_var_feats, num_dir_feats, vol_state_idx,
                 dte_state_idx,
                 seq_len=10, d_model=32, nhead=4, dropout=0.2,
                 num_targets=1, num_grn_layers=3, decay_rate=0.15):
        super().__init__()
        self.num_targets = num_targets
        self.seq_len     = seq_len
        self.register_buffer('vol_state_idx_buf',
                             torch.tensor(vol_state_idx, dtype=torch.long))
        self.register_buffer('dte_state_idx_buf',
                             torch.tensor(dte_state_idx, dtype=torch.long))

        self.dir_embed      = nn.Parameter(torch.randn(num_dir_feats, d_model))
        self.dir_attn       = nn.MultiheadAttention(embed_dim=d_model, num_heads=nhead,
                                                    dropout=dropout, batch_first=True)
        self.dir_layer_norm = nn.LayerNorm(d_model)
        self.mu_layer       = nn.Sequential(
            nn.Linear(d_model, d_model), nn.GELU(),
            nn.Dropout(dropout), nn.Linear(d_model, num_targets))

        self.var_norm       = RobustInstanceNorm(num_var_feats)
        self.var_proj       = nn.Linear(num_var_feats, d_model)
        self.var_grn_in     = nn.Sequential(*[
            GatedResidualNetwork(d_model, d_model * 2, d_model, dropout)
            for _ in range(num_grn_layers)])
        self.var_attn       = nn.MultiheadAttention(embed_dim=d_model, num_heads=nhead,
                                                    dropout=dropout, batch_first=True)
        self.var_layer_norm = nn.LayerNorm(d_model)
        self.var_grn_out    = GatedResidualNetwork(d_model, d_model, d_model, dropout)

        self.cross_attn = nn.MultiheadAttention(embed_dim=d_model, num_heads=nhead,
                                                dropout=dropout, batch_first=True)
        self.fusion_grn = GatedResidualNetwork(d_model * 2, d_model * 2, d_model, dropout)

        self.spread_layer = nn.Linear(d_model, 4)
        self.aux_layer    = nn.Linear(d_model, num_targets)

        _vol_gate_in = len(vol_state_idx) * 2 + len(dte_state_idx)
        self.vol_gate = nn.Sequential(
            nn.Linear(_vol_gate_in, 16), nn.GELU(),
            nn.Linear(16, 4), nn.Sigmoid())

        pe       = torch.zeros(seq_len, d_model)
        position = torch.arange(0, seq_len, dtype=torch.float).unsqueeze(1)
        div_term = torch.exp(torch.arange(0, d_model, 2).float()
                             * (-math.log(10000.0) / d_model))
        pe[:, 0::2] = torch.sin(position * div_term)
        pe[:, 1::2] = torch.cos(position * div_term)
        self.register_buffer('pe', pe.unsqueeze(0))
        self.register_buffer('decay_mask', generate_decay_mask(seq_len, decay_rate))

    def forward(self, x, idx_var, idx_dir):
        x_var = x[:, :, idx_var]
        x_dir = x[:, :, idx_dir]
        mask  = self.decay_mask.to(x.device)

        x_dir_last    = x_dir[:, -1, :]
        dir_embedded  = x_dir_last.unsqueeze(-1) * self.dir_embed.unsqueeze(0)
        d_attn_out, _ = self.dir_attn(dir_embedded, dir_embedded, dir_embedded)
        d_out         = self.dir_layer_norm(dir_embedded + d_attn_out)
        dir_context   = d_out.mean(dim=1)
        expected_return = self.mu_layer(dir_context)

        x_var_norm    = self.var_norm(x_var)
        v_in          = self.var_proj(x_var_norm)
        v_in          = self.var_grn_in(v_in) + self.pe
        v_attn_out, _ = self.var_attn(v_in, v_in, v_in, attn_mask=mask)
        v_seq         = self.var_layer_norm(v_in + v_attn_out)
        v_last        = self.var_grn_out(v_seq[:, -1, :])

        query        = dir_context.unsqueeze(1).detach()
        cross_out, _ = self.cross_attn(query, v_seq, v_seq)
        cross_out    = cross_out.squeeze(1)
        fused        = self.fusion_grn(torch.cat([v_last, cross_out], dim=-1))

        vol_state_now  = x_var[:, -1, self.vol_state_idx_buf]
        hist_len       = min(5, x_var.shape[1] - 1)
        vol_state_hist = (x_var[:, -(hist_len + 1):-1, self.vol_state_idx_buf].mean(dim=1)
                          if hist_len > 0 else vol_state_now)
        dte_state      = x_var[:, -1, self.dte_state_idx_buf]

        vol_gate  = 0.5 + self.vol_gate(
            torch.cat([vol_state_now, vol_state_hist, dte_state], dim=-1))

        raw_spreads = (F.softplus(self.spread_layer(fused)) + 1e-5) * vol_gate

        dir_bias      = torch.tanh(expected_return.detach())
        skew          = 0.3 * dir_bias

        spread_d_core = (raw_spreads[:, 0:1] * (1.0 - skew)).clamp(min=1e-5)
        spread_u_core = (raw_spreads[:, 1:2] * (1.0 + skew)).clamp(min=1e-5)
        spread_d_tail = (raw_spreads[:, 2:3] * (1.0 - skew)).clamp(min=1e-5)
        spread_u_tail = (raw_spreads[:, 3:4] * (1.0 + skew)).clamp(min=1e-5)

        q40  = expected_return - spread_d_core
        q60  = expected_return + spread_u_core
        q075 = q40 - spread_d_tail
        q925 = q60 + spread_u_tail

        aux_preds = self.aux_layer(v_last)
        return q075, q40, expected_return, q60, q925, aux_preds


_anchor_epochs = int(CONFIG["epochs"] * CONFIG["anchor_epoch_multiplier"])
_ww = CONFIG.get("width_cos_weight", 0.0)
print("AnchoredCrossAttentionTFT loaded — architecture UNCHANGED from Section 7b.")
print(f"  Vol gate input : {len(VOL_STATE_IDX)*2} + {len(DTE_STATE_IDX)} = "
      f"{len(VOL_STATE_IDX)*2 + len(DTE_STATE_IDX)}")
print(f"  anchor_epochs={_anchor_epochs} | inner_outer_ratio_weight={CONFIG['inner_outer_ratio_weight']}")
print(f"  [NOTE] Adaptive DoF injected via per-batch config dict in training loop.")
print(f"  [NOTE] Aux head now trained to predict vol-normalised log(H/L) range.")

# ================================================================================
# CELL 3 — RANDOM SAMPLING EXECUTION  [Section 9]
# Changes vs Section 7b:
#   + _TRAIN_VOL_MEAN / _TRAIN_VOL_STD: module-level globals set per split,
#     read inside _train_ensemble for adaptive DoF computation.
#   + _train_ensemble: per-batch adaptive ratio target; aux task trains on
#     vol-normalised next-day H-L range instead of |return|.
#   + _run_inference: captures actual HL range in s["hl_ranges"] (from y col 1).
#   + _compute_metrics: adds hl_range_ic (Spearman IC of outer width vs HL range).
#   All existing outputs and metric keys preserved.
# ================================================================================

import torch.optim as optim
import numpy as np
import math
from scipy import stats as scipy_stats
from sklearn.preprocessing import StandardScaler

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

IDX_VAR    = torch.tensor(VAR_IDX,    dtype=torch.long, device=device)
IDX_DIR_1D = torch.tensor(DIR_IDX_1D, dtype=torch.long, device=device)

# ── Intraday direction (unchanged) ────────────────────────────────────────────
_intraday_ret_raw = (df_pd['Spot_Close'].values - df_pd['Spot_Open'].values)
intraday_dir_raw  = np.sign(_intraday_ret_raw).astype(np.float32)

# ── Global vol stats for adaptive DoF ────────────────────────────────────────
# Set to defaults here; overwritten per-split before calling _train_ensemble.
# _train_ensemble reads these at batch time (Python global lookup) so they
# must be set BEFORE the first call.
_TRAIN_VOL_MEAN: float = 0.20
_TRAIN_VOL_STD:  float = 0.10


def winkler_score(actual, lower, upper, alpha=0.15):
    w  = upper - lower
    pl = np.where(actual < lower, (2/alpha)*(lower - actual), 0.0)
    pu = np.where(actual > upper, (2/alpha)*(actual - upper), 0.0)
    return float(np.mean(w + pl + pu))


def christoffersen_test(actuals, lowers, uppers):
    hits = ((lowers <= actuals) & (actuals <= uppers)).astype(int)
    n    = len(hits)
    n00  = int(((hits[:-1]==0)&(hits[1:]==0)).sum())
    n01  = int(((hits[:-1]==0)&(hits[1:]==1)).sum())
    n10  = int(((hits[:-1]==1)&(hits[1:]==0)).sum())
    n11  = int(((hits[:-1]==1)&(hits[1:]==1)).sum())
    if (n00+n01)==0 or (n10+n11)==0:
        return {"p_value": 1.0, "clustered": False}
    pi_01 = n01/(n00+n01); pi_10 = n10/(n10+n11)
    pi    = (n01+n11)/max(n-1, 1)
    if pi in (0., 1.) or pi_01 in (0., 1.) or pi_10 in (0., 1.):
        return {"p_value": 1.0, "clustered": False}
    try:
        lr = -2*(
            n00*np.log(max(1-pi,1e-10))    + n01*np.log(max(pi,1e-10)) +
            n10*np.log(max(1-pi,1e-10))    + n11*np.log(max(pi,1e-10))
          -(n00*np.log(max(1-pi_01,1e-10)) + n01*np.log(max(pi_01,1e-10)) +
            n10*np.log(max(1-pi_10,1e-10)) + n11*np.log(max(pi_10,1e-10))))
        p = float(1 - scipy_stats.chi2.cdf(lr, df=1))
    except Exception:
        p = 1.0
    return {"p_value": p, "clustered": bool(p < 0.05)}


def _train_ensemble(loader_tr, seq_len, dir_idx_tensor, y_col, vol_scale_fn, tag):
    """
    Train an ensemble of AnchoredCrossAttentionTFT models.

    Section 9 additions:
      (a) Adaptive DoF: per-batch inner_outer_ratio_target derived from vol regime.
          Reads _TRAIN_VOL_MEAN / _TRAIN_VOL_STD globals (set by caller).
          Falls back to fixed CONFIG ratio when df_vol_sensitivity == 0.
      (b) Log-range aux task: aux head trains on vol-normalised next-day H-L range
          (yb[:, 1:2] / ve) instead of |return|. Requires y_raw to have 2 columns.
    """
    models            = []
    per_model_dir_idx = []
    n_dir             = len(dir_idx_tensor)
    ratio             = CONFIG.get("dir_feature_subsample_ratio", 0.75)
    n_sub             = max(int(n_dir * ratio), 1)
    anchor_mult       = CONFIG.get("anchor_epoch_multiplier", 1.0)
    width_cos_weight  = CONFIG.get("width_cos_weight", 0.0)
    use_pcgrad        = width_cos_weight > 0.0
    _df_sensitivity   = CONFIG.get("df_vol_sensitivity", 0.0)
    _use_adaptive_df  = (_df_sensitivity > 0.0 and
                         CONFIG.get("inner_outer_ratio_weight", 0.0) > 0.0)

    for i in range(CONFIG["n_ensembles"]):
        if i == 0:
            model_dir_idx = dir_idx_tensor
            n_epochs      = int(CONFIG["epochs"] * anchor_mult)
        else:
            perm          = torch.randperm(n_dir, device=device)[:n_sub]
            perm_sorted, _= perm.sort()
            model_dir_idx = dir_idx_tensor[perm_sorted]
            n_epochs      = CONFIG["epochs"]

        per_model_dir_idx.append(model_dir_idx)

        m = AnchoredCrossAttentionTFT(
            num_var_feats  = len(VAR_IDX),
            num_dir_feats  = len(model_dir_idx),
            vol_state_idx  = VOL_STATE_IDX,
            dte_state_idx  = DTE_STATE_IDX,
            seq_len        = seq_len,
            d_model        = CONFIG["d_model"],
            nhead          = CONFIG["nhead"],
            dropout        = CONFIG["dropout"],
            num_targets    = 1,
            num_grn_layers = CONFIG["num_grn_layers"],
            decay_rate     = CONFIG["attn_decay_rate"],
        ).to(device)

        opt = torch.optim.AdamW(m.parameters(), lr=CONFIG["lr"], weight_decay=3e-4)
        sch = torch.optim.lr_scheduler.CosineAnnealingWarmRestarts(
            opt, T_0=10, T_mult=2) if CONFIG["use_lr_scheduler"] else None

        param_list = list(m.parameters())
        best = float('inf'); final = 0.0

        for _ in range(n_epochs):
            m.train(); ep = 0.0
            for Xb, yb, vb in loader_tr:
                Xb, yb, vb = Xb.to(device), yb.to(device), vb.to(device)
                opt.zero_grad()

                q075, q40, er, q60, q925, aux = m(Xb, IDX_VAR, model_dir_idx)
                ve = vol_scale_fn(vb)               # (B,1) vol scaling
                ys = yb[:, y_col:y_col+1] / ve      # (B,1) normalised c-t-c return

                # ── (a) Adaptive DoF: per-batch ratio target ──────────────────
                if _use_adaptive_df:
                    _bv       = float(vb.mean().item())
                    _vz       = float(np.clip(
                        (_bv - _TRAIN_VOL_MEAN) / (_TRAIN_VOL_STD + 1e-6),
                        -2.0, 2.0))
                    _adf      = float(np.clip(
                        CONFIG["df"] * (1.0 - _df_sensitivity * _vz),
                        CONFIG["df_min"], CONFIG["df_max"]))
                    _adap_r   = float(
                        scipy_stats.t.ppf(inner_q, _adf) /
                        scipy_stats.t.ppf(outer_q, _adf))
                    _loss_cfg = {**CONFIG, "inner_outer_ratio_target": _adap_r}
                else:
                    _loss_cfg = CONFIG

                dl, vl, wl = multi_quantile_pinball_loss(
                    q075, q40, er, q60, q925, ys, _loss_cfg)

                # ── (b) Log-range auxiliary task ──────────────────────────────
                # yb[:, 1:2] = Target_HL_Range_1D (log(H_{t+1}/L_{t+1}), ≥0)
                # Normalised by vol so the aux target is dimensionless ~[0, 3]
                hl_target    = yb[:, 1:2] / (ve + 1e-6)  # (B,1)
                loss_aux     = F.mse_loss(aux, hl_target)

                primary_loss = (CONFIG["dir_weight"] * dl
                                + vl
                                + CONFIG["aux_task_weight"] * loss_aux)

                if use_pcgrad and wl is not None:
                    primary_loss.backward(retain_graph=True)
                    torch.nn.utils.clip_grad_norm_(m.parameters(), 1.0)
                    g_primary = [
                        p.grad.clone() if p.grad is not None else None
                        for p in param_list
                    ]
                    opt.zero_grad()
                    wl.backward()
                    torch.nn.utils.clip_grad_norm_(m.parameters(), 1.0)
                    for idx, p in enumerate(param_list):
                        g_w = p.grad; g_p = g_primary[idx]
                        if g_p is None and g_w is None:
                            continue
                        elif g_w is None or g_p is None:
                            p.grad = g_p; continue
                        g_w_flat = g_w.view(-1); g_p_flat = g_p.view(-1)
                        dot      = (g_w_flat * g_p_flat).sum()
                        norm_sq  = (g_p_flat * g_p_flat).sum().clamp(min=1e-12)
                        g_w_star = g_w - (dot / norm_sq) * g_p
                        p.grad   = g_p + width_cos_weight * g_w_star
                else:
                    primary_loss.backward()
                    torch.nn.utils.clip_grad_norm_(m.parameters(), 1.0)

                opt.step()
                ep += primary_loss.item()

            avg = ep / len(loader_tr)
            if avg < best: best = avg
            final = avg
            if sch: sch.step()

        models.append(m)
        anchor_tag = f"[anchor, {n_epochs}ep]" if i == 0 else f"[{n_epochs}ep]"
        pcgrad_tag = f" PCGrad(w={width_cos_weight})" if use_pcgrad else ""
        print(f"     [{tag}] Model {i+1} | dir={len(model_dir_idx)}/{n_dir} "
              f"{anchor_tag}{pcgrad_tag} "
              f"| Best: {best:.5f} | Final: {final:.5f}")

    return models, per_model_dir_idx


def _run_inference(loader, models, per_model_dir_idx, y_col,
                   intraday_dir_slice, is_5d=False):
    """
    Section 9 addition: captures s["hl_ranges"] from y column 1
    (Target_HL_Range_1D). All existing keys and logic unchanged.
    """
    out = {k: [] for k in (
        "actuals", "lowers_out", "lowers_in", "uppers_in",
        "uppers_out", "means", "vols_ann", "intraday_dirs",
        "hl_ranges",   # NEW: actual next-day log(H/L) range from label
    )}
    _intra_cursor = 0

    for m in models:
        m.eval()

    with torch.no_grad():
        for Xb, yb, vb in loader:
            Xg, vg = Xb.to(device), vb.to(device)
            ya     = yb.numpy()          # shape (B, 2) — col0=ret, col1=HL range
            batch_size = Xb.shape[0]

            Qs = [[] for _ in range(5)]
            for m, m_dir_idx in zip(models, per_model_dir_idx):
                o = m(Xg, IDX_VAR, m_dir_idx)
                for k in range(5):
                    Qs[k].append(o[k])

            Qm = [torch.mean(torch.stack(Qs[k]), 0) for k in range(5)]
            vm  = (vg * math.sqrt(5) if is_5d else vg).unsqueeze(-1)
            r   = [(Qm[k] * vm).cpu().numpy() for k in range(5)]

            for b in range(batch_size):
                out["lowers_out"].append(r[0][b, 0])
                out["lowers_in"].append(r[1][b, 0])
                out["means"].append(r[2][b, 0])
                out["uppers_in"].append(r[3][b, 0])
                out["uppers_out"].append(r[4][b, 0])
                out["actuals"].append(ya[b, y_col])          # col 0: c-t-c return
                out["vols_ann"].append(vb[b].item())
                out["intraday_dirs"].append(
                    float(intraday_dir_slice[_intra_cursor]))
                out["hl_ranges"].append(float(ya[b, 1]))     # col 1: H-L range
                _intra_cursor += 1

    return {k: np.array(v, dtype=np.float32) for k, v in out.items()}


def _compute_metrics(s):
    """
    Section 9 addition: hl_range_ic — Spearman IC between predicted outer
    band width and actual next-day H-L range.
    Positive significant IC = model uncertainty is genuinely predictive of
    realized intraday range, not just coverage-driven width.
    All existing keys preserved unchanged.
    """
    a      = s["actuals"]
    m      = s["means"]
    l_out, u_out = s["lowers_out"], s["uppers_out"]
    l_in,  u_in  = s["lowers_in"],  s["uppers_in"]
    i_dir  = s["intraday_dirs"]

    hr_out = float(np.mean((l_out <= a) & (a <= u_out)) * 100)
    hr_in  = float(np.mean((l_in  <= a) & (a <= u_in))  * 100)
    rng85  = (u_out - l_out) * 100
    rng20  = (u_in  - l_in)  * 100

    dir_ctc = float(np.mean(np.sign(m) == np.sign(a)) * 100)
    naive   = float(np.mean(a > 0) * 100)

    valid_mask  = i_dir != 0
    n_valid     = int(valid_mask.sum())
    if n_valid > 0:
        pred_sign    = np.sign(m[valid_mask])
        actual_intra = i_dir[valid_mask]
        dir_intraday = float(np.mean(pred_sign == actual_intra) * 100)
        naive_intraday = float(np.mean(actual_intra > 0) * 100)
        hits_intra   = int((pred_sign == actual_intra).sum())
        from scipy.stats import binomtest
        p_intraday = float(
            binomtest(hits_intra, n_valid, 0.5, alternative='two-sided').pvalue)
    else:
        dir_intraday = naive_intraday = p_intraday = float('nan')
        n_valid = 0

    outer_alpha = (100 - CONFIG["outer_ci_pct"]) / 100.0
    wink  = winkler_score(a, l_out, u_out, alpha=outer_alpha)
    eff   = wink / (float(np.mean(np.abs(a))) + 1e-9)
    chri  = christoffersen_test(a, l_out, u_out)
    inner_w  = np.mean(u_in  - l_in)
    outer_w  = np.mean(u_out - l_out)
    io_ratio = float(inner_w / (outer_w + 1e-9))

    # ── NEW: HL Range Rank IC ─────────────────────────────────────────────────
    # Spearman IC between predicted outer band width (return space) and the
    # actual next-day log(High/Low) range. Valid rows only (HL range > 0).
    hl_ranges_arr = s.get("hl_ranges", None)
    if hl_ranges_arr is not None and len(hl_ranges_arr) > 0:
        _hl_arr  = np.asarray(hl_ranges_arr, dtype=np.float32)
        _ow_arr  = u_out - l_out                   # outer width (return space)
        _valid_hl = _hl_arr > 1e-5                 # exclude fill-zero last row
        if int(_valid_hl.sum()) > 10:
            _hl_ic, _hl_p = scipy_stats.spearmanr(_ow_arr[_valid_hl], _hl_arr[_valid_hl])
            _hl_ic, _hl_p = float(_hl_ic), float(_hl_p)
        else:
            _hl_ic, _hl_p = float('nan'), float('nan')
    else:
        _hl_ic, _hl_p = float('nan'), float('nan')

    return dict(
        hr_85=hr_out,  rng_85_mean=float(np.mean(rng85)),
        rng_85_min=float(np.min(rng85)), rng_85_max=float(np.max(rng85)),
        hr_20=hr_in,   rng_20_mean=float(np.mean(rng20)),
        dir=dir_ctc,   naive=naive,
        dir_intraday=dir_intraday, naive_intraday=naive_intraday,
        p_intraday=p_intraday,     n_intraday_valid=n_valid,
        wink=wink,     eff=eff,
        christo_p=chri["p_value"], christo_clust=chri["clustered"],
        inner_outer_ratio=io_ratio,
        hl_range_ic=_hl_ic,        hl_range_ic_p=_hl_p,   # NEW
    )


pipeline_results = []
last_actuals_1d = last_lowers_1d = last_uppers_1d = last_means_1d = None
last_dates_1d   = None

# ── Pre-calculate non-overlapping splits ─────────────────────────────────────
generated_splits = []
used_test_ranges = []
_req_space = CONFIG["test_size"] + CONFIG["purge_gap"]

_max_allowable_min_train = len(X_raw) - (CONFIG["num_runs"] * _req_space)
_absolute_min_train = 400

if _max_allowable_min_train <= _absolute_min_train:
    _min_train_size = _absolute_min_train
else:
    _min_train_size = random.randint(_absolute_min_train, _max_allowable_min_train)

for _ in range(CONFIG["num_runs"]):
    _max_train_idx = len(X_raw) - _req_space
    _found_split   = False
    for _retry in range(2000):
        _t_end    = random.randint(_min_train_size, _max_train_idx)
        _te_start = _t_end + CONFIG["purge_gap"]
        _te_end   = _te_start + CONFIG["test_size"]
        _is_overlapping = any(
            max(_te_start, u_start) < min(_te_end, u_end)
            for (u_start, u_end) in used_test_ranges
        )
        if not _is_overlapping:
            generated_splits.append({'train': (0, _t_end), 'test': (_te_start, _te_end)})
            used_test_ranges.append((_te_start, _te_end))
            _found_split = True
            break
    if not _found_split:
        print(f"\n⚠️ WARNING: Space limit reached after {len(generated_splits)} splits.")
        break

actual_num_runs = len(generated_splits)
if actual_num_runs == 0:
    raise RuntimeError("Failed to generate any valid train/test splits.")

for run in range(1, actual_num_runs + 1):
    print(f"\n{'='*60}\nPIPELINE RUN {run}/{actual_num_runs}\n{'='*60}")

    split = generated_splits[run - 1]
    tr_start, tr_end = split['train']
    te_start, te_end = split['test']
    print(f"Train: 0-{tr_end} | Test: {te_start}-{te_end}")

    X_tr = X_raw[tr_start:tr_end]; y_tr = y_raw[tr_start:tr_end]; v_tr = vol_raw[tr_start:tr_end]
    X_te = X_raw[te_start:te_end]; y_te = y_raw[te_start:te_end]; v_te = vol_raw[te_start:te_end]

    sc_std = StandardScaler(); sc_dir = StandardScaler(with_mean=False)
    Xtr = np.zeros_like(X_tr, dtype=np.float32); Xte = np.zeros_like(X_te, dtype=np.float32)
    Xtr[:, VAR_IDX]     = sc_std.fit_transform(X_tr[:, VAR_IDX])
    Xte[:, VAR_IDX]     = sc_std.transform(X_te[:, VAR_IDX])
    Xtr[:, ALL_DIR_IDX] = sc_dir.fit_transform(X_tr[:, ALL_DIR_IDX])
    Xte[:, ALL_DIR_IDX] = sc_dir.transform(X_te[:, ALL_DIR_IDX])

    trd  = NiftySequenceDataset(Xtr, y_tr, v_tr, CONFIG["seq_len_1d"])
    ted  = NiftySequenceDataset(Xte, y_te, v_te, CONFIG["seq_len_1d"])
    trl1 = DataLoader(trd, CONFIG["batch_size"], shuffle=True,  drop_last=True)
    tel1 = DataLoader(ted, CONFIG["batch_size"], shuffle=False)

    _seq = CONFIG["seq_len_1d"]
    _te_pred_start  = te_start + _seq - 1
    _te_pred_end    = te_end
    intraday_dir_te = intraday_dir_raw[_te_pred_start : _te_pred_end]

    # ── Set vol stats for adaptive DoF (computed from TRAINING data only) ─────
    _TRAIN_VOL_MEAN = float(np.mean(v_tr))
    _TRAIN_VOL_STD  = max(float(np.std(v_tr, ddof=1)), 1e-6)
    print(f"  Vol stats for adaptive DoF: mean={_TRAIN_VOL_MEAN:.4f}  "
          f"std={_TRAIN_VOL_STD:.4f}")

    print("\n  -> Training 1D Ensembles...")
    e1, dir_idx_list = _train_ensemble(
        trl1, CONFIG["seq_len_1d"], IDX_DIR_1D, 0,
        lambda vb: vb.unsqueeze(-1) + 1e-6, "1D")

    s1 = _run_inference(tel1, e1, dir_idx_list, y_col=0,
                        intraday_dir_slice=intraday_dir_te, is_5d=False)
    m1 = _compute_metrics(s1)

    _sig_intra = (
        f"p={m1['p_intraday']:.5f} "
        f"({'SIGNIFICANT' if m1['p_intraday'] < 0.05 else 'not significant'})"
    )
    _sig_hl = (
        f"p={m1['hl_range_ic_p']:.4f} "
        f"({'sig' if m1['hl_range_ic_p'] < 0.05 else 'n.s.'})"
        if not np.isnan(m1['hl_range_ic_p']) else "n/a"
    )
    print(
        f"\n[1D] {CONFIG['outer_ci_pct']}% HR: {m1['hr_85']:.2f}% "
        f"| Rng: {m1['rng_85_mean']:.2f}% "
        f"| Dir C2C: {m1['dir']:.2f}% (Naive: {m1['naive']:.2f}%) "
        f"| Dir Intraday: {m1['dir_intraday']:.2f}% "
        f"(Naive: {m1['naive_intraday']:.2f}%, n={m1['n_intraday_valid']}, {_sig_intra})"
        f"\n      Wink: {m1['wink']:.4f} | Eff: {m1['eff']:.3f}"
        f" | IO_ratio: {m1['inner_outer_ratio']:.3f} (target {CONFIG['inner_outer_ratio_target']})"
        f" | Christo p={m1['christo_p']:.3f}"
        f"\n      HL Range IC: {m1['hl_range_ic']:.3f} ({_sig_hl})"
    )

    res = {
        "run": run, "train_range": f"0-{tr_end}", "test_range": f"{te_start}-{te_end}",
        "hr_85_1d": m1["hr_85"],       "rng_85_1d":    m1["rng_85_mean"],
        "rng_85_min_1d": m1["rng_85_min"], "rng_85_max_1d": m1["rng_85_max"],
        "hr_20_1d": m1["hr_20"],       "rng_20_1d":    m1["rng_20_mean"],
        "dir_1d":   m1["dir"],         "naive_1d":     m1["naive"],
        "dir_intraday_1d": m1["dir_intraday"],
        "naive_intraday_1d": m1["naive_intraday"],
        "p_intraday_1d": m1["p_intraday"],
        "wink_1d":  m1["wink"],        "wink_eff_1d":  m1["eff"],
        "christo_p_1d": m1["christo_p"], "christo_clust_1d": m1["christo_clust"],
        "io_ratio_1d": m1["inner_outer_ratio"],
        "hl_range_ic_1d": m1["hl_range_ic"],        # NEW
        "hl_range_ic_p_1d": m1["hl_range_ic_p"],    # NEW
        "series_1d": {
            "actuals":       s1["actuals"],
            "lowers":        s1["lowers_out"],
            "uppers":        s1["uppers_out"],
            "lowers_out":    s1["lowers_out"],
            "uppers_out":    s1["uppers_out"],
            "means":         s1["means"],
            "vols_ann":      s1["vols_ann"],
            "intraday_dirs": s1["intraday_dirs"],
            "hl_ranges":     s1["hl_ranges"],        # NEW
        },
    }

    pipeline_results.append(res)

    if run == actual_num_runs:
        last_actuals_1d = s1["actuals"].tolist()
        last_lowers_1d  = s1["lowers_out"].tolist()
        last_uppers_1d  = s1["uppers_out"].tolist()
        last_means_1d   = s1["means"].tolist()
        last_dates_1d   = df_pd['Date'].values[
            te_start + CONFIG["seq_len_1d"] - 1 :
            te_start + CONFIG["seq_len_1d"] - 1 + len(s1["actuals"])]

    del e1
    torch.cuda.empty_cache()

