# CELL 6 — WALK-FORWARD RESULTS WITH NIFTY POINT TRANSLATION  [Section 9]
# Changes vs Section 7b:
#   + Aggregate hl_range_ic printed in the evaluation summary.
#   + Band sanity check and all plots are UNCHANGED.
