import numpy as np
import plotly.graph_objects as go
from scipy import stats as scipy_stats

print("\n" + "="*80)
print("PHASE 5: UNIVERSAL WALK-FORWARD EVALUATION & TRANSLATION")
print("="*80)


def winkler_score_c6(actual, lower, upper, alpha=0.15):
    w  = upper - lower
    pl = np.where(actual < lower, (2/alpha)*(lower - actual), 0)
    pu = np.where(actual > upper, (2/alpha)*(actual - upper), 0)
    return np.mean(w + pl + pu)


def christoffersen_test_c6(actuals, lowers, uppers):
    hits = np.array([1 if l <= a <= u else 0
                     for a, l, u in zip(actuals, lowers, uppers)])
    n    = len(hits)
    n00  = sum(1 for i in range(1, n) if hits[i-1]==0 and hits[i]==0)
    n01  = sum(1 for i in range(1, n) if hits[i-1]==0 and hits[i]==1)
    n10  = sum(1 for i in range(1, n) if hits[i-1]==1 and hits[i]==0)
    n11  = sum(1 for i in range(1, n) if hits[i-1]==1 and hits[i]==1)
    if (n00 + n01) == 0 or (n10 + n11) == 0:
        return {"p_value": 1.0, "clustered": False}
    pi_01 = n01 / (n00 + n01); pi_10 = n10 / (n10 + n11)
    pi    = (n01 + n11) / max(n - 1, 1)
    if pi in [0.0, 1.0] or pi_01 in [0.0, 1.0] or pi_10 in [0.0, 1.0]:
        return {"p_value": 1.0, "clustered": False}
    try:
        lr = -2 * (
            (n00*np.log(max(1-pi,1e-10))    + n01*np.log(max(pi,1e-10)) +
             n10*np.log(max(1-pi,1e-10))    + n11*np.log(max(pi,1e-10))) -
            (n00*np.log(max(1-pi_01,1e-10)) + n01*np.log(max(pi_01,1e-10)) +
             n10*np.log(max(1-pi_10,1e-10)) + n11*np.log(max(pi_10,1e-10))))
        p_value = float(1 - scipy_stats.chi2.cdf(lr, df=1))
    except Exception:
        return {"p_value": 1.0, "clustered": False}
    return {"p_value": p_value, "clustered": bool(p_value < 0.05)}


# ── Load arrays ───────────────────────────────────────────────────────────────
base_px  = np.array(wf_base_prices_1d, dtype=np.float64)
act_lr   = np.array(wf_actuals_1d,     dtype=np.float64)
m_lr     = np.array(wf_means_1d,       dtype=np.float64)
lo85_lr  = np.array(wf_lowers_85_1d,   dtype=np.float64)
hi85_lr  = np.array(wf_uppers_85_1d,   dtype=np.float64)
lo20_lr  = np.array(wf_lowers_20_1d,   dtype=np.float64)
hi20_lr  = np.array(wf_uppers_20_1d,   dtype=np.float64)
hl_ranges_wf = wf_continuous_1d["hl_ranges"].astype(np.float64)  # NEW

print(f"\n[Spot_Close sanity] min={base_px.min():.0f}  max={base_px.max():.0f}  "
      f"mean={base_px.mean():.0f}  (expected: 8,000 – 30,000 for Nifty 50)")
if base_px.max() > 40000 or base_px.min() < 1000:
    print("  WARNING: values outside expected Nifty 50 range.")

# ── Index-point conversion ────────────────────────────────────────────────────
act_px   = base_px * np.exp(act_lr)
m_px     = base_px * np.exp(m_lr)
lo85_px  = base_px * np.exp(lo85_lr)
hi85_px  = base_px * np.exp(hi85_lr)
lo20_px  = base_px * np.exp(lo20_lr)
hi20_px  = base_px * np.exp(hi20_lr)

band85_px = hi85_px - lo85_px
band20_px = hi20_px - lo20_px

_avg_band_pct = float(np.mean(hi85_lr - lo85_lr)) * 100
_expected_pts = float(np.mean(base_px)) * (_avg_band_pct / 100)
_computed_pts = float(np.mean(band85_px))
print(f"[Band sanity] avg_band={_avg_band_pct:.2f}% × avg_base={np.mean(base_px):.0f} "
      f"→ expected {_expected_pts:.0f} pts | computed {_computed_pts:.0f} pts")

# ── Percentage-space metrics ──────────────────────────────────────────────────
rng85   = (hi85_lr - lo85_lr) * 100
rng20   = (hi20_lr - lo20_lr) * 100
hr85    = np.mean((act_lr >= lo85_lr) & (act_lr <= hi85_lr)) * 100
hr20    = np.mean((act_lr >= lo20_lr) & (act_lr <= hi20_lr)) * 100
dir_acc = np.mean(np.sign(m_lr) == np.sign(act_lr)) * 100
naive   = np.mean(act_lr > 0) * 100
wink    = winkler_score_c6(act_lr, lo85_lr, hi85_lr, alpha=0.15)
weff    = wink / (np.mean(np.abs(act_lr)) + 1e-9)
chri    = christoffersen_test_c6(act_lr, lo85_lr, hi85_lr)
io_rat  = float(np.mean(hi20_lr - lo20_lr) / (np.mean(hi85_lr - lo85_lr) + 1e-9))

# ── HL Range IC on the full WF series ────────────────────────────────────────
_outer_widths_wf = hi85_lr - lo85_lr
_valid_hl_wf     = hl_ranges_wf > 1e-5
if int(_valid_hl_wf.sum()) > 10:
    _hl_ic_wf, _hl_p_wf = scipy_stats.spearmanr(
        _outer_widths_wf[_valid_hl_wf], hl_ranges_wf[_valid_hl_wf])
    _hl_ic_wf, _hl_p_wf = float(_hl_ic_wf), float(_hl_p_wf)
    _sig_hl_wf = (f"p={_hl_p_wf:.4f} "
                  f"({'sig' if _hl_p_wf < 0.05 else 'n.s.'})")
else:
    _hl_ic_wf, _hl_p_wf = float('nan'), float('nan')
    _sig_hl_wf = "n/a"

print("-" * 80)
print(f"[1D CONTINUOUS EVALUATION] (Total Days: {len(base_px)})")
print(f"  Nifty base range (pts) : {base_px.min():.0f} – {base_px.max():.0f}")
print(f"  85% Hit Rate           : {hr85:.2f}% | Avg Rng: {np.mean(rng85):.2f}% "
      f"(Min: {np.min(rng85):.2f}%, Max: {np.max(rng85):.2f}%)")
print(f"  20% Core Hit Rate      : {hr20:.2f}% | Avg Rng: {np.mean(rng20):.2f}%"
      f" | IO ratio: {io_rat:.3f} (target 0.165)")
print(f"  Directional Accuracy   : {dir_acc:.2f}% (Naive: {naive:.2f}%)")
print(f"  Winkler Score (85%)    : {wink:.4f} | Efficiency: {weff:.3f}")
print(f"  Miss Autocorr          : p={chri['p_value']:.3f} | Clustered: {chri['clustered']}")
print(f"  85% Band (Nifty pts)   : {np.mean(band85_px):.1f} avg "
      f"(Min: {np.min(band85_px):.1f},  Max: {np.max(band85_px):.1f})")
print(f"  20% Band (Nifty pts)   : {np.mean(band20_px):.1f} avg "
      f"(Min: {np.min(band20_px):.1f},  Max: {np.max(band20_px):.1f})")
print(f"  HL Range IC            : {_hl_ic_wf:.3f} ({_sig_hl_wf})")   # NEW
print("-" * 80)


def _plot_wf(dates, actuals, lowers, uppers, means, title, y_label,
             lowers_20=None, uppers_20=None):
    fig    = go.Figure()
    ranges = uppers - lowers
    mi     = int(np.argmin(ranges))
    mx     = int(np.argmax(ranges))

    fig.add_trace(go.Scatter(
        x=list(dates) + list(dates)[::-1],
        y=list(uppers) + list(lowers)[::-1],
        fill='toself', fillcolor='rgba(0,0,255,0.06)',
        line=dict(color='rgba(255,255,255,0)'), name='85% CI'))

    if lowers_20 is not None and uppers_20 is not None:
        fig.add_trace(go.Scatter(
            x=list(dates) + list(dates)[::-1],
            y=list(uppers_20) + list(lowers_20)[::-1],
            fill='toself', fillcolor='rgba(0,0,255,0.12)',
            line=dict(color='rgba(255,255,255,0)'), name='20% CI'))

    fig.add_trace(go.Scatter(x=dates, y=uppers, mode='lines',
        line=dict(color='green', dash='dash', width=1.2), name='Upper 85%'))
    fig.add_trace(go.Scatter(x=dates, y=lowers, mode='lines',
        line=dict(color='red',   dash='dash', width=1.2), name='Lower 85%'))
    fig.add_trace(go.Scatter(x=dates, y=means, mode='lines',
        line=dict(color='purple', width=2), name='Directional core'))
    fig.add_trace(go.Scatter(x=dates, y=actuals, mode='markers+lines',
        line=dict(color='black', width=1), marker=dict(size=3), name='Actual'))

    is_pts = y_label != 'Log return'
    r_fmt  = lambda v: f"{v:.1f} pts" if is_pts else f"{v*100:.2f}%"

    fig.add_trace(go.Scatter(x=[dates[mx]], y=[uppers[mx]],
        mode='markers', marker=dict(size=12, symbol='star', color='darkorange'),
        name='Widest day'))
    fig.add_annotation(x=dates[mx], y=uppers[mx],
        text=f"Max {r_fmt(ranges[mx])}", showarrow=True, ax=0, ay=-38,
        font=dict(color='darkorange', size=10))

    fig.add_trace(go.Scatter(x=[dates[mi]], y=[lowers[mi]],
        mode='markers', marker=dict(size=12, symbol='star', color='gold'),
        name='Tightest day'))
    fig.add_annotation(x=dates[mi], y=lowers[mi],
        text=f"Min {r_fmt(ranges[mi])}", showarrow=True, ax=0, ay=38,
        font=dict(color='goldenrod', size=10))

    fig.update_layout(title=title, xaxis_title='Prediction date (T)',
        yaxis_title=y_label, hovermode='x unified',
        template='plotly_white', height=600)
    fig.show()


_plot_wf(wf_dates_1d, act_lr, lo85_lr, hi85_lr, m_lr,
         "PLOT 1: 1D Ahead Forecast — Log Returns (85% + 20% CI)",
         "Log return", lowers_20=lo20_lr, uppers_20=hi20_lr)

_plot_wf(wf_dates_1d, act_px, lo85_px, hi85_px, m_px,
         "PLOT 2: 1D Ahead Forecast — Nifty 50 Index Points (Spot_Close based)",
         "Nifty 50 (pts)", lowers_20=lo20_px, uppers_20=hi20_px)

# ================================================================================
# CELL 7 — STATISTICAL TEST SUITE  (EXTENDED)
# Tests: DM | Conditional Coverage | Rank IC | Kupiec | Directional | Zone
#      + PIT | CRPS | Mincer-Zarnowitz | OOS-R² | Block-Bootstrap DM
#      + MCS | Economic Value | Regime Stratification
# ================================================================================

import numpy as np
from scipy import stats as scipy_stats

# Dynamically calculate alpha from CONFIG
_CI_ALPHA = (100 - CONFIG["outer_ci_pct"]) / 100.0
_Z_85     = float(scipy_stats.norm.ppf(1 - _CI_ALPHA / 2))


# ══════════════════════════════════════════════════════════════════════════════
# SHARED HELPERS
# ══════════════════════════════════════════════════════════════════════════════

def _winkler_obs(actual, lower, upper, alpha=_CI_ALPHA):
    """Per-observation Winkler interval score."""
    w  = upper - lower
    pl = np.where(actual < lower, (2 / alpha) * (lower - actual), 0.0)
    pu = np.where(actual > upper, (2 / alpha) * (actual - upper), 0.0)
    return w + pl + pu

def _naive_bands(vols_ann, horizon_days):
    """Symmetric rolling-vol naive CI (zero-mean, annualised vol)."""
    per_period_sigma = vols_ann / np.sqrt(252) * np.sqrt(horizon_days)
    return -_Z_85 * per_period_sigma, +_Z_85 * per_period_sigma

def _get_lu(series):
    """Return (lower, upper) arrays, preferring *_out variants."""
    return (series.get("lowers_out", series.get("lowers")),
            series.get("uppers_out", series.get("uppers")))

def _model_sigma(series):
    """Per-period σ inferred from CI half-width: σ = width / (2·Z)."""
    l, u = _get_lu(series)
    return np.maximum((u - l) / (2.0 * _Z_85), 1e-10)

def _block_draw(d, block_size, rng):
    """Single circular block-bootstrap resample of 1-D array d."""
    n        = len(d)
    n_blocks = int(np.ceil(n / block_size))
    starts   = rng.integers(0, n, size=n_blocks)          # circular wrap
    idx      = np.concatenate(
        [np.arange(s, s + block_size) % n for s in starts]
    )[:n]
    return d[idx]


# ══════════════════════════════════════════════════════════════════════════════
# EXISTING TESTS  (unchanged)
# ══════════════════════════════════════════════════════════════════════════════

def dm_test(series, horizon_days, alpha=_CI_ALPHA, label=""):
    a, l, u, v = (series["actuals"],
                  series.get("lowers_out", series.get("lowers")),
                  series.get("uppers_out", series.get("uppers")),
                  series["vols_ann"])
    n = len(a)
    l_model = _winkler_obs(a, l, u, alpha)
    nl, nu  = _naive_bands(v, horizon_days)
    l_naive = _winkler_obs(a, nl, nu, alpha)
    d     = l_model - l_naive
    d_bar = float(np.mean(d))
    lag   = max(horizon_days - 1, 0)
    gamma = np.var(d, ddof=1)
    for k in range(1, lag + 1):
        gk = float(np.mean((d[k:] - d_bar) * (d[:-k] - d_bar)))
        gamma += 2.0 * (1.0 - k / (lag + 1.0)) * gk
    se      = np.sqrt(max(gamma, 1e-15) / n)
    dm_stat = d_bar / se
    p_value = float(scipy_stats.t.sf(np.abs(dm_stat), df=n - 1) * 2)
    return {
        "label": label, "n": n, "horizon_days": horizon_days,
        "dm_stat":              round(float(dm_stat), 4),
        "p_value":              round(p_value, 5),
        "model_wins":           bool(dm_stat < 0 and p_value < 0.05),
        "directionally_better": bool(dm_stat < 0),
        "model_mean_wink":      round(float(np.mean(l_model)), 6),
        "naive_mean_wink":      round(float(np.mean(l_naive)), 6),
        "pct_days_model_wins":  round(float(np.mean(l_model < l_naive) * 100), 1),
        "mean_diff":            round(float(d_bar), 6),
    }

def conditional_coverage(series, n_quintiles=5, alpha=_CI_ALPHA, label=""):
    a      = series["actuals"]
    l, u   = series.get("lowers_out", series.get("lowers")), series.get("uppers_out", series.get("uppers"))
    widths = u - l
    hits   = (l <= a) & (a <= u)
    target = (1.0 - alpha) * 100
    edges  = np.percentile(widths, np.linspace(0, 100, n_quintiles + 1))
    rows   = []
    for i in range(n_quintiles):
        lo_e = edges[i]; hi_e = edges[i + 1]
        mask = (widths >= lo_e) if i == n_quintiles - 1 else ((widths >= lo_e) & (widths < hi_e))
        if mask.sum() == 0:
            continue
        hr_q   = float(hits[mask].mean() * 100)
        w_q    = float(widths[mask].mean() * 100)
        absa_q = float(np.abs(a[mask]).mean() * 100)
        eff_q  = float(widths[mask].mean() / (np.abs(a[mask]).mean() + 1e-9))
        rows.append({
            "quintile": i + 1, "n": int(mask.sum()),
            "width_range":      (round(float(edges[i] * 100), 3), round(float(edges[i + 1] * 100), 3)),
            "avg_width_pct":    round(w_q,    3),
            "hit_rate_pct":     round(hr_q,   2),
            "mean_abs_ret_pct": round(absa_q, 3),
            "width_eff":        round(eff_q,  3),
            "coverage_ok":      bool(hr_q >= target),
        })
    tight_ok = rows[0]["coverage_ok"] if rows else False
    return {
        "label": label, "target_hr": target,
        "q1_coverage_ok": tight_ok,
        "q1_hr": rows[0]["hit_rate_pct"] if rows else None,
        "quintiles": rows,
    }

def rank_ic_test(series, label=""):
    a      = series["actuals"]
    l, u   = series.get("lowers_out", series.get("lowers")), series.get("uppers_out", series.get("uppers"))
    widths = u - l
    n      = len(a)
    ic, p  = scipy_stats.spearmanr(widths, np.abs(a))
    t_stat = float(ic) * np.sqrt((n - 2) / max(1.0 - float(ic) ** 2, 1e-12))
    level  = "strong" if abs(float(ic)) > 0.20 else "moderate" if abs(float(ic)) > 0.10 else "weak"
    return {
        "label": label, "n": n,
        "rank_ic":    round(float(ic),     4),
        "p_value":    round(float(p),      5),
        "t_stat":     round(float(t_stat), 3),
        "skill_level": level,
        "significant": bool(float(p) < 0.05),
    }

def kupiec_test(series, alpha=_CI_ALPHA, label=""):
    a, l, u = (series["actuals"],
               series.get("lowers_out", series.get("lowers")),
               series.get("uppers_out", series.get("uppers")))
    n      = len(a)
    hits   = int(np.sum((l <= a) & (a <= u)))
    viols  = n - hits
    obs_vr = viols / n
    z_stat = (obs_vr - alpha) / np.sqrt(alpha * (1 - alpha) / n)
    try:
        binom_p = float(scipy_stats.binomtest(viols, n, alpha, alternative="two-sided").pvalue)
    except AttributeError:
        binom_p = float(scipy_stats.binom_test(viols, n, alpha, alternative="two-sided"))
    return {
        "label": label, "n": n,
        "expected_hr_pct":   round((1 - alpha) * 100, 1),
        "observed_hr_pct":   round(hits / n * 100, 2),
        "observed_viol_pct": round(obs_vr * 100,   2),
        "z_stat":            round(float(z_stat),   3),
        "binom_p":           round(binom_p,          5),
        "passes":            bool(binom_p > 0.05),
    }

def directional_test(series, label=""):
    actuals   = series["actuals"]
    forecasts = series["means"]
    n         = len(actuals)
    hits      = np.sum(np.sign(actuals) == np.sign(forecasts))
    acc       = hits / n
    try:
        p_value = float(scipy_stats.binomtest(int(hits), n, p=0.5, alternative="greater").pvalue)
    except AttributeError:
        p_value = float(scipy_stats.binom_test(int(hits), n, p=0.5, alternative="greater"))
    return {
        "label": label, "n": n,
        "hits":       int(hits),
        "accuracy":   round(acc * 100, 2),
        "p_value":    round(p_value,   5),
        "significant": bool(p_value < 0.05),
    }

def classify_zone(dm, cc, ic, kup, dr, label=""):
    dm_stat_neg = dm["dm_stat"] < 0
    dm_sig      = dm["p_value"] < 0.05
    q1_ok       = cc["q1_coverage_ok"]
    dir_sig     = dr["significant"]

    if dm_stat_neg and dm_sig and q1_ok:
        prefix = "" if dir_sig else "(Vol-only) "
        zone   = "A"
        desc   = (f"{prefix}Model beats naive. Q1 bands stable. "
                  f"Dir Acc: {dr['accuracy']}% ({'Sig' if dir_sig else 'Non-sig'})")
    elif dm_stat_neg and (not dm_sig or not q1_ok):
        zone = "A-"
        desc = "Model directionally tighter than naive but DM not significant or Q1 borderline."
    elif not dm_stat_neg and dm_sig:
        zone = "C"
        desc = "Model bands statistically wider than naive. Recalibrate variance head."
    else:
        zone = "B"
        desc = "No statistically detectable edge over rolling-vol naive."

    return {
        "label": label, "zone": zone, "description": desc,
        "dm_stat":             dm["dm_stat"],
        "dm_p":                dm["p_value"],
        "model_beats_naive":   dm["directionally_better"],
        "dm_significant":      bool(dm["model_wins"] or (dm["directionally_better"] and dm_sig)),
        "pct_days_model_wins": dm["pct_days_model_wins"],
        "q1_coverage_ok":      q1_ok,
        "q1_hr":               cc["q1_hr"],
        "kupiec_passes":       kup["passes"],
        "rank_ic":             ic["rank_ic"],
        "rank_ic_significant": ic["significant"],
        "dir_acc":             dr["accuracy"],
        "dir_sig":             dir_sig,
        "model_wink":          dm["model_mean_wink"],
        "naive_wink":          dm["naive_mean_wink"],
    }


# ══════════════════════════════════════════════════════════════════════════════
# NEW TESTS
# ══════════════════════════════════════════════════════════════════════════════

# ── [6]  PIT Uniformity Test ─────────────────────────────────────────────────

def pit_test(series, alpha=_CI_ALPHA, label="", n_bins=10):
    """
    Probability Integral Transform (PIT) uniformity test.

    PIT_t = Φ((actual_t − μ_t) / σ_t).  Under ideal calibration PITs ~ U(0,1).
    σ is recovered from the CI half-width.

    Reports:
      • Kolmogorov-Smirnov test against U(0,1)
      • Chi-squared uniformity test (equal-frequency bins)
      • Dispersion diagnosis: over → bands too narrow, under → too wide
    """
    a     = series["actuals"]
    mu    = series["means"]
    sigma = _model_sigma(series)
    n     = len(a)

    pits = scipy_stats.norm.cdf(a, loc=mu, scale=sigma)

    ks_stat, ks_p = scipy_stats.kstest(pits, "uniform")

    hist, edges = np.histogram(pits, bins=n_bins, range=(0.0, 1.0))
    expected    = n / n_bins
    chi2_stat, chi2_p = scipy_stats.chisquare(hist, f_exp=np.full(n_bins, expected))

    # For U(0,1): std = 1/√12 ≈ 0.2887
    ideal_std = 1.0 / np.sqrt(12.0)
    std_pit   = float(np.std(pits))
    if std_pit > ideal_std * 1.05:
        dispersion = "over"     # more surprises than calibrated → bands too narrow
    elif std_pit < ideal_std * 0.95:
        dispersion = "under"    # fewer surprises → bands too wide / over-conservative
    else:
        dispersion = "ok"

    return {
        "label": label, "n": n,
        "ks_stat":      round(float(ks_stat),  4),
        "ks_p":         round(float(ks_p),     5),
        "chi2_stat":    round(float(chi2_stat), 4),
        "chi2_p":       round(float(chi2_p),    5),
        "uniform_ks":   bool(ks_p   > 0.05),
        "uniform_chi2": bool(chi2_p > 0.05),
        "mean_pit":     round(float(np.mean(pits)), 4),
        "std_pit":      round(std_pit,              4),
        "ideal_std":    round(ideal_std,            4),
        "dispersion":   dispersion,
        "pits":         pits,
        "hist":         hist.tolist(),
        "bin_edges":    edges.tolist(),
    }


# ── [7]  CRPS ────────────────────────────────────────────────────────────────

def crps_test(series, horizon_days=1, alpha=_CI_ALPHA, label=""):
    """
    Continuous Ranked Probability Score for Gaussian predictive distributions.

    Closed-form Gaussian CRPS:
        CRPS(N(μ,σ), y) = σ · [ z·(2Φ(z)−1) + 2φ(z) − 1/√π ]
        where z = (y − μ) / σ.

    Compares model vs zero-mean naive (rolling vol).
    Skill score > 0 means model has lower CRPS (better probabilistic forecast).
    """
    a  = series["actuals"]
    mu = series["means"]
    v  = series["vols_ann"]
    n  = len(a)

    sigma_model = _model_sigma(series)
    sigma_naive = np.maximum(v / np.sqrt(252) * np.sqrt(horizon_days), 1e-10)

    def _g_crps(y, mu_f, sig_f):
        z   = (y - mu_f) / sig_f
        Phi = scipy_stats.norm.cdf(z)
        phi = scipy_stats.norm.pdf(z)
        return sig_f * (z * (2.0 * Phi - 1.0) + 2.0 * phi - 1.0 / np.sqrt(np.pi))

    crps_m = _g_crps(a, mu,              sigma_model)
    crps_n = _g_crps(a, np.zeros_like(a), sigma_naive)   # naive: zero-mean forecast

    mean_m = float(np.mean(crps_m))
    mean_n = float(np.mean(crps_n))
    skill  = 1.0 - mean_m / max(mean_n, 1e-15)

    # Paired t-test on per-observation CRPS difference
    diff   = crps_m - crps_n
    t_stat = float(np.mean(diff)) / max(float(np.std(diff, ddof=1)) / np.sqrt(n), 1e-15)
    p_val  = float(scipy_stats.t.sf(np.abs(t_stat), df=n - 1) * 2)

    return {
        "label": label, "n": n,
        "mean_crps_model":  round(mean_m,  6),
        "mean_crps_naive":  round(mean_n,  6),
        "crps_skill_score": round(skill,   4),
        "t_stat":           round(t_stat,  4),
        "p_value":          round(p_val,   5),
        "model_better":     bool(skill > 0),
        "significant":      bool(p_val < 0.05 and skill > 0),
    }


# ── [8]  Mincer-Zarnowitz Regression ─────────────────────────────────────────

def mincer_zarnowitz_test(series, label=""):
    """
    Mincer-Zarnowitz (1969) efficiency regression.

    Regresses actual_t on forecast_t:  actual = α + β·forecast + ε.
    Rational / efficient forecasts satisfy H₀: α = 0 AND β = 1 jointly (F-test).

    Reports individual t-tests, joint F-test, and in-regression R².
    """
    a = series["actuals"]
    f = series["means"]
    n = len(a)

    X    = np.column_stack([np.ones(n), f])
    beta = np.linalg.lstsq(X, a, rcond=None)[0]
    alpha_hat, beta_hat = float(beta[0]), float(beta[1])

    resid = a - X @ beta
    s2    = float(np.sum(resid ** 2)) / max(n - 2, 1)

    try:
        XtX_inv = np.linalg.inv(X.T @ X)
    except np.linalg.LinAlgError:
        XtX_inv = np.linalg.pinv(X.T @ X)

    cov  = s2 * XtX_inv
    se_a = float(np.sqrt(max(cov[0, 0], 0.0)))
    se_b = float(np.sqrt(max(cov[1, 1], 0.0)))

    t_a = alpha_hat      / max(se_a, 1e-15)
    t_b = (beta_hat - 1.0) / max(se_b, 1e-15)
    p_a = float(scipy_stats.t.sf(np.abs(t_a), df=n - 2) * 2)
    p_b = float(scipy_stats.t.sf(np.abs(t_b), df=n - 2) * 2)

    # Joint F-test: H₀: [α, β] = [0, 1]
    r_vec  = beta - np.array([0.0, 1.0])                 # deviation from null
    F_stat = float(r_vec @ np.linalg.solve(cov, r_vec)) / 2.0
    p_F    = float(scipy_stats.f.sf(max(F_stat, 0.0), 2, n - 2))

    ss_res = float(np.sum(resid ** 2))
    ss_tot = float(np.sum((a - np.mean(a)) ** 2))
    r2     = 1.0 - ss_res / max(ss_tot, 1e-15)

    return {
        "label": label, "n": n,
        "alpha":      round(alpha_hat, 6),
        "beta":       round(beta_hat,  4),
        "se_alpha":   round(se_a,      6),
        "se_beta":    round(se_b,      4),
        "t_alpha":    round(t_a,       3),
        "t_beta":     round(t_b,       3),
        "p_alpha":    round(p_a,       5),
        "p_beta":     round(p_b,       5),
        "F_stat":     round(F_stat,    4),
        "p_F":        round(p_F,       5),
        "r2":         round(r2,        4),
        "passes":     bool(p_F > 0.05),
        "alpha_zero": bool(p_a > 0.05),
        "beta_one":   bool(p_b > 0.05),
    }


# ── [9]  OOS R² (Campbell-Thompson + Clark-West) ─────────────────────────────

def oos_r2_test(series, label=""):
    """
    Out-of-sample R² (Campbell & Thompson 2008).

    OOS-R² = 1 − MSE_model / MSE_benchmark
    Benchmark: zero-mean forecast (historical mean ≈ 0 for returns).

    Also runs the Clark-West (2007) MSPE-adjusted t-test which corrects for the
    upward bias of the null benchmark's MSPE under H₀ of equal predictability.
    CW test is one-sided: H₁ that model beats the benchmark.
    """
    a  = series["actuals"]
    f  = series["means"]
    n  = len(a)

    mse_m  = float(np.mean((a - f) ** 2))
    mse_b  = float(np.mean(a ** 2))                 # benchmark: ŷ = 0
    oos_r2 = 1.0 - mse_m / max(mse_b, 1e-15)

    # Clark-West series: (a − 0)² − [(a − f)² − f²]
    cw_series = a ** 2 - ((a - f) ** 2 - f ** 2)
    cw_mean   = float(np.mean(cw_series))
    cw_se     = float(np.std(cw_series, ddof=1)) / np.sqrt(n)
    cw_stat   = cw_mean / max(cw_se, 1e-15)
    cw_p      = float(scipy_stats.t.sf(cw_stat, df=n - 1))    # one-sided

    return {
        "label": label, "n": n,
        "mse_model":             round(mse_m,  8),
        "mse_benchmark":         round(mse_b,  8),
        "oos_r2":                round(oos_r2, 4),
        "cw_stat":               round(cw_stat, 4),
        "cw_p":                  round(cw_p,    5),
        "model_beats_zero_mean": bool(oos_r2 > 0),
        "cw_significant":        bool(cw_p < 0.05),
    }


# ── [10]  Block-Bootstrap DM ─────────────────────────────────────────────────

def block_bootstrap_dm(series, horizon_days, alpha=_CI_ALPHA, label="",
                       n_boot=2000, block_size=None, seed=42):
    """
    Block-bootstrap Diebold-Mariano test (Künsch 1989 / Liu & Singh 1992).

    Resamples the Winkler loss differential with overlapping circular blocks,
    giving more reliable p-values than the analytical HAC-DM test — especially
    in small samples or when the loss differential is heavy-tailed or persistent.

    block_size defaults to n^(1/3) (rule of thumb), floored at max(horizon_days, 2).
    """
    rng     = np.random.default_rng(seed)
    a, v    = series["actuals"], series["vols_ann"]
    l, u    = _get_lu(series)
    n       = len(a)

    if block_size is None:
        block_size = max(int(round(n ** (1.0 / 3.0))), max(horizon_days, 2))

    l_model = _winkler_obs(a, l, u, alpha)
    nl, nu  = _naive_bands(v, horizon_days)
    l_naive = _winkler_obs(a, nl, nu, alpha)
    d       = l_model - l_naive
    d_bar   = float(np.mean(d))

    boot_means = np.array([
        float(np.mean(_block_draw(d, block_size, rng))) for _ in range(n_boot)
    ])
    centered = boot_means - float(np.mean(boot_means))   # re-centre under H₀

    p_two = float(np.mean(np.abs(centered) >= np.abs(d_bar)))
    p_one = float(np.mean(centered <= d_bar)) if d_bar < 0 else 1.0

    ci_lo = float(np.percentile(boot_means, 2.5))
    ci_hi = float(np.percentile(boot_means, 97.5))

    return {
        "label": label, "n": n,
        "n_boot":              n_boot,
        "block_size":          block_size,
        "mean_loss_diff":      round(d_bar, 6),
        "p_boot_two_sided":    round(p_two, 4),
        "p_boot_one_sided":    round(p_one, 4),
        "boot_ci_lo":          round(ci_lo, 6),
        "boot_ci_hi":          round(ci_hi, 6),
        "model_wins_boot":     bool(d_bar < 0 and p_two < 0.05),
        "directionally_better": bool(d_bar < 0),
    }


# ── [11]  Model Confidence Set (2-model) ─────────────────────────────────────

def mcs_test(series, horizon_days, alpha=_CI_ALPHA, label="",
             n_boot=2000, block_size=None, seed=42):
    """
    Model Confidence Set — Hansen, Lunde & Nason (2011), 2-model edition.

    Constructs t_R = d̄ / se_boot(d̄) from the Winkler loss differential d = L_model − L_naive.
    Uses block-bootstrap critical values. Significance level fixed at 10% (standard MCS
    convention). At this level:
      • p_MCS > 0.10  → both models survive (no significant loss difference)
      • p_MCS ≤ 0.10  → the model with the higher mean loss is eliminated.
    """
    rng     = np.random.default_rng(seed)
    a, v    = series["actuals"], series["vols_ann"]
    l, u    = _get_lu(series)
    n       = len(a)

    if block_size is None:
        block_size = max(int(round(n ** (1.0 / 3.0))), max(horizon_days, 2))

    l_model = _winkler_obs(a, l, u, alpha)
    nl, nu  = _naive_bands(v, horizon_days)
    l_naive = _winkler_obs(a, nl, nu, alpha)
    d       = l_model - l_naive
    d_bar   = float(np.mean(d))

    boot_d_bars = np.array([
        float(np.mean(_block_draw(d, block_size, rng))) for _ in range(n_boot)
    ])
    var_boot = float(np.var(boot_d_bars - np.mean(boot_d_bars), ddof=0))
    se_boot  = np.sqrt(max(var_boot, 1e-15))
    t_R      = d_bar / se_boot

    # Bootstrap distribution of t under H₀ (re-centred)
    boot_t = (boot_d_bars - float(np.mean(boot_d_bars))) / se_boot
    p_mcs  = float(np.mean(np.abs(boot_t) >= np.abs(t_R)))

    if p_mcs <= 0.10:
        model_in = bool(d_bar <= 0)    # survives if it has the lower loss
        naive_in = bool(d_bar > 0)
        conclusion = "Naive eliminated (model lower loss)" if d_bar < 0 else "Model eliminated (naive lower loss)"
    else:
        model_in = True
        naive_in = True
        conclusion = "Both models in MCS — no significant loss difference at 10%"

    return {
        "label": label, "n": n,
        "block_size":      block_size,
        "t_R":             round(t_R,   4),
        "p_mcs":           round(p_mcs, 5),
        "model_in_mcs":    model_in,
        "naive_in_mcs":    naive_in,
        "conclusion":      conclusion,
        "mean_loss_model": round(float(np.mean(l_model)), 6),
        "mean_loss_naive": round(float(np.mean(l_naive)), 6),
    }


# ── [12]  Economic Value ──────────────────────────────────────────────────────

def economic_value_test(series, horizon_days=1, alpha=_CI_ALPHA, label="",
                        risk_aversion=3.0, tc_bps=10):
    """
    Economic value analysis — Cenesizoglu & Timmermann (2012) style.

    Mean-variance optimal position:  w_t = clip( μ_t / (γ·σ²_t) , −1, 1 )
    Three benchmarks:
      • Model strategy (above)
      • Buy-and-hold  (w = 1, invested always)
      • Cash          (w = 0, risk-free)

    Certainty-equivalent return (CEQ) = E[r] − (γ/2)·Var[r], annualised × 252.
    Economic value (EV) = CEQ_model − CEQ_benchmark.
    Transaction costs (tc_bps) applied on |Δw| per period.
    """
    a  = series["actuals"]
    mu = series["means"]
    n  = len(a)

    sigma_m = _model_sigma(series)
    tc      = tc_bps / 10_000.0

    w_m  = np.clip(mu / np.maximum(risk_aversion * sigma_m ** 2, 1e-10), -1.0, 1.0)

    tc_m  = tc * np.abs(np.diff(np.concatenate([[0.0], w_m])))
    tc_bh = tc * np.array([1.0] + [0.0] * (n - 1))

    ret_m  = w_m * a - tc_m
    ret_bh = 1.0 * a - tc_bh
    ret_c  = np.zeros(n)

    def _ceq_ann(r):
        return (float(np.mean(r)) - 0.5 * risk_aversion * float(np.var(r, ddof=1))) * 252

    def _sharpe_ann(r):
        s = float(np.std(r, ddof=1))
        return float(np.mean(r)) / s * np.sqrt(252) if s > 1e-10 else 0.0

    def _max_dd(r):
        cum  = np.cumprod(1.0 + np.maximum(r, -0.9999))
        peak = np.maximum.accumulate(cum)
        return float(np.min((cum - peak) / np.maximum(peak, 1e-10)))

    ceq_m  = _ceq_ann(ret_m)
    ceq_bh = _ceq_ann(ret_bh)

    return {
        "label": label, "n": n,
        "risk_aversion":          risk_aversion,
        "tc_bps":                 tc_bps,
        "sharpe_model":           round(_sharpe_ann(ret_m),  3),
        "sharpe_bh":              round(_sharpe_ann(ret_bh), 3),
        "ceq_model_ann_pct":      round(ceq_m  * 100, 3),
        "ceq_bh_ann_pct":         round(ceq_bh * 100, 3),
        "ceq_cash_ann_pct":       0.0,
        "ev_vs_bh_ann_pct":       round((ceq_m - ceq_bh) * 100, 3),
        "ev_vs_cash_ann_pct":     round(ceq_m * 100,            3),
        "mean_abs_position":      round(float(np.mean(np.abs(w_m))), 3),
        "max_drawdown_model_pct": round(_max_dd(ret_m)  * 100, 2),
        "max_drawdown_bh_pct":    round(_max_dd(ret_bh) * 100, 2),
        "model_beats_bh":         bool(ceq_m > ceq_bh),
        "model_beats_cash":       bool(ceq_m > 0.0),
    }


# ── [13]  Regime-Conditional Stratification ──────────────────────────────────

def regime_stratification(series, horizon_days=1, alpha=_CI_ALPHA, label="",
                           n_vol_regimes=3):
    """
    Regime-conditional performance stratification.

    Splits the test set into three regime families:
      (A) Volatility regimes  — equal-count buckets of rolling realised vol.
      (B) Market direction    — up-return vs down-return days.
      (C) Tail vs normal days — |return| above/below the 90th percentile.

    For each regime reports: coverage (hit rate), model vs naive Winkler score,
    Winkler ratio (<1 = model better), and directional accuracy.
    """
    a    = series["actuals"]
    l, u = _get_lu(series)
    f    = series["means"]
    v    = series["vols_ann"]
    target_hr = (1.0 - alpha) * 100

    # ── (A) Volatility regimes ────────────────────────────────────────────────
    vol_edges = np.percentile(v, np.linspace(0, 100, n_vol_regimes + 1))
    _vol_labels = {
        3: ["Low Vol",  "Mid Vol",  "High Vol"],
        4: ["Low Vol",  "Mid-Low",  "Mid-High", "High Vol"],
    }.get(n_vol_regimes, [f"Vol-Q{i+1}" for i in range(n_vol_regimes)])

    vol_rows = []
    for i in range(n_vol_regimes):
        if i < n_vol_regimes - 1:
            mask = (v >= vol_edges[i]) & (v < vol_edges[i + 1])
        else:
            mask = v >= vol_edges[i]
        if mask.sum() < 5:
            continue
        a_r, l_r, u_r, f_r, v_r = a[mask], l[mask], u[mask], f[mask], v[mask]
        hit_r  = float(np.mean((l_r <= a_r) & (a_r <= u_r)) * 100)
        wink_m = float(np.mean(_winkler_obs(a_r, l_r, u_r, alpha)))
        nl_r, nu_r = _naive_bands(v_r, horizon_days)
        wink_n = float(np.mean(_winkler_obs(a_r, nl_r, nu_r, alpha)))
        dir_r  = float(np.mean(np.sign(a_r) == np.sign(f_r)) * 100)
        vol_rows.append({
            "regime":        _vol_labels[i],
            "n":             int(mask.sum()),
            "vol_range_pct": (round(float(vol_edges[i]     * 100), 1),
                              round(float(vol_edges[i + 1] * 100), 1)),
            "hit_rate_pct":  round(hit_r,  2),
            "mean_winkler":  round(wink_m, 6),
            "naive_winkler": round(wink_n, 6),
            "wink_ratio":    round(wink_m / max(wink_n, 1e-15), 4),  # <1 → model better
            "dir_acc_pct":   round(dir_r,  2),
            "coverage_ok":   bool(hit_r >= target_hr),
            "beats_naive":   bool(wink_m < wink_n),
        })

    # ── (B) Market direction regimes ─────────────────────────────────────────
    dir_rows = []
    for mask, name in [(a > 0,  "Up Days   (ret > 0)"),
                       (a <= 0, "Down Days (ret ≤ 0)")]:
        if mask.sum() < 5:
            continue
        a_r, l_r, u_r, f_r = a[mask], l[mask], u[mask], f[mask]
        hit_r = float(np.mean((l_r <= a_r) & (a_r <= u_r)) * 100)
        dir_r = float(np.mean(np.sign(a_r) == np.sign(f_r)) * 100)
        dir_rows.append({
            "regime":       name,
            "n":            int(mask.sum()),
            "hit_rate_pct": round(hit_r, 2),
            "dir_acc_pct":  round(dir_r, 2),
            "coverage_ok":  bool(hit_r >= target_hr),
        })

    # ── (C) Tail vs normal days ───────────────────────────────────────────────
    tail_thresh = float(np.percentile(np.abs(a), 90))
    tail_rows   = []
    for mask, name in [(np.abs(a) > tail_thresh,  "Tail Days   (|ret| > P90)"),
                       (np.abs(a) <= tail_thresh, "Normal Days (|ret| ≤ P90)")]:
        if mask.sum() < 5:
            continue
        a_r, l_r, u_r, f_r, v_r = a[mask], l[mask], u[mask], f[mask], v[mask]
        hit_r  = float(np.mean((l_r <= a_r) & (a_r <= u_r)) * 100)
        wink_m = float(np.mean(_winkler_obs(a_r, l_r, u_r, alpha)))
        nl_r, nu_r = _naive_bands(v_r, horizon_days)
        wink_n = float(np.mean(_winkler_obs(a_r, nl_r, nu_r, alpha)))
        dir_r  = float(np.mean(np.sign(a_r) == np.sign(f_r)) * 100)
        tail_rows.append({
            "regime":        name,
            "n":             int(mask.sum()),
            "hit_rate_pct":  round(hit_r,  2),
            "mean_winkler":  round(wink_m, 6),
            "naive_winkler": round(wink_n, 6),
            "wink_ratio":    round(wink_m / max(wink_n, 1e-15), 4),
            "dir_acc_pct":   round(dir_r,  2),
            "coverage_ok":   bool(hit_r >= target_hr),
            "beats_naive":   bool(wink_m < wink_n),
        })

    return {
        "label":             label,
        "target_hr":         target_hr,
        "vol_regimes":       vol_rows,
        "direction_regimes": dir_rows,
        "tail_regimes":      tail_rows,
    }


print(
    "Test suite loaded:\n"
    "  [ORIG]  dm_test | conditional_coverage | rank_ic_test | kupiec_test | "
    "directional_test | classify_zone\n"
    "  [NEW]   pit_test | crps_test | mincer_zarnowitz_test | oos_r2_test | "
    "block_bootstrap_dm | mcs_test | economic_value_test | regime_stratification"
)

