import sys, io
from datetime import datetime
from pathlib import Path

class _TeeWriter:
    def __init__(self, original, buffer):
        self._orig = original; self._buf = buffer
    def write(self, text):
        self._orig.write(text); self._buf.write(text)
    def flush(self):
        self._orig.flush(); self._buf.flush()
    def __getattr__(self, attr):
        return getattr(self._orig, attr)

_output_buf  = io.StringIO()
_orig_stdout = sys.stdout
sys.stdout   = _TeeWriter(sys.stdout, _output_buf)


def _print_battery(series, horizon_days, label):
    SEP2 = "-" * 76
    DOTS = "·" * 50
    n_obs = len(series["actuals"])

    print(f"\n{SEP2}")
    print(f"  {label}  |  n = {n_obs}  |  {horizon_days}D horizon")
    print(SEP2)
    if n_obs < 30:
        print("  ** Sample too small for reliable inference — results shown but flagged **")

    dm  = dm_test(series, horizon_days, label=label)
    cc  = conditional_coverage(series, label=label)
    ic  = rank_ic_test(series, label=label)
    kup = kupiec_test(series, label=label)
    dr  = directional_test(series, label=label)
    zn  = classify_zone(dm, cc, ic, kup, dr, label=label)

    pit = pit_test(series, label=label)
    cr  = crps_test(series, horizon_days=horizon_days, label=label)
    mz  = mincer_zarnowitz_test(series, label=label)
    r2  = oos_r2_test(series, label=label)
    bb  = block_bootstrap_dm(series, horizon_days, label=label)
    mcs = mcs_test(series, horizon_days, label=label)
    ev  = economic_value_test(series, horizon_days=horizon_days, label=label)
    rg  = regime_stratification(series, horizon_days=horizon_days, label=label)

    # [1] DM
    arrow = "<" if dm["dm_stat"] < 0 else ">"
    sig   = "SIGNIFICANT" if dm["p_value"] < 0.05 else "not significant"
    print(f"\n  [1] Diebold-Mariano  (model {arrow} naive rolling-vol)  [{sig}]")
    print(f"      DM stat   : {dm['dm_stat']:+.4f}   p = {dm['p_value']:.5f}")
    print(f"      Model mean Winkler : {dm['model_mean_wink']:.6f}"
          f"   Naive mean Winkler : {dm['naive_mean_wink']:.6f}")
    print(f"      Days model tighter : {dm['pct_days_model_wins']:.1f}%")

    # [2] Conditional Coverage
    print(f"\n  [2] Conditional Coverage by Width Quintile  "
          f"(target HR = {cc['target_hr']:.0f}%)")
    print(f"      {'Q':<4} {'n':>6} {'Avg Width':>12} {'Hit Rate':>10} "
          f"{'Mean|Ret|':>11} {'Eff':>7} {'OK?':>5}")
    print(f"      {'-'*56}")
    for r in cc["quintiles"]:
        flag = "  <-- KEY" if r["quintile"] == 1 else ""
        ok   = "YES" if r["coverage_ok"] else " NO"
        print(f"      Q{r['quintile']:<3} {r['n']:>6} "
              f"  {r['avg_width_pct']:>9.3f}%  {r['hit_rate_pct']:>8.2f}%  "
              f"{r['mean_abs_ret_pct']:>9.3f}%  {r['width_eff']:>6.2f}  {ok:>4}{flag}")

    # [3] Rank IC
    stars = {"strong": "***", "moderate": "**", "weak": "*"}
    print(f"\n  [3] Rank IC  (width vs |return|, {ic['skill_level']} {stars[ic['skill_level']]})")
    print(f"      Spearman IC : {ic['rank_ic']:+.4f}   t = {ic['t_stat']:+.3f}   "
          f"p = {ic['p_value']:.5f}   "
          f"({'significant' if ic['significant'] else 'not significant'})")

    # ── NEW: HL Range IC ──────────────────────────────────────────────────────
    _hl_arr = series.get("hl_ranges", None)
    if _hl_arr is not None and len(_hl_arr) > 0:
        _hl = np.asarray(_hl_arr, dtype=np.float32)
        _ow = np.asarray(series.get("uppers_out", series.get("uppers"))) - \
              np.asarray(series.get("lowers_out", series.get("lowers")))
        _vm = _hl > 1e-5
        if int(_vm.sum()) > 10:
            from scipy.stats import spearmanr
            _hl_ic_v, _hl_p_v = spearmanr(_ow[_vm], _hl[_vm])
            _hl_ic_v, _hl_p_v = float(_hl_ic_v), float(_hl_p_v)
            _sig_hl_v = f"p={_hl_p_v:.4f} ({'sig' if _hl_p_v < 0.05 else 'n.s.'})"
        else:
            _hl_ic_v, _sig_hl_v = float('nan'), "n/a"
        print(f"      HL Range IC : {_hl_ic_v:+.4f}   ({_sig_hl_v})"
              f"  ← width vs next-day log(H/L) range")
    # ─────────────────────────────────────────────────────────────────────────

    # [4] Kupiec
    pass_str = "PASS" if kup["passes"] else "FAIL"
    print(f"\n  [4] Kupiec Coverage Test  [{pass_str}]")
    print(f"      Expected HR : {kup['expected_hr_pct']:.1f}%  |  "
          f"Observed HR : {kup['observed_hr_pct']:.2f}%  |  "
          f"z = {kup['z_stat']:+.3f}  |  p = {kup['binom_p']:.5f}")

    # [5] Directional Accuracy
    sig_str = "SIGNIFICANT" if dr["significant"] else "not significant"
    print(f"\n  [5] Directional Accuracy (Midpoint vs Actual)")
    print(f"      Accuracy : {dr['accuracy']}%   n = {dr['n']}   hits = {dr['hits']}")
    print(f"      p-value  : {dr['p_value']:.5f}   ({sig_str} vs 50% baseline)")

    # [6] PIT
    ks_tag = "UNIFORM" if pit["uniform_ks"] else "NON-UNIFORM"
    print(f"\n  [6] PIT Uniformity Test  [{ks_tag}]")
    print(f"      KS   stat : {pit['ks_stat']:.4f}   p = {pit['ks_p']:.5f}"
          f"   ({'uniform' if pit['uniform_ks']   else 'non-uniform'})")
    print(f"      Chi² stat : {pit['chi2_stat']:.4f}   p = {pit['chi2_p']:.5f}"
          f"   ({'uniform' if pit['uniform_chi2'] else 'non-uniform'})")
    print(f"      PIT mean  : {pit['mean_pit']:.4f}   std : {pit['std_pit']:.4f}"
          f"   (ideal ≈ {pit['ideal_std']:.4f})   "
          f"Dispersion : {pit['dispersion'].upper()}")
    _disp_hint = {
        "over":  "  → bands too NARROW: more extreme outcomes than calibrated",
        "under": "  → bands too WIDE: over-conservative intervals",
        "ok":    "  → dispersion consistent with stated coverage level",
    }
    print(f"      {_disp_hint[pit['dispersion']]}")

    # [7] CRPS
    cr_dir = "BETTER" if cr["model_better"] else "WORSE"
    cr_sig = "SIGNIFICANT" if cr["significant"] else "not significant"
    print(f"\n  [7] CRPS Skill Score  [model {cr_dir} than naive]  [{cr_sig}]")
    print(f"      Model CRPS  : {cr['mean_crps_model']:.6f}"
          f"   Naive CRPS : {cr['mean_crps_naive']:.6f}")
    print(f"      Skill score : {cr['crps_skill_score']:+.4f}"
          f"   t = {cr['t_stat']:+.4f}   p = {cr['p_value']:.5f}")

    # [8] Mincer-Zarnowitz
    mz_tag = "PASS" if mz["passes"] else "FAIL"
    print(f"\n  [8] Mincer-Zarnowitz Regression  "
          f"[joint H₀: α=0, β=1  →  {mz_tag}]")
    print(f"      α = {mz['alpha']:+.6f}  (se={mz['se_alpha']:.6f})"
          f"  t = {mz['t_alpha']:+.3f}  p = {mz['p_alpha']:.5f}"
          f"  {'✓ unbiased' if mz['alpha_zero'] else '✗ BIAS'}")
    print(f"      β = {mz['beta']:+.4f}     (se={mz['se_beta']:.4f})"
          f"  t(β−1) = {mz['t_beta']:+.3f}  p = {mz['p_beta']:.5f}"
          f"  {'✓ slope=1' if mz['beta_one'] else '✗ SLOPE≠1'}")
    print(f"      F(α=0,β=1) = {mz['F_stat']:.4f}   p = {mz['p_F']:.5f}"
          f"   In-sample R² = {mz['r2']:.4f}")

    # [9] OOS R²
    r2_tag = "POSITIVE ✓" if r2["model_beats_zero_mean"] else "NEGATIVE ✗"
    cw_tag = "SIGNIFICANT" if r2["cw_significant"] else "not significant"
    print(f"\n  [9] OOS R²  [{r2_tag}]")
    print(f"      OOS R² = {r2['oos_r2']:+.4f}"
          f"   MSE_model : {r2['mse_model']:.8f}"
          f"   MSE_bench(0) : {r2['mse_benchmark']:.8f}")
    print(f"      Clark-West stat : {r2['cw_stat']:+.4f}"
          f"   p = {r2['cw_p']:.5f}   [{cw_tag}]")

    # [10] Block-Bootstrap DM
    bb_tag = "SIGNIFICANT ✓" if bb["model_wins_boot"] else "not significant"
    print(f"\n  [10] Block-Bootstrap DM"
          f"  [block={bb['block_size']}, B={bb['n_boot']}]  [{bb_tag}]")
    print(f"       Mean loss diff  : {bb['mean_loss_diff']:+.6f}"
          f"   p(2-sided) = {bb['p_boot_two_sided']:.4f}"
          f"   p(1-sided) = {bb['p_boot_one_sided']:.4f}")
    print(f"       95% CI of d̄   : [{bb['boot_ci_lo']:+.6f},  {bb['boot_ci_hi']:+.6f}]")

    # [11] MCS
    print(f"\n  [11] Model Confidence Set  (α = 10%, block={mcs['block_size']})")
    print(f"       t_R = {mcs['t_R']:+.4f}   p_MCS = {mcs['p_mcs']:.5f}")
    print(f"       Model in MCS : {'YES ✓' if mcs['model_in_mcs'] else ' NO ✗'}"
          f"   |   Naive in MCS : {'YES' if mcs['naive_in_mcs'] else ' NO'}")
    print(f"       {mcs['conclusion']}")

    # [12] Economic Value
    ev_tag = "BEATS B&H ✓" if ev["model_beats_bh"] else "below B&H"
    print(f"\n  [12] Economic Value  "
          f"[γ={ev['risk_aversion']}, tc={ev['tc_bps']} bps]  [{ev_tag}]")
    print(f"       Sharpe (ann)  — Model : {ev['sharpe_model']:+.3f}"
          f"   B&H : {ev['sharpe_bh']:+.3f}")
    print(f"       CEQ (ann)     — Model : {ev['ceq_model_ann_pct']:+.3f}%"
          f"   B&H : {ev['ceq_bh_ann_pct']:+.3f}%"
          f"   Cash : {ev['ceq_cash_ann_pct']:+.3f}%")
    print(f"       EV vs B&H : {ev['ev_vs_bh_ann_pct']:+.3f}%"
          f"   EV vs Cash : {ev['ev_vs_cash_ann_pct']:+.3f}%")
    print(f"       Max DD — Model : {ev['max_drawdown_model_pct']:.2f}%"
          f"   B&H : {ev['max_drawdown_bh_pct']:.2f}%"
          f"   Mean |w| : {ev['mean_abs_position']:.3f}")

    # [13] Regime Stratification
    tgt = rg["target_hr"]
    print(f"\n  [13] Regime-Conditional Stratification  (target HR = {tgt:.0f}%)")
    _hdr = f"  {'Regime':<26} {'n':>5}  {'Vol Range':>12}  {'HR':>7}  " \
           f"{'Wink_m':>9}  {'Wink_n':>9}  {'Ratio':>6}  {'DirAcc':>7}  {'OK?':>4}"
    print(f"\n       -- (A) Volatility Regimes --")
    print(f"       {_hdr.strip()}")
    print(f"       {'-'*92}")
    for r in rg["vol_regimes"]:
        ok = "YES" if r["coverage_ok"] else " NO"
        bt = " ◀" if r["beats_naive"] else "  "
        vr = f"{r['vol_range_pct'][0]:>4.1f}–{r['vol_range_pct'][1]:<4.1f}%"
        print(f"       {r['regime']:<26} {r['n']:>5}  {vr:>12}  "
              f"{r['hit_rate_pct']:>6.2f}%  "
              f"{r['mean_winkler']:>9.6f}  {r['naive_winkler']:>9.6f}  "
              f"{r['wink_ratio']:>6.3f}  "
              f"{r['dir_acc_pct']:>6.2f}%  {ok:>4}{bt}")

    print(f"\n       -- (B) Market Direction --")
    print(f"       {'Regime':<30} {'n':>5}  {'HR':>7}  {'DirAcc':>7}  {'OK?':>4}")
    print(f"       {'-'*56}")
    for r in rg["direction_regimes"]:
        ok = "YES" if r["coverage_ok"] else " NO"
        print(f"       {r['regime']:<30} {r['n']:>5}  "
              f"{r['hit_rate_pct']:>6.2f}%  {r['dir_acc_pct']:>6.2f}%  {ok:>4}")

    print(f"\n       -- (C) Tail vs Normal --")
    print(f"       {'Regime':<30} {'n':>5}  {'HR':>7}  {'Wink_m':>9}  "
          f"{'Wink_n':>9}  {'Ratio':>6}  {'DirAcc':>7}  {'OK?':>4}")
    print(f"       {'-'*80}")
    for r in rg["tail_regimes"]:
        ok = "YES" if r["coverage_ok"] else " NO"
        bt = " ◀" if r["beats_naive"] else "  "
        print(f"       {r['regime']:<30} {r['n']:>5}  "
              f"{r['hit_rate_pct']:>6.2f}%  "
              f"{r['mean_winkler']:>9.6f}  {r['naive_winkler']:>9.6f}  "
              f"{r['wink_ratio']:>6.3f}  "
              f"{r['dir_acc_pct']:>6.2f}%  {ok:>4}{bt}")

    zone_badges = {"A": "[ ZONE A  ]", "A-": "[ ZONE A- ]",
                   "B": "[ ZONE B  ]", "C":  "[ ZONE C  ]"}
    print(f"\n  {DOTS}")
    print(f"  CLASSIFICATION  {zone_badges.get(zn['zone'], zn['zone'])}")
    print(f"  {zn['description']}")
    print(f"  {DOTS}")

    return {
        "dm": dm, "cc": cc, "ic": ic, "kup": kup, "dr": dr, "zone": zn,
        "pit": pit, "crps": cr, "mz": mz, "r2": r2,
        "bb": bb, "mcs": mcs, "ev": ev, "rg": rg,
    }


SEP = "=" * 76

def _row(label, hz, zn, batt=None, n=None, hl_ic=None):
    n_tag   = f" [n={n}]" if n and n < 50 else ""
    q1hr    = f"{zn['q1_hr']:.1f}%" if zn["q1_hr"] is not None else "  N/A"
    kup     = "PASS" if zn["kupiec_passes"] else "FAIL"
    dir_str = f"{zn['dir_acc']}%{'*' if zn['dir_sig'] else ''}"

    if batt is not None:
        crps_s = f"{batt['crps']['crps_skill_score']:+.3f}"
        osr2   = f"{batt['r2']['oos_r2']:+.4f}"
        bb_p   = f"{batt['bb']['p_boot_two_sided']:.4f}"
        pit_u  = "OK " if batt["pit"]["uniform_ks"] else "NG "
        mcs_m  = "IN " if batt["mcs"]["model_in_mcs"] else "OUT"
        ev_bh  = f"{batt['ev']['ev_vs_bh_ann_pct']:+.2f}%"
    else:
        crps_s = "  N/A"; osr2 = "   N/A"; bb_p = "  N/A"
        pit_u  = "N/A"; mcs_m = "N/A"; ev_bh = "  N/A"

    # NEW: HL Range IC column
    hl_str = f"{hl_ic:+.3f}" if hl_ic is not None and not np.isnan(hl_ic) else "  N/A"

    print(
        f"{label+n_tag:<38} {str(hz)+'D':>3} {zn['zone']:<6} "
        f"{zn['dm_p']:>8.4f} {q1hr:>7} {kup:>5} {dir_str:>8} "
        f"{zn['rank_ic']:>+7.4f} {zn['pct_days_model_wins']:>7.1f}% "
        f"{crps_s:>7} {osr2:>8} {bb_p:>7} {pit_u:>4} {mcs_m:>4} {ev_bh:>8} "
        f"{hl_str:>7}"   # NEW
    )


# ── PART A — RANDOM OOS: PER-RUN ──────────────────────────────────────────────
print(f"\n{SEP}\nPART A — RANDOM OOS: PER-RUN\n{SEP}")
rng_run_results = []
for res in pipeline_results:
    r1 = _print_battery(res["series_1d"], horizon_days=1,
                        label=f"Random OOS Run {res['run']} · 1D")
    rng_run_results.append({"run": res["run"], "1d": r1,
                             "hl_ic": res.get("hl_range_ic_1d", float('nan'))})

# ── PART B — RANDOM OOS: POOLED ───────────────────────────────────────────────
print(f"\n{SEP}\nPART B — RANDOM OOS: POOLED (all runs concatenated)\n{SEP}")
pool_1d = {
    "actuals":    np.concatenate([r["series_1d"]["actuals"]  for r in pipeline_results]),
    "lowers_out": np.concatenate([r["series_1d"].get("lowers_out", r["series_1d"].get("lowers")) for r in pipeline_results]),
    "uppers_out": np.concatenate([r["series_1d"].get("uppers_out", r["series_1d"].get("uppers")) for r in pipeline_results]),
    "means":      np.concatenate([r["series_1d"]["means"]    for r in pipeline_results]),
    "vols_ann":   np.concatenate([r["series_1d"]["vols_ann"] for r in pipeline_results]),
    "hl_ranges":  np.concatenate([r["series_1d"].get("hl_ranges", np.zeros(len(r["series_1d"]["actuals"]))) for r in pipeline_results]),  # NEW
}
pool_r1 = _print_battery(pool_1d, horizon_days=1, label="Pooled Random OOS · 1D")
_pool_hl_ic = float(np.mean([r.get("hl_range_ic_1d", float('nan'))
                              for r in pipeline_results
                              if not np.isnan(r.get("hl_range_ic_1d", float('nan')))]))

# ── PART C — WALK-FORWARD: PER FOLD ───────────────────────────────────────────
print(f"\n{SEP}\nPART C — WALK-FORWARD: PER FOLD\n{SEP}")
wf_fold_results = []
for s1 in wf_series_1d:
    fold = s1["fold"]
    if s1["tiny"]:
        print(f"\n  [Fold {fold} SKIPPED — n < {WF_CONFIG['min_test_obs']}, unreliable]")
        continue
    r1 = _print_battery(s1, horizon_days=1, label=f"WF Fold {fold} · 1D")
    _fold_hl_ic = wf_results[fold-1].get("hl_range_ic_1d", float('nan')) if fold <= len(wf_results) else float('nan')
    wf_fold_results.append({"fold": fold, "1d": r1, "hl_ic": _fold_hl_ic})

# ── PART D — WALK-FORWARD CONTINUOUS ──────────────────────────────────────────
print(f"\n{SEP}\nPART D — WALK-FORWARD CONTINUOUS  *** PRIMARY SIGNAL ***\n{SEP}")
wf_cont_r1 = _print_battery(wf_continuous_1d, horizon_days=1,
                             label="WF Continuous · 1D  [PRIMARY]")

# ── MASTER SUMMARY ─────────────────────────────────────────────────────────────
print(f"\n{SEP}\nMASTER SUMMARY — ZONE CLASSIFICATIONS + EXTENDED METRICS\n{SEP}")

_hdr = (
    f"{'Source':<38} {'Hz':>3} {'Zone':<6} {'DM_p':>8} {'Q1HR':>7} "
    f"{'Kup':>5} {'DirAcc':>8} {'RankIC':>7} {'%BeatNv':>8} "
    f"{'CRPS_S':>7} {'OOS_R²':>8} {'BB_p':>7} {'PIT':>4} {'MCS':>4} "
    f"{'EV_BH':>8} {'HL_IC':>7}"   # NEW column
)
print(_hdr)
print("-" * len(_hdr))

for r in rng_run_results:
    _row(f"Rnd OOS Run {r['run']}", 1, r["1d"]["zone"], batt=r["1d"],
         hl_ic=r.get("hl_ic"))

_row("Pooled Random OOS", 1, pool_r1["zone"], batt=pool_r1,
     n=len(pool_1d["actuals"]), hl_ic=_pool_hl_ic)

for r in wf_fold_results:
    _row(f"WF Fold {r['fold']}", 1, r["1d"]["zone"], batt=r["1d"],
         hl_ic=r.get("hl_ic"))

print(f"{'':->76}")
_row("WF Continuous  [PRIMARY]", 1, wf_cont_r1["zone"], batt=wf_cont_r1,
     n=len(wf_continuous_1d["actuals"]),
     hl_ic=_hl_ic_wf if '_hl_ic_wf' in dir() else float('nan'))

print(f"""
Column guide:
  DM_p    Analytical HAC Diebold-Mariano p-value (two-sided)
  Q1HR    Hit-rate in tightest quintile (target = {100*(1-((100-CONFIG['outer_ci_pct'])/100)):.0f}%)
  Kup     Kupiec unconditional coverage binomial test
  DirAcc  Directional accuracy (* = significant vs 50%)
  RankIC  Spearman rank IC (width vs |return|)
#   %BeatNv % of days model Winkler < naive Winkler
  CRPS_S  CRPS skill score vs zero-mean naive (>0 = better)
  OOS_R²  Out-of-sample R² vs zero-mean benchmark
  BB_p    Block-bootstrap DM p-value (two-sided)
  PIT     OK = KS test cannot reject U(0,1)  |  NG = non-uniform
  MCS     Model Confidence Set membership (IN / OUT at α=10%)
  EV_BH   Economic value vs buy-and-hold (ann. CEQ, % p.a.)
  HL_IC   Spearman IC: outer band width vs next-day log(H/L) range  [NEW]

Zone key:
  A  = DM significant + Q1 coverage ≥ {100*(1-((100-CONFIG['outer_ci_pct'])/100)):.0f}% → trade
  A- = directionally better but not yet significant → paper-trade
  B  = no detectable edge over rolling-vol naive
  C  = statistically worse than naive → recalibrate
{SEP}""")

# ── Restore stdout and save ────────────────────────────────────────────────────
sys.stdout = _orig_stdout
_saved     = _output_buf.getvalue()
_results_dir = Path("/content/drive/MyDrive/Model Results")
_results_dir.mkdir(parents=True, exist_ok=True)
_ts        = datetime.now().strftime("%Y%m%d_%H%M%S")
_save_path = _results_dir / f"nifty_1d_s9_results_{_ts}.txt"
with open(_save_path, "w", encoding="utf-8") as _fh:
    _fh.write(_saved)
print(f"\nResults saved: {_save_path}")

